INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct, client_needs_category, client_needs_subcategory, nursing_subject, body_system, topic, subtopic, difficulty, bloom_level, tags, marks, is_published, is_builder_visible, is_free_sample, batch_id, question_ref
) VALUES
('NCLEX_MCQ_399001', 'MCQ', 'A nurse is caring for an older adult client who is confused and attempting to climb out of bed. Which action should the nurse take FIRST?', 'The least restrictive intervention that addresses immediate safety is chosen before restraints.', '{"options":[{"id":"A","text":"Apply soft wrist restraints"},{"id":"B","text":"Stay with the client and remove nearby hazards"},{"id":"C","text":"Administer a prescribed sedative"},{"id":"D","text":"Raise all four side rails"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Restraints require a provider order and are a last resort.","B":"Correct. The least restrictive action addresses the immediate risk.","C":"Incorrect. Chemical restraint requires an order and is not first.","D":"Incorrect. Four raised side rails are considered a restraint."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Fall prevention', 'Restraint alternatives', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_399001', 'TF', 'A client with a blood pressure of 85/50 mmHg and a heart rate of 120 bpm is likely experiencing compensatory shock.', 'Tachycardia with hypotension reflects the compensatory stage of shock.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Shock', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311001', 'MCQ', 'A nurse is caring for a bedbound client who cannot reposition independently. To prevent pressure injuries, how often should the nurse reposition the client?', 'Repositioning an immobile client at least every 2 hours is the standard measure to prevent pressure injuries.', '{"options":[{"id":"A","text":"Every 2 hours"},{"id":"B","text":"Every 8 hours"},{"id":"C","text":"Once per shift"},{"id":"D","text":"Only when the client requests it"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Repositioning at least every 2 hours relieves prolonged pressure over bony prominences.","B":"Incorrect. This interval is far too long and allows tissue ischemia.","C":"Incorrect. This does not relieve pressure often enough.","D":"Incorrect. An immobile client may not sense the need."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure-injury prevention', 'Repositioning', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311002', 'MCQ', 'A nurse is administering a continuous enteral feeding through a nasogastric tube. To reduce the risk of aspiration, the nurse should keep the head of the bed elevated to at least which position?', 'Keeping the head of the bed at 30 to 45 degrees during and after enteral feeding minimizes aspiration.', '{"options":[{"id":"A","text":"30 to 45 degrees"},{"id":"B","text":"Flat (0 degrees)"},{"id":"C","text":"10 degrees"},{"id":"D","text":"Prone position"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevating the head of the bed 30 to 45 degrees reduces reflux and aspiration risk.","B":"Incorrect. Lying flat increases aspiration risk.","C":"Incorrect. This is not high enough to reduce reflux.","D":"Incorrect. Prone positioning is inappropriate during feeding."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral tube feeding', 'Aspiration prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311003', 'MCQ', 'A nurse teaches a client with left-leg weakness how to use a cane. On which side should the client hold the cane?', 'A cane is held on the stronger side, opposite the affected leg, to widen the base of support.', '{"options":[{"id":"A","text":"The right (stronger) side"},{"id":"B","text":"The left (weaker) side"},{"id":"C","text":"Either side, whichever feels comfortable"},{"id":"D","text":"In front of the body with both hands"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The cane is held on the stronger side to provide support opposite the weak leg.","B":"Incorrect. Holding it on the weak side does not offload the affected leg.","C":"Incorrect. Correct placement affects stability and safety.","D":"Incorrect. A standard cane is held in one hand."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Cane use', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311004', 'MCQ', 'A nurse is assessing pain in an alert adult client. Which is considered the most reliable indicator of the client''s pain?', 'For an alert client, the client''s self-report is the most reliable measure of pain.', '{"options":[{"id":"A","text":"The client''s self-report of pain"},{"id":"B","text":"The client''s vital signs"},{"id":"C","text":"The nurse''s observation of behavior"},{"id":"D","text":"The family''s description of pain"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Self-report is the single most reliable indicator of pain.","B":"Incorrect. Vital signs are supportive but not the most reliable.","C":"Incorrect. Behavior is used mainly when self-report is unavailable.","D":"Incorrect. Family report is secondary to the client''s own report."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Pain assessment', 'Self-report', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311005', 'MCQ', 'A nurse is recording intake and output for a client. Which item should be documented as intake?', 'Substances liquid at room temperature, including gelatin, ice cream, and broth, are counted as fluid intake.', '{"options":[{"id":"A","text":"Gelatin dessert eaten at lunch"},{"id":"B","text":"Emesis of 100 mL"},{"id":"C","text":"Urine of 250 mL"},{"id":"D","text":"Liquid stool"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Foods that are liquid at room temperature, such as gelatin, count as fluid intake.","B":"Incorrect. Emesis is recorded as output.","C":"Incorrect. Urine is output.","D":"Incorrect. Liquid stool is recorded as output."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', 'Measurement', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311006', 'MCQ', 'A nurse wants to promote sleep for a hospitalized client without using medication. Which nonpharmacologic intervention is most appropriate?', 'Dimming lights and clustering care reduce nighttime disruptions and support restful sleep.', '{"options":[{"id":"A","text":"Dim the lights and cluster nighttime care"},{"id":"B","text":"Offer a caffeinated beverage in the evening"},{"id":"C","text":"Schedule vital signs every hour overnight"},{"id":"D","text":"Keep the television on for background noise"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reducing light and grouping care minimizes sleep interruptions.","B":"Incorrect. Caffeine interferes with sleep.","C":"Incorrect. Frequent interruptions disrupt sleep.","D":"Incorrect. Noise and light can impair sleep."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Nonpharmacologic comfort', 'Environment', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311007', 'MCQ', 'A nurse is providing postmortem care shortly after a client''s death. Which action should the nurse take to prevent discoloration of the face?', 'Elevating the head slightly during postmortem care prevents blood pooling and facial discoloration.', '{"options":[{"id":"A","text":"Elevate the head of the bed slightly"},{"id":"B","text":"Place the body flat with the head lowered"},{"id":"C","text":"Turn the body prone"},{"id":"D","text":"Remove the pillow entirely"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Slight head elevation prevents pooling of blood and facial discoloration.","B":"Incorrect. A lowered head promotes facial discoloration.","C":"Incorrect. Prone positioning is inappropriate.","D":"Incorrect. Leaving the head flat can cause discoloration."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Postmortem care', 'Body positioning', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311008', 'MCQ', 'A nurse performs passive range-of-motion exercises for an immobile client. What is the primary purpose of this intervention?', 'Passive range of motion maintains joint flexibility and prevents contractures in immobile clients.', '{"options":[{"id":"A","text":"To maintain joint mobility and prevent contractures"},{"id":"B","text":"To increase the client''s muscle strength"},{"id":"C","text":"To replace the need for repositioning"},{"id":"D","text":"To measure the client''s pain tolerance"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Passive ROM keeps joints flexible and prevents contractures.","B":"Incorrect. Passive ROM does not build strength.","C":"Incorrect. Repositioning is still required.","D":"Incorrect. That is not the purpose of ROM."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Range of motion', 'Passive ROM', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311009', 'MCQ', 'A nurse is preparing to give a bed bath to a client. Which action best preserves the client''s dignity and privacy?', 'Providing privacy by closing the door and keeping the client draped preserves dignity during personal care.', '{"options":[{"id":"A","text":"Close the door and keep the client covered except the area being washed"},{"id":"B","text":"Leave the curtain open to allow staff to assist quickly"},{"id":"C","text":"Uncover the entire body for efficiency"},{"id":"D","text":"Discuss the client''s condition with visitors during the bath"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Closing the door and draping maintains privacy and dignity.","B":"Incorrect. This exposes the client unnecessarily.","C":"Incorrect. Full exposure compromises dignity.","D":"Incorrect. This violates privacy and confidentiality."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Dignity and privacy', 'Personal care', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311010', 'MCQ', 'A postoperative client has not voided for 8 hours and reports lower abdominal fullness. Which nonpharmacologic action should the nurse try first to promote voiding?', 'Noninvasive measures such as running water and warmth are tried first to stimulate voiding before catheterization.', '{"options":[{"id":"A","text":"Run warm water over the client''s hands or turn on running water"},{"id":"B","text":"Insert an indwelling urinary catheter immediately"},{"id":"C","text":"Restrict the client''s oral fluids"},{"id":"D","text":"Tell the client to wait until the urge is stronger"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sensory cues such as running water can stimulate voiding.","B":"Incorrect. Catheterization requires an order and is not the first noninvasive step.","C":"Incorrect. Fluid restriction does not promote voiding.","D":"Incorrect. Delay can worsen retention."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bladder elimination', 'Urinary retention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311011', 'MCQ', 'A nurse cares for a client with a newly applied leg cast. Which assessment is the priority to monitor for complications?', 'Neurovascular assessment distal to a new cast detects impaired circulation and nerve compromise early.', '{"options":[{"id":"A","text":"Neurovascular status of the toes (color, warmth, movement, sensation)"},{"id":"B","text":"The client''s appetite"},{"id":"C","text":"The client''s sleep pattern"},{"id":"D","text":"The color of the cast material"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Neurovascular checks detect compromised circulation early.","B":"Incorrect. This is not the priority for a new cast.","C":"Incorrect. Not the priority.","D":"Incorrect. Cast color is not a complication indicator."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Cast care', 'Neurovascular checks', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311012', 'MCQ', 'A nurse assists an older adult with dysphagia at mealtime. Which action best promotes safe swallowing?', 'Upright positioning with small bites promotes safe swallowing in clients with dysphagia.', '{"options":[{"id":"A","text":"Position the client upright and encourage small bites"},{"id":"B","text":"Have the client lie back to relax"},{"id":"C","text":"Offer thin liquids rapidly to finish quickly"},{"id":"D","text":"Encourage the client to talk while eating"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Upright positioning and small bites reduce aspiration risk.","B":"Incorrect. A reclined position increases aspiration risk.","C":"Incorrect. Thin liquids and rushing increase aspiration risk.","D":"Incorrect. Talking while eating raises aspiration risk."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Nutrition', 'Feeding safety', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_311013', 'SATA', 'A nurse plans care to prevent pressure injuries in an immobile client. Which interventions are appropriate? Select all that apply.', 'Repositioning, skin hygiene, offloading, and regular skin inspection prevent pressure injuries; massaging reddened areas is contraindicated.', '{"options":[{"id":"A","text":"Reposition the client at least every 2 hours"},{"id":"B","text":"Keep the skin clean and dry"},{"id":"C","text":"Use pillows to offload bony prominences"},{"id":"D","text":"Massage vigorously over reddened bony areas"},{"id":"E","text":"Leave the client in one position to avoid disturbing sleep"},{"id":"F","text":"Inspect the skin regularly"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure-injury prevention', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_311014', 'SATA', 'A nurse plans nonpharmacologic comfort measures for a client with chronic pain. Which measures are appropriate? Select all that apply.', 'Guided imagery, heat/cold, repositioning, and distraction are nonpharmacologic comfort measures; the other options are not.', '{"options":[{"id":"A","text":"Guided imagery"},{"id":"B","text":"Application of heat or cold as prescribed"},{"id":"C","text":"Repositioning for comfort"},{"id":"D","text":"Distraction with music"},{"id":"E","text":"Withholding all fluids"},{"id":"F","text":"Placing the client on strict bed rest indefinitely"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic pain management', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_311015', 'SATA', 'A nurse is caring for a client receiving enteral tube feedings. Which nursing actions are appropriate? Select all that apply.', 'Elevating the head of the bed, verifying placement, and flushing the tube are correct; lying flat and using expired formula increase risk.', '{"options":[{"id":"A","text":"Keep the head of the bed elevated at least 30 degrees"},{"id":"B","text":"Verify tube placement before intermittent feedings"},{"id":"C","text":"Flush the tube with water as ordered"},{"id":"D","text":"Lay the client flat during the feeding"},{"id":"E","text":"Hang formula that has been open for 48 hours at room temperature"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral tube feeding', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_311016', 'SATA', 'A nurse assists a weak client with ambulation using a gait belt. Which actions are appropriate? Select all that apply.', 'A snug gait belt, nonskid footwear, and proper nurse positioning promote safe ambulation.', '{"options":[{"id":"A","text":"Apply the gait belt snugly around the client''s waist"},{"id":"B","text":"Ensure the client wears nonskid footwear"},{"id":"C","text":"Stand slightly behind and to the side of the client"},{"id":"D","text":"Pull the client forward by the arms to speed up walking"},{"id":"E","text":"Have the client walk in socks on a wet floor"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Fall and mobility safety', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_311017', 'SATA', 'A nurse teaches a client measures to promote normal bowel elimination and prevent constipation. Which measures should the nurse include? Select all that apply.', 'Fiber, fluids, and activity promote normal elimination; suppressing the urge and daily enemas are harmful.', '{"options":[{"id":"A","text":"Increase dietary fiber intake"},{"id":"B","text":"Drink adequate fluids"},{"id":"C","text":"Engage in regular physical activity"},{"id":"D","text":"Ignore the urge to defecate until convenient"},{"id":"E","text":"Use enemas daily as routine"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Bowel elimination', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_311018', 'TF', 'When measuring a client''s intake and output, ice chips should be recorded as approximately half of their measured volume.', 'Ice chips melt to roughly half their volume, so they are recorded as about 50 percent of the amount given.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_311019', 'SELECT_N', 'A nurse performs eye irrigation for a client with a chemical splash. Which 2 actions are appropriate?', 'Irrigate from inner to outer canthus with the head turned toward the affected side to avoid cross-contamination.', '{"options":[{"id":"A","text":"Direct the irrigating solution from the inner to the outer canthus"},{"id":"B","text":"Have the client turn the head toward the affected side"},{"id":"C","text":"Aim the stream directly onto the cornea with force"},{"id":"D","text":"Direct flow from the outer to the inner canthus"},{"id":"E","text":"Withhold irrigation until the provider arrives"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Eye irrigation', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_311020', 'MATRIX', 'For each item, click to specify whether it is recorded as intake or output.', 'Fluids taken in count as intake; urine and drainage count as output.', '{"row_label":"Item","rows":[{"id":"r1","text":"Apple juice consumed"},{"id":"r2","text":"Urine in the drainage bag"},{"id":"r3","text":"IV fluids infused"},{"id":"r4","text":"Wound drainage"},{"id":"r5","text":"Broth eaten at lunch"}],"columns":[{"id":"c1","text":"Intake"},{"id":"c2","text":"Output"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_311021', 'MATRIX_MR', 'For each comfort need, select all appropriate nonpharmacologic measures (may support more than one).', 'Each nonpharmacologic measure maps to the comfort needs it addresses.', '{"row_label":"Comfort measure","rows":[{"id":"r1","text":"Dimming the lights and reducing noise"},{"id":"r2","text":"Applying a warm compress as prescribed"},{"id":"r3","text":"Repositioning for comfort"},{"id":"r4","text":"Draping the client during a bath"}],"columns":[{"id":"c1","text":"Promotes sleep"},{"id":"c2","text":"Relieves pain"},{"id":"c3","text":"Preserves dignity"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c1","c2"],"r4":["c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic comfort', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_311022', 'CLOZE', 'When a client with weakness on one side climbs stairs with a cane, the {1} leg leads going up, and the {2} leg leads going down.', 'Up with the good (stronger) leg, down with the bad (weaker) leg is the rule for safe stair climbing.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"stronger"},{"id":"c2","text":"weaker"},{"id":"c3","text":"either"}]},{"id":"b2","choices":[{"id":"c1","text":"weaker"},{"id":"c2","text":"stronger"},{"id":"c3","text":"either"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_311023', 'HIGHLIGHT', 'The nurse inspects the skin of an immobile client. Highlight the findings that indicate an early pressure injury. Over the sacrum there is [[nonblanchable redness]]. The heels show [[intact, warm skin]]. There is an area of [[skin breakdown]] on the left hip. The forearm has a [[healed old scar]].', 'Nonblanchable redness and skin breakdown indicate pressure injury; intact skin and old scars do not.', '{"chunks":[{"id":"h1","text":"nonblanchable redness"},{"id":"h2","text":"intact, warm skin"},{"id":"h3","text":"skin breakdown"},{"id":"h4","text":"healed old scar"}]}'::jsonb, '{"correct_ids":["h1","h3"],"feedback":{"h1":"Nonblanchable redness is a stage 1 pressure injury.","h2":"Normal skin — not a pressure injury.","h3":"Open skin breakdown indicates tissue damage.","h4":"An old scar is not an early pressure injury."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure-injury assessment', NULL, 'Easy', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_311024', 'BOWTIE', 'A bedbound client is at risk for a pressure injury. Complete the diagram by selecting the priority actions, the client problem, and the parameters to monitor.', 'For pressure-injury risk, reposition and keep skin dry while monitoring skin and Braden Scale score.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Reposition every 2 hours"},{"id":"lt2","text":"Keep skin clean and dry"},{"id":"lt3","text":"Massage reddened bony areas"},{"id":"lt4","text":"Restrict all fluids"}]},"centre":{"label":"Client problem","tokens":[{"id":"ct1","text":"Risk for pressure injury"},{"id":"ct2","text":"Risk for hyperglycemia"},{"id":"ct3","text":"Risk for seizure"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Skin over bony prominences"},{"id":"rt2","text":"Braden Scale score"},{"id":"rt3","text":"Pupil size"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure-injury prevention', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_311025', 'DRAG_CLOZE', 'During enteral feeding, the nurse keeps the head of the bed elevated at least [1] degrees and verifies [2] before an intermittent feeding.', 'The head of the bed is kept at least 30 degrees, and tube placement is verified before feeding.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"30"},{"id":"t2","text":"tube placement"},{"id":"t3","text":"10"},{"id":"t4","text":"the client''s weight"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral tube feeding', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_311026', 'DRAG_ORDER', 'A nurse gives a complete bed bath. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Provide privacy and gather supplies"},{"id":"t2","text":"Wash the face and neck"},{"id":"t3","text":"Wash the arms, chest, and abdomen"},{"id":"t4","text":"Wash the legs and feet"},{"id":"t5","text":"Wash the perineal area last"},{"id":"t6","text":"Offer a snack"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Bed bath', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_311027', 'MCQ', 'A nurse offers a complementary therapy to help a client relax and reduce mild anxiety. Which is an example of a complementary relaxation therapy?', 'Deep-breathing and guided imagery are complementary, nonpharmacologic relaxation therapies.', '{"options":[{"id":"A","text":"Deep-breathing and guided imagery"},{"id":"B","text":"Administering an IV opioid"},{"id":"C","text":"Applying wrist restraints"},{"id":"D","text":"Inserting a urinary catheter"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are complementary relaxation therapies.","B":"Incorrect. This is a pharmacologic, not complementary, therapy.","C":"Incorrect. Restraints are not a comfort therapy.","D":"Incorrect. This is an invasive procedure, not a relaxation therapy."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Complementary therapies', 'Relaxation', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312001', 'MCQ', 'A nurse teaches a client with left-leg weakness how to use a cane. On which side should the client hold the cane?', 'A cane is held on the stronger side to provide support to the weaker leg.', '{"options":[{"id":"A","text":"On the right (stronger) side"},{"id":"B","text":"On the left (weaker) side"},{"id":"C","text":"In whichever hand feels more comfortable"},{"id":"D","text":"In front of the body with both hands"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The cane is held on the stronger side and advances with the weak leg.","B":"Incorrect. Holding it on the weak side does not offload the affected leg.","C":"Incorrect. Placement is based on the weak leg, not comfort.","D":"Incorrect. A cane is a single-hand device."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Cane use', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312002', 'MCQ', 'How often should a nurse reposition a bedbound client to help prevent pressure injuries?', 'The standard is to reposition an immobile client at least every 2 hours.', '{"options":[{"id":"A","text":"At least every 2 hours"},{"id":"B","text":"Once every shift"},{"id":"C","text":"Only when the client requests it"},{"id":"D","text":"Every 8 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Repositioning every 2 hours relieves pressure over bony prominences.","B":"Incorrect. This is far too infrequent to prevent tissue breakdown.","C":"Incorrect. Repositioning must be scheduled, not client-initiated.","D":"Incorrect. Prolonged pressure causes ischemia within a couple of hours."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', 'Repositioning', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312003', 'MCQ', 'A client is receiving a continuous enteral tube feeding. To reduce the risk of aspiration, how should the nurse position the client?', 'Keeping the head of the bed elevated 30-45 degrees during and after feeding prevents aspiration.', '{"options":[{"id":"A","text":"Head of bed elevated at least 30 degrees"},{"id":"B","text":"Flat and supine"},{"id":"C","text":"Left lateral (Sims) position"},{"id":"D","text":"Trendelenburg position"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevating the head of the bed reduces reflux and aspiration risk.","B":"Incorrect. Lying flat increases the risk of reflux and aspiration.","C":"Incorrect. This does not address vertical reflux risk during feeding.","D":"Incorrect. Head-down positioning increases aspiration risk."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Aspiration prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312004', 'MCQ', 'Which item should the nurse include when calculating a client''s fluid intake?', 'Foods that are liquid at room or body temperature (gelatin, ice cream, broth) count toward fluid intake.', '{"options":[{"id":"A","text":"Gelatin dessert eaten at lunch"},{"id":"B","text":"A slice of toast"},{"id":"C","text":"A scrambled egg"},{"id":"D","text":"A grilled chicken breast"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Gelatin is liquid at body temperature and counts as intake.","B":"Incorrect. Solid food is not counted as fluid intake.","C":"Incorrect. Solid food is not measured as fluid.","D":"Incorrect. Solid protein is not counted as fluid intake."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', 'Fluid measurement', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312005', 'MCQ', 'A nurse must assess pain in a nonverbal client with advanced dementia. Which tool is most appropriate?', 'For nonverbal clients, behavioral/observational pain scales assessing facial and body cues are appropriate.', '{"options":[{"id":"A","text":"A behavioral pain scale that observes facial expression and body movements"},{"id":"B","text":"The 0-10 numeric rating scale"},{"id":"C","text":"Asking the family to rate the pain from memory"},{"id":"D","text":"Waiting until the client can speak"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Observational/behavioral scales are used when a client cannot self-report.","B":"Incorrect. This requires the client to verbally rate pain.","C":"Incorrect. Direct observation of the client is more valid.","D":"Incorrect. Pain assessment should not be delayed."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Pain assessment', 'Nonverbal client', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312006', 'MCQ', 'While providing postmortem care, which action should the nurse take first after the client is pronounced dead?', 'Postmortem care includes providing privacy and family support along with respectful body preparation per policy.', '{"options":[{"id":"A","text":"Provide privacy and allow the family time with the body if they wish"},{"id":"B","text":"Immediately remove all tubes without checking policy"},{"id":"C","text":"Position the body face-down"},{"id":"D","text":"Discard the client''s belongings"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Supporting the grieving family with privacy is a priority in postmortem care.","B":"Incorrect. Removal depends on facility policy and any medical examiner involvement.","C":"Incorrect. The body is placed supine in normal alignment.","D":"Incorrect. Belongings are gathered and given to the family."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Postmortem care', 'Body preparation', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312007', 'MCQ', 'A nurse performs passive range-of-motion exercises for an immobile client. What is the primary purpose of these exercises?', 'Passive ROM maintains joint range and prevents contractures in clients who cannot move their joints actively.', '{"options":[{"id":"A","text":"To maintain joint mobility and prevent contractures"},{"id":"B","text":"To build large muscle mass"},{"id":"C","text":"To increase the client''s heart rate for exercise"},{"id":"D","text":"To replace the need for repositioning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Passive ROM preserves joint flexibility when the client cannot move independently.","B":"Incorrect. Passive ROM does not significantly increase muscle mass.","C":"Incorrect. This is not the goal of passive ROM.","D":"Incorrect. ROM does not replace pressure-relief repositioning."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Range of motion', 'Passive ROM', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312008', 'MCQ', 'A client reports constipation. Which nonpharmacologic measure should the nurse recommend first?', 'Increasing fiber, fluids, and activity are first-line nonpharmacologic interventions for constipation.', '{"options":[{"id":"A","text":"Increase dietary fiber and fluid intake"},{"id":"B","text":"Begin daily enemas"},{"id":"C","text":"Restrict all physical activity"},{"id":"D","text":"Limit fluid intake to reduce bloating"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Fiber and fluids are first-line nonpharmacologic measures for constipation.","B":"Incorrect. Routine enemas are not a first-line measure.","C":"Incorrect. Activity promotes peristalsis and helps relieve constipation.","D":"Incorrect. Reducing fluids worsens constipation."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Bowel elimination', 'Constipation', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312009', 'MCQ', 'A client with a newly applied plaster cast asks how to relieve itching under the cast. What should the nurse advise?', 'Cool air relieves itching under a cast safely; inserting objects risks skin injury and infection.', '{"options":[{"id":"A","text":"Direct cool air from a hair dryer set on the cool setting into the cast"},{"id":"B","text":"Insert a knitting needle to scratch the skin"},{"id":"C","text":"Pour lotion down inside the cast"},{"id":"D","text":"Remove padding at the cast edge to scratch"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cool air relieves itching without breaking the skin.","B":"Incorrect. Inserting objects can injure skin and cause infection.","C":"Incorrect. Moisture and lotion under a cast promote skin breakdown.","D":"Incorrect. Altering the cast is unsafe."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Orthopedic devices', 'Cast care', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312010', 'MCQ', 'A client reports difficulty falling asleep in the hospital. Which nonpharmacologic action should the nurse take first?', 'Reducing environmental stimulation is a first-line nonpharmacologic sleep-promotion measure.', '{"options":[{"id":"A","text":"Reduce noise and dim the lights during the night"},{"id":"B","text":"Offer a caffeinated beverage"},{"id":"C","text":"Schedule vital signs every hour through the night"},{"id":"D","text":"Encourage a long daytime nap"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Promoting a quiet, dark environment supports sleep.","B":"Incorrect. Caffeine is a stimulant that interferes with sleep.","C":"Incorrect. Frequent interruptions worsen sleep.","D":"Incorrect. Long daytime naps can disrupt nighttime sleep."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Sleep and rest', 'Sleep hygiene', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312011', 'MCQ', 'A postoperative client has not voided for 8 hours and reports lower abdominal fullness. Which nonpharmacologic action should the nurse try first to promote voiding?', 'Noninvasive measures such as warm water and the sound of running water stimulate voiding before catheterization.', '{"options":[{"id":"A","text":"Run warm water over the perineum or turn on a running faucet"},{"id":"B","text":"Insert an indwelling catheter immediately"},{"id":"C","text":"Restrict oral fluids"},{"id":"D","text":"Place the client flat and tell them to hold it"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sensory cues such as warm water and running water stimulate voiding.","B":"Incorrect. Catheterization is not the first step; try noninvasive measures first.","C":"Incorrect. Restricting fluids does not promote voiding.","D":"Incorrect. This does not relieve retention."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bladder elimination', 'Urinary retention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_312012', 'MCQ', 'While assisting a client with a bed bath, which action best preserves the client''s dignity?', 'Draping the client and exposing only the area being washed maintains dignity, privacy, and warmth.', '{"options":[{"id":"A","text":"Keep the client covered, exposing only the area being washed"},{"id":"B","text":"Leave the door open to save time"},{"id":"C","text":"Fully uncover the client for the entire bath"},{"id":"D","text":"Discuss the client''s care loudly with a passing coworker"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Draping and exposing only one area preserves dignity and warmth.","B":"Incorrect. An open door violates privacy.","C":"Incorrect. Full exposure is unnecessary and undignified.","D":"Incorrect. This breaches privacy and confidentiality."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Dignity and privacy', 'Personal care', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_312013', 'SATA', 'Which measures help prevent pressure injuries in an immobile client? Select all that apply.', 'Repositioning, clean dry skin, pressure-redistributing surfaces, and good nutrition prevent pressure injuries; massaging reddened areas is contraindicated.', '{"options":[{"id":"A","text":"Reposition at least every 2 hours"},{"id":"B","text":"Keep the skin clean and dry"},{"id":"C","text":"Use a pressure-redistributing mattress"},{"id":"D","text":"Massage vigorously over reddened bony prominences"},{"id":"E","text":"Keep the client in one position to avoid disturbing them"},{"id":"F","text":"Ensure adequate protein and fluid intake"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', 'Skin care', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_312014', 'SATA', 'Which are nonpharmacologic measures a nurse can use for pain relief? Select all that apply.', 'Heat/cold, imagery, positioning, and massage are nonpharmacologic; opioids and IV rate changes are not.', '{"options":[{"id":"A","text":"Applying heat or cold"},{"id":"B","text":"Guided imagery and relaxation breathing"},{"id":"C","text":"Repositioning for comfort"},{"id":"D","text":"Administering an opioid analgesic"},{"id":"E","text":"Massage"},{"id":"F","text":"Increasing the IV fluid rate"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Pain management', 'Nonpharmacologic', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_312015', 'SATA', 'Which nursing actions are appropriate when administering an enteral tube feeding? Select all that apply.', 'Verifying placement, elevating the head, flushing, and checking residuals are safe practices; expired formula and rapid infusion are not.', '{"options":[{"id":"A","text":"Verify tube placement before feeding"},{"id":"B","text":"Elevate the head of the bed at least 30 degrees"},{"id":"C","text":"Flush the tube with water per protocol"},{"id":"D","text":"Hang formula that has been at room temperature for 24 hours"},{"id":"E","text":"Check gastric residual per facility policy"},{"id":"F","text":"Administer the feeding rapidly by gravity bolus in under a minute"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Safe administration', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_312016', 'SATA', 'Which findings suggest that a client may have poor nutritional status? Select all that apply.', 'Weight loss, poor healing, brittle hair/nails, and muscle wasting indicate poor nutrition; good turgor and stable appetite are normal.', '{"options":[{"id":"A","text":"Unintended weight loss"},{"id":"B","text":"Poor wound healing"},{"id":"C","text":"Brittle hair and nails"},{"id":"D","text":"Firm, resilient skin turgor"},{"id":"E","text":"Muscle wasting"},{"id":"F","text":"Stable energy and appetite"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nutrition', 'Nutritional status', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_312017', 'SATA', 'Which instructions are correct when teaching a client to use a standard walker? Select all that apply.', 'Stable four-point contact, short advances, nonskid shoes, and slight elbow flexion are correct; leaning over the walker and using it on stairs are unsafe.', '{"options":[{"id":"A","text":"Keep all four legs of the walker on the floor before stepping"},{"id":"B","text":"Move the walker forward a short distance, then step to it"},{"id":"C","text":"Wear well-fitting, nonskid footwear"},{"id":"D","text":"Lean far over the front of the walker when walking"},{"id":"E","text":"Keep the elbows slightly flexed while gripping the handles"},{"id":"F","text":"Use the walker to climb stairs like a step stool"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Walker use', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_312018', 'SELECT_N', 'Which 3 sources should the nurse include when measuring a client''s fluid output?', 'Output includes urine, emesis, and liquid stool; oral and IV fluids are intake, and solid food is not measured.', '{"options":[{"id":"A","text":"Urine"},{"id":"B","text":"Emesis (vomit)"},{"id":"C","text":"Liquid stool (diarrhea)"},{"id":"D","text":"Oral fluids consumed"},{"id":"E","text":"IV fluids infused"},{"id":"F","text":"A solid meal eaten"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', 'Output measurement', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_312019', 'TF', 'Nonblanchable redness over the sacrum in an immobile client is an early sign of a stage 1 pressure injury.', 'Persistent, nonblanchable erythema over a bony prominence indicates a stage 1 pressure injury.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_312020', 'TF', 'The most reliable indicator of a client''s pain is the nurse''s judgment of how much pain the client should be feeling.', 'The client''s self-report is the most reliable indicator of pain, not the nurse''s judgment.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Pain assessment', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_312021', 'MATRIX', 'For each item, click to specify whether it is recorded as intake or output on the fluid balance record.', 'Fluids taken in (juice, gelatin, IV) are intake; urine and emesis are output.', '{"row_label":"Activity","rows":[{"id":"r1","text":"240 mL of apple juice"},{"id":"r2","text":"300 mL of urine"},{"id":"r3","text":"Cup of gelatin dessert"},{"id":"r4","text":"150 mL of emesis"},{"id":"r5","text":"IV fluid infused"}],"columns":[{"id":"c1","text":"Intake"},{"id":"c2","text":"Output"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_312022', 'MATRIX_MR', 'For each comfort or ADL measure, select all goals it helps achieve (may support more than one).', 'Repositioning and dry, smooth linens both comfort the client and protect skin; massage and warmth mainly promote comfort.', '{"row_label":"Task","rows":[{"id":"r1","text":"Repositioning every 2 hours"},{"id":"r2","text":"Keeping linens dry and wrinkle-free"},{"id":"r3","text":"Providing a back massage"},{"id":"r4","text":"Offering warm blankets"}],"columns":[{"id":"c1","text":"Promotes comfort"},{"id":"c2","text":"Prevents skin breakdown"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1","c2"],"r3":["c1"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'ADLs', NULL, 'Easy', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_312023', 'CLOZE', 'Before administering an intermittent tube feeding, the nurse should first {1}, and to reduce aspiration risk should keep the head of the bed elevated to at least {2}.', 'Tube placement is verified before feeding, and the head of the bed is kept at least 30 degrees to prevent aspiration.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"verify tube placement"},{"id":"c2","text":"clamp the tube for an hour"},{"id":"c3","text":"lay the client flat"}]},{"id":"b2","choices":[{"id":"c1","text":"30 degrees"},{"id":"c2","text":"10 degrees"},{"id":"c3","text":"0 degrees (flat)"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_312024', 'HIGHLIGHT', 'The nurse assesses an immobile client. Highlight the findings that increase this client''s risk for a pressure injury. The client is [[incontinent of urine]], has [[limited mobility]], reports [[good appetite with high protein intake]], has [[poor nutritional intake]], and has [[intact, well-hydrated skin]].', 'Incontinence, immobility, and poor nutrition raise pressure-injury risk; good nutrition and intact skin are protective.', '{"chunks":[{"id":"h1","text":"incontinent of urine"},{"id":"h2","text":"limited mobility"},{"id":"h3","text":"good appetite with high protein intake"},{"id":"h4","text":"poor nutritional intake"},{"id":"h5","text":"intact, well-hydrated skin"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"Moisture from incontinence increases skin breakdown risk.","h2":"Immobility causes prolonged pressure over bony areas.","h3":"Good nutrition is protective, not a risk factor.","h4":"Poor nutrition impairs skin integrity and healing.","h5":"Healthy skin is protective, not a risk factor."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_312025', 'BOWTIE', 'An immobile client is at risk for complications of immobility. Complete the diagram by selecting the problem, actions to take, and parameters to monitor.', 'Immobility is managed with repositioning and ROM, monitoring skin integrity and joint mobility.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Reposition every 2 hours"},{"id":"lt2","text":"Perform range-of-motion exercises"},{"id":"lt3","text":"Keep the client flat and still"},{"id":"lt4","text":"Restrict fluid intake"}]},"centre":{"label":"Problem","tokens":[{"id":"ct1","text":"Complications of immobility"},{"id":"ct2","text":"Acute myocardial infarction"},{"id":"ct3","text":"Hyperthyroidism"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Skin over bony prominences"},{"id":"rt2","text":"Joint range of motion"},{"id":"rt3","text":"Pupil size"},{"id":"rt4","text":"Bowel sounds only"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Mobility', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_312026', 'DRAG_CLOZE', 'When a client with left-leg weakness uses a cane, the cane is held in the [1] hand and advances together with the [2] leg.', 'The cane is held on the strong (right) side and moves with the weak (left) leg.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"right"},{"id":"t2","text":"left"},{"id":"t3","text":"dominant"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_312027', 'DRAG_ORDER', 'Place the steps for giving a client a bed bath in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Gather supplies and provide privacy"},{"id":"t2","text":"Wash the client''s face"},{"id":"t3","text":"Wash the arms, chest, and abdomen"},{"id":"t4","text":"Wash the legs and feet"},{"id":"t5","text":"Wash the perineal area last"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Skin care', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307001', 'MCQ', 'A nurse is teaching a healthy 65-year-old client about recommended vaccines. Which vaccine should the nurse recommend annually?', 'The influenza vaccine is recommended annually for all adults, especially older adults.', '{"options":[{"id":"A","text":"Influenza vaccine"},{"id":"B","text":"Tetanus (Td) booster"},{"id":"C","text":"MMR vaccine"},{"id":"D","text":"Hepatitis B vaccine"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Influenza vaccine is recommended every year.","B":"Incorrect. Td is given every 10 years.","C":"Incorrect. MMR is not given annually to adults.","D":"Incorrect. Hepatitis B is a series, not annual."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Immunizations', 'Adult schedule', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307002', 'MCQ', 'At which age does a nurse expect a healthy infant to sit without support?', 'Sitting without support is an expected milestone around 6 months of age.', '{"options":[{"id":"A","text":"2 months"},{"id":"B","text":"6 months"},{"id":"C","text":"12 months"},{"id":"D","text":"18 months"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Too early for unsupported sitting.","B":"Correct. Infants typically sit unsupported around 6 months.","C":"Incorrect. Children usually walk around this age.","D":"Incorrect. This is well past the expected milestone."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Infant milestones', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307003', 'MCQ', 'A nurse teaches a client planning pregnancy about preventing neural tube defects. Which supplement should the nurse emphasize?', 'Folic acid taken before and during early pregnancy reduces neural tube defect risk.', '{"options":[{"id":"A","text":"Folic acid"},{"id":"B","text":"Vitamin C"},{"id":"C","text":"Vitamin D"},{"id":"D","text":"Calcium"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Folic acid reduces the risk of neural tube defects.","B":"Incorrect. Vitamin C does not prevent neural tube defects.","C":"Incorrect. Vitamin D supports bone health, not neural tube closure.","D":"Incorrect. Calcium supports bone development, not neural tube closure."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Nutrition education', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307004', 'MCQ', 'A nurse counsels a 55-year-old woman about routine screening. Which screening test is recommended for breast cancer detection?', 'Mammography is the standard screening test for early breast cancer detection.', '{"options":[{"id":"A","text":"Mammography"},{"id":"B","text":"Colonoscopy"},{"id":"C","text":"Pap smear"},{"id":"D","text":"Bone density scan"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mammography screens for breast cancer.","B":"Incorrect. Colonoscopy screens for colorectal cancer.","C":"Incorrect. A Pap smear screens for cervical cancer.","D":"Incorrect. This screens for osteoporosis."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Reproductive', 'Targeted screening', 'Cancer screening', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307005', 'MCQ', 'A nurse teaches new parents about infant nutrition. Until what age is exclusive breastfeeding generally recommended?', 'Exclusive breastfeeding for about the first 6 months is recommended before introducing solids.', '{"options":[{"id":"A","text":"About 6 months"},{"id":"B","text":"2 weeks"},{"id":"C","text":"12 months"},{"id":"D","text":"2 years"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Exclusive breastfeeding is recommended for about the first 6 months.","B":"Incorrect. Far too early to add other foods.","C":"Incorrect. Solids are usually introduced around 6 months.","D":"Incorrect. This exceeds the exclusive breastfeeding period."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'GI', 'Newborn care', 'Infant nutrition', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307006', 'MCQ', 'A client who smokes asks about the benefit of quitting. Which is an accurate statement the nurse can share?', 'Smoking cessation reduces the risk of lung cancer, heart disease, and other conditions at any age.', '{"options":[{"id":"A","text":"Quitting lowers the risk of lung cancer and heart disease"},{"id":"B","text":"Quitting has no benefit after age 50"},{"id":"C","text":"Switching to light cigarettes eliminates risk"},{"id":"D","text":"Damage from smoking cannot be reduced by quitting"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cessation reduces multiple health risks.","B":"Incorrect. Benefits occur at any age.","C":"Incorrect. Light cigarettes still carry risk.","D":"Incorrect. Quitting improves health outcomes."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Respiratory', 'High-risk behavior education', 'Smoking cessation', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307007', 'MCQ', 'A nurse teaches an adult client about physical activity. Which weekly amount of moderate aerobic activity is generally recommended?', 'At least 150 minutes of moderate aerobic activity per week is recommended for adults.', '{"options":[{"id":"A","text":"At least 150 minutes"},{"id":"B","text":"About 20 minutes"},{"id":"C","text":"About 500 minutes"},{"id":"D","text":"No regular activity is needed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. About 150 minutes per week is recommended.","B":"Incorrect. This is well below the recommendation.","C":"Incorrect. This exceeds the standard recommendation.","D":"Incorrect. Regular activity is important."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Lifestyle and health maintenance', 'Exercise', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307008', 'MCQ', 'A nurse teaches parents of a toddler about injury prevention. Which action best reduces the risk of accidental poisoning?', 'Storing toxic substances in locked cabinets prevents accidental poisoning in toddlers.', '{"options":[{"id":"A","text":"Store cleaning products in a locked cabinet"},{"id":"B","text":"Keep medications on the kitchen counter"},{"id":"C","text":"Allow the toddler to explore under the sink"},{"id":"D","text":"Store chemicals in unlabeled drink bottles"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Locking away toxic substances prevents poisoning.","B":"Incorrect. This increases access risk.","C":"Incorrect. This exposes the child to hazards.","D":"Incorrect. This causes accidental ingestion."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Toddler safety', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307009', 'MCQ', 'A nurse teaches a postpartum client warning signs to report. Which finding should the client report to the provider?', 'Foul-smelling lochia with fever indicates possible postpartum infection and must be reported.', '{"options":[{"id":"A","text":"Foul-smelling lochia with fever"},{"id":"B","text":"Gradual decrease in lochia over days"},{"id":"C","text":"Mild afterpains during breastfeeding"},{"id":"D","text":"Breast fullness before feeding"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This suggests infection and must be reported.","B":"Incorrect. This is expected.","C":"Incorrect. These are normal.","D":"Incorrect. This is expected."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum education', 'Danger signs', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307010', 'MCQ', 'A nurse reviews a client''s body mass index (BMI) of 27. How should the nurse classify this result?', 'A BMI of 25 to 29.9 falls in the overweight category.', '{"options":[{"id":"A","text":"Overweight"},{"id":"B","text":"Underweight"},{"id":"C","text":"Normal weight"},{"id":"D","text":"Obese"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A BMI of 25 to 29.9 is classified as overweight.","B":"Incorrect. Underweight is below 18.5.","C":"Incorrect. Normal is 18.5 to 24.9.","D":"Incorrect. Obesity begins at 30."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Endocrine', 'Comprehensive health assessment', 'BMI', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307011', 'MCQ', 'A nurse plans client teaching. Which factor indicates the client is ready to learn?', 'A client who asks questions about self-care demonstrates readiness to learn.', '{"options":[{"id":"A","text":"The client asks questions about self-care"},{"id":"B","text":"The client is in severe acute pain"},{"id":"C","text":"The client is heavily sedated"},{"id":"D","text":"The client refuses to discuss the diagnosis"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Curiosity signals readiness to learn.","B":"Incorrect. Pain interferes with learning.","C":"Incorrect. Sedation impairs learning.","D":"Incorrect. This suggests a barrier."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Readiness and barriers to learning', 'Teaching', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_307012', 'MCQ', 'A nurse teaches a client about skin cancer prevention. Which recommendation is appropriate?', 'Broad-spectrum sunscreen and sun protection reduce the risk of skin cancer.', '{"options":[{"id":"A","text":"Apply broad-spectrum sunscreen before sun exposure"},{"id":"B","text":"Use tanning beds instead of natural sunlight"},{"id":"C","text":"Avoid sunscreen to allow vitamin D formation"},{"id":"D","text":"Sunburn is harmless if it fades"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sunscreen reduces UV-related skin damage.","B":"Incorrect. Tanning beds increase skin cancer risk.","C":"Incorrect. Sun protection is still recommended.","D":"Incorrect. Sunburns increase cancer risk."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Integumentary', 'Lifestyle and health maintenance', 'Skin cancer prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_307013', 'SATA', 'A nurse teaches an adult client about reducing cardiovascular risk. Which lifestyle recommendations should the nurse include? Select all that apply.', 'Physical activity, a heart-healthy diet, and tobacco avoidance reduce cardiovascular risk.', '{"options":[{"id":"A","text":"Engage in regular physical activity"},{"id":"B","text":"Eat a diet low in saturated fat and sodium"},{"id":"C","text":"Avoid tobacco use"},{"id":"D","text":"Increase intake of processed foods"},{"id":"E","text":"Maintain a sedentary lifestyle"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Lifestyle and health maintenance', 'Heart health', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_307014', 'SATA', 'A nurse educates parents about well-child care. Which are components of a routine well-child visit? Select all that apply.', 'Well-child visits include growth assessment, immunizations, and anticipatory guidance.', '{"options":[{"id":"A","text":"Growth and development assessment"},{"id":"B","text":"Routine immunizations"},{"id":"C","text":"Age-appropriate anticipatory guidance"},{"id":"D","text":"Emergency surgical intervention"},{"id":"E","text":"Only visits when the child is ill"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Preventive care and immunizations', 'Well-child visits', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_307015', 'SATA', 'A nurse teaches a pregnant client about healthy behaviors during pregnancy. Which instructions are appropriate? Select all that apply.', 'Prenatal vitamins, alcohol avoidance, and regular prenatal visits promote a healthy pregnancy.', '{"options":[{"id":"A","text":"Take a prenatal vitamin with folic acid daily"},{"id":"B","text":"Avoid alcohol during pregnancy"},{"id":"C","text":"Attend regularly scheduled prenatal visits"},{"id":"D","text":"Smoke to relieve stress"},{"id":"E","text":"Take medications without checking with the provider"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Health teaching', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_307016', 'SATA', 'A nurse teaches an older adult about preventing falls at home. Which recommendations should the nurse include? Select all that apply.', 'Removing hazards, installing grab bars, and improving lighting reduce fall risk in older adults.', '{"options":[{"id":"A","text":"Remove loose rugs and clutter"},{"id":"B","text":"Install grab bars in the bathroom"},{"id":"C","text":"Ensure adequate lighting in hallways"},{"id":"D","text":"Wear loose, floor-length clothing"},{"id":"E","text":"Keep walkways dark to save energy"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult health', 'Fall prevention', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_307017', 'SATA', 'A nurse reviews recommended screenings for an adult client. Which are routine preventive screenings? Select all that apply.', 'Blood pressure, cholesterol, and depression screenings are routine adult preventive measures.', '{"options":[{"id":"A","text":"Blood pressure measurement"},{"id":"B","text":"Cholesterol screening"},{"id":"C","text":"Depression screening"},{"id":"D","text":"Daily chest x-ray"},{"id":"E","text":"Routine brain MRI for all adults"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Targeted screening', 'Adult screening', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_307018', 'SELECT_N', 'Which 2 behaviors are expected developmental milestones for a healthy 3-year-old child?', 'A 3-year-old typically speaks in short sentences and can ride a tricycle.', '{"options":[{"id":"A","text":"Speaks in short sentences"},{"id":"B","text":"Rides a tricycle"},{"id":"C","text":"Reads simple paragraphs"},{"id":"D","text":"Ties shoelaces independently"},{"id":"E","text":"Writes in cursive"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Preschool milestones', 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_307019', 'TF', 'Colorectal cancer screening is generally recommended to begin at age 45 for average-risk adults.', 'Average-risk colorectal cancer screening is recommended starting at age 45.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'GI', 'Targeted screening', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
