('NCLEX_MAT_307021', 'MATRIX', 'For each developmental milestone, click to indicate the age group in which it is typically first achieved.', 'Rolling and first words emerge in infancy; stair-climbing and spoon-feeding emerge in toddlerhood.', '{"row_label":"Milestone","rows":[{"id":"r1","text":"Rolls from back to front"},{"id":"r2","text":"Walks up stairs with help"},{"id":"r3","text":"Says first words"},{"id":"r4","text":"Uses a spoon to self-feed"}],"columns":[{"id":"c1","text":"Infant (0-12 months)"},{"id":"c2","text":"Toddler (1-3 years)"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Age milestones', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_307022', 'MATRIX_MR', 'For each health maintenance activity, select all age groups for which it is routinely recommended.', 'Influenza vaccine and blood pressure screening apply broadly, while routine pneumococcal vaccination targets older adults.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Annual influenza vaccine"},{"id":"r2","text":"Pneumococcal vaccine"},{"id":"r3","text":"Blood pressure screening"}],"columns":[{"id":"c1","text":"Older adult (65+)"},{"id":"c2","text":"Adult (18-64)"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Preventive care and immunizations', 'Screening by age', 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_307023', 'CLOZE', 'The nurse teaches that a pregnant client should take {1} daily to help prevent neural tube defects and should avoid {2} entirely during pregnancy.', 'Folic acid prevents neural tube defects; alcohol should be avoided completely during pregnancy.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"folic acid"},{"id":"c2","text":"vitamin K"},{"id":"c3","text":"iron only"}]},{"id":"b2","choices":[{"id":"c1","text":"alcohol"},{"id":"c2","text":"water"},{"id":"c3","text":"fruit"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Nutrition', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_307024', 'HIGHLIGHT', 'Highlight the behaviors that promote health during a routine wellness visit. The client reports [[exercising 30 minutes most days]], [[smoking one pack of cigarettes daily]], [[eating vegetables with most meals]], and [[skipping all preventive checkups]].', 'Exercise and a vegetable-rich diet promote health, while smoking and skipping checkups do not.', '{"chunks":[{"id":"h1","text":"exercising 30 minutes most days"},{"id":"h2","text":"smoking one pack of cigarettes daily"},{"id":"h3","text":"eating vegetables with most meals"},{"id":"h4","text":"skipping all preventive checkups"}]}'::jsonb, '{"correct_ids":["h1","h3"],"feedback":{"h1":"Regular exercise promotes health.","h2":"Smoking is a high-risk behavior.","h3":"A vegetable-rich diet promotes health.","h4":"Avoiding checkups is not health-promoting."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'High-risk behavior education', 'Healthy behaviors', 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_307025', 'BOWTIE', 'Complete the diagram for a client at risk for cardiovascular disease by selecting health-promoting actions, the goal, and outcomes to monitor.', 'Exercise and a low-sodium diet reduce cardiovascular risk, monitored by blood pressure and weight.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Encourage regular aerobic exercise"},{"id":"lt2","text":"Teach a low-sodium diet"},{"id":"lt3","text":"Recommend daily smoking"},{"id":"lt4","text":"Advise a sedentary routine"}]},"centre":{"label":"Goal","tokens":[{"id":"ct1","text":"Reduce cardiovascular risk"},{"id":"ct2","text":"Increase blood pressure"},{"id":"ct3","text":"Promote weight gain"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Blood pressure"},{"id":"rt2","text":"Body weight"},{"id":"rt3","text":"Hair color"},{"id":"rt4","text":"Shoe size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Lifestyle and health maintenance', 'Risk reduction', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_307026', 'DRAG_CLOZE', 'The nurse teaches that adults should aim for at least [1] of moderate aerobic activity per week and should include [2] on two or more days weekly.', 'Adults should get at least 150 minutes of moderate aerobic activity plus muscle-strengthening exercise weekly.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"150 minutes"},{"id":"t2","text":"muscle-strengthening exercise"},{"id":"t3","text":"10 minutes"},{"id":"t4","text":"complete bed rest"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Lifestyle and health maintenance', 'Activity guidelines', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_307027', 'DRAG_ORDER', 'A nurse plans a health-promotion teaching session for a client. Place the steps of the teaching process in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"}],"tokens":[{"id":"t1","text":"Assess the client''s learning needs"},{"id":"t2","text":"Set mutual learning goals"},{"id":"t3","text":"Provide the health education"},{"id":"t4","text":"Evaluate the client''s understanding"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Comprehensive health assessment', 'Teaching process', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308001', 'MCQ', 'A nurse is teaching a woman planning pregnancy about preventing neural tube defects. Which supplement should the nurse emphasize taking before and during early pregnancy?', 'Adequate folic acid intake before and during early pregnancy reduces the risk of neural tube defects.', '{"options":[{"id":"A","text":"Folic acid"},{"id":"B","text":"Vitamin C"},{"id":"C","text":"Vitamin E"},{"id":"D","text":"Vitamin K"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Folic acid before conception and in early pregnancy prevents neural tube defects.","B":"Incorrect. Vitamin C is not linked to neural tube defect prevention.","C":"Incorrect. Vitamin E does not prevent neural tube defects.","D":"Incorrect. Vitamin K supports clotting, not neural tube formation."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Folic acid', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308002', 'MCQ', 'At which age does a nurse typically expect a healthy infant to begin sitting without support?', 'Sitting without support is an expected gross motor milestone around 6 months of age.', '{"options":[{"id":"A","text":"2 months"},{"id":"B","text":"6 months"},{"id":"C","text":"12 months"},{"id":"D","text":"18 months"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. At 2 months infants have minimal head control.","B":"Correct. Most infants sit without support around 6 months.","C":"Incorrect. By 12 months infants are typically standing or walking.","D":"Incorrect. This is far later than the expected milestone."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Growth and development', 'Infant milestones', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308003', 'MCQ', 'A nurse reviews the immunization record of a 12-month-old child. Which vaccine is typically first given at this age?', 'The first MMR vaccine is scheduled at 12 to 15 months of age.', '{"options":[{"id":"A","text":"Measles, mumps, and rubella (MMR)"},{"id":"B","text":"Hepatitis B first dose"},{"id":"C","text":"Rotavirus first dose"},{"id":"D","text":"Tetanus, diphtheria (Td) booster"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The first MMR dose is given at 12 to 15 months.","B":"Incorrect. The first hepatitis B dose is given at birth.","C":"Incorrect. Rotavirus begins at 2 months.","D":"Incorrect. Td boosters are given in adolescence and adulthood."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunizations', 'Childhood schedule', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308004', 'MCQ', 'A 52-year-old woman asks about routine breast cancer screening. Which screening test should the nurse recommend?', 'Mammography is the recommended screening test for early detection of breast cancer.', '{"options":[{"id":"A","text":"Mammography"},{"id":"B","text":"Colonoscopy"},{"id":"C","text":"Pap smear"},{"id":"D","text":"Bone density scan"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mammography is the standard screening test for breast cancer.","B":"Incorrect. Colonoscopy screens for colorectal cancer.","C":"Incorrect. The Pap smear screens for cervical cancer.","D":"Incorrect. A bone density scan screens for osteoporosis."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Reproductive', 'Cancer screening', 'Mammography', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308005', 'MCQ', 'A nurse teaches a new mother about breastfeeding. Which statement indicates the client understands proper latch?', 'A proper latch covers much of the areola, allowing effective milk transfer and reducing nipple trauma.', '{"options":[{"id":"A","text":"The baby''s mouth covers much of the areola, not just the nipple"},{"id":"B","text":"The baby should latch onto the nipple tip only"},{"id":"C","text":"I should hear a clicking sound while feeding"},{"id":"D","text":"Feeding should be limited to two minutes per side"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A wide latch over the areola promotes effective feeding and prevents soreness.","B":"Incorrect. Latching only the nipple causes soreness and poor feeding.","C":"Incorrect. Clicking suggests a poor latch.","D":"Incorrect. Feeding time should follow the infant''s cues."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum care', 'Breastfeeding', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308006', 'MCQ', 'A nurse counsels a healthy adult about physical activity. Which weekly amount of moderate-intensity aerobic activity should the nurse recommend?', 'Adults should perform at least 150 minutes of moderate-intensity aerobic activity per week.', '{"options":[{"id":"A","text":"At least 150 minutes"},{"id":"B","text":"At least 30 minutes"},{"id":"C","text":"At least 500 minutes"},{"id":"D","text":"No structured activity is needed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Guidelines recommend at least 150 minutes of moderate activity weekly.","B":"Incorrect. This is less than the weekly recommendation.","C":"Incorrect. This exceeds the standard recommendation.","D":"Incorrect. Regular activity is recommended for health maintenance."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Lifestyle education', 'Physical activity', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308007', 'MCQ', 'A nurse provides safety teaching to the parents of a 16-year-old who just obtained a driver''s permit. Which topic is the priority?', 'Motor vehicle crashes are a leading cause of death in adolescents, making driving safety the priority.', '{"options":[{"id":"A","text":"Consistent seat belt use and avoiding distracted driving"},{"id":"B","text":"Choosing a nutritious breakfast"},{"id":"C","text":"Establishing a consistent bedtime"},{"id":"D","text":"Limiting screen time on weekends"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Motor vehicle crashes are a leading cause of adolescent death.","B":"Incorrect. Important but not the safety priority for a new driver.","C":"Incorrect. Not the priority safety concern here.","D":"Incorrect. Not the leading safety risk for a new driver."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Adolescent health', 'Safety education', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308008', 'MCQ', 'A nurse teaches an older adult about home safety. Which suggestion best reduces the risk of falls?', 'Removing loose rugs and other tripping hazards is a key strategy to prevent falls in older adults.', '{"options":[{"id":"A","text":"Remove loose throw rugs from walkways"},{"id":"B","text":"Keep the home dimly lit to save energy"},{"id":"C","text":"Wear socks without shoes indoors"},{"id":"D","text":"Store frequently used items on high shelves"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Loose rugs are a common tripping hazard for older adults.","B":"Incorrect. Poor lighting increases fall risk.","C":"Incorrect. Socks alone are slippery and increase fall risk.","D":"Incorrect. Reaching high shelves increases fall risk."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Musculoskeletal', 'Older adult health', 'Fall prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308009', 'MCQ', 'A nurse discusses the benefits of smoking cessation with a client. Which statement by the nurse is accurate?', 'Smoking cessation reduces the risk of cardiovascular disease and cancer at any age.', '{"options":[{"id":"A","text":"Quitting smoking lowers your risk of heart disease and lung cancer"},{"id":"B","text":"The damage from smoking cannot be reduced by quitting"},{"id":"C","text":"Switching to menthol cigarettes is a safe alternative"},{"id":"D","text":"Only smoking outdoors eliminates all health risks"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cessation reduces cardiovascular and cancer risk.","B":"Incorrect. Quitting reduces future health risks.","C":"Incorrect. Menthol cigarettes are not safer.","D":"Incorrect. Location does not remove smoking risks."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Respiratory', 'High-risk behavior', 'Smoking cessation', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308010', 'MCQ', 'A parent asks when to introduce solid foods to their infant. Which age should the nurse recommend?', 'Solid foods are typically introduced around 6 months when infants show developmental readiness.', '{"options":[{"id":"A","text":"Around 6 months"},{"id":"B","text":"At 2 weeks"},{"id":"C","text":"At 2 months"},{"id":"D","text":"At 12 months"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Solid foods are generally introduced around 6 months.","B":"Incorrect. This is far too early for solid foods.","C":"Incorrect. The digestive system is not ready at 2 months.","D":"Incorrect. Solids are usually started earlier than 12 months."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'GI', 'Infant nutrition', 'Solid foods', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308011', 'MCQ', 'During a routine adult health check, which resting heart rate would the nurse consider within the normal range?', 'A normal adult resting heart rate ranges from 60 to 100 beats per minute.', '{"options":[{"id":"A","text":"72 beats per minute"},{"id":"B","text":"45 beats per minute"},{"id":"C","text":"120 beats per minute"},{"id":"D","text":"38 beats per minute"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A normal adult resting heart rate is 60 to 100 beats per minute.","B":"Incorrect. This is below the normal resting range.","C":"Incorrect. This is above the normal resting range.","D":"Incorrect. This is bradycardic for a healthy adult."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Health assessment', 'Vital signs', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_308012', 'MCQ', 'At what age is routine colorectal cancer screening generally recommended to begin for average-risk adults?', 'Routine colorectal cancer screening for average-risk adults generally begins at age 45.', '{"options":[{"id":"A","text":"45 years"},{"id":"B","text":"18 years"},{"id":"C","text":"75 years"},{"id":"D","text":"30 years"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Current guidelines recommend starting at age 45 for average-risk adults.","B":"Incorrect. This is far earlier than recommended.","C":"Incorrect. Screening typically begins well before this age.","D":"Incorrect. This is earlier than the standard recommendation."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'GI', 'Cancer screening', 'Colorectal', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_308013', 'SATA', 'A nurse teaches a pregnant client about danger signs to report immediately. Which findings should the client be instructed to report? Select all that apply.', 'Bleeding, severe headache, and sudden facial or hand edema can signal serious complications and must be reported.', '{"options":[{"id":"A","text":"Vaginal bleeding"},{"id":"B","text":"Severe headache"},{"id":"C","text":"Sudden swelling of the face and hands"},{"id":"D","text":"Mild fatigue in the afternoon"},{"id":"E","text":"Occasional mild nausea in the first trimester"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal education', 'Warning signs', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_308014', 'SATA', 'A nurse teaches an adult about reducing cardiovascular risk. Which lifestyle measures should the nurse include? Select all that apply.', 'A healthy diet, regular activity, and tobacco avoidance reduce cardiovascular risk.', '{"options":[{"id":"A","text":"Eat a diet low in saturated fat and sodium"},{"id":"B","text":"Engage in regular physical activity"},{"id":"C","text":"Avoid tobacco use"},{"id":"D","text":"Increase daily intake of fried foods"},{"id":"E","text":"Maintain a sedentary routine"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Heart health', 'Lifestyle', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_308015', 'SATA', 'A nurse teaches parents of a toddler about home injury prevention. Which instructions are appropriate? Select all that apply.', 'Locking chemicals, using stair gates, and limiting water temperature reduce common toddler injuries.', '{"options":[{"id":"A","text":"Store cleaning products in locked cabinets"},{"id":"B","text":"Place safety gates at the top of stairs"},{"id":"C","text":"Set the water heater to a safe temperature to prevent burns"},{"id":"D","text":"Keep small objects within the child''s reach"},{"id":"E","text":"Leave medication bottles on the kitchen counter"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Integumentary', 'Child safety', 'Injury prevention', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_308016', 'SATA', 'A nurse counsels a postmenopausal woman about osteoporosis prevention. Which recommendations should the nurse include? Select all that apply.', 'Weight-bearing exercise, calcium and vitamin D, and avoiding smoking and alcohol support bone health.', '{"options":[{"id":"A","text":"Perform weight-bearing exercise regularly"},{"id":"B","text":"Ensure adequate calcium and vitamin D intake"},{"id":"C","text":"Avoid smoking and excessive alcohol"},{"id":"D","text":"Remain sedentary to protect the bones"},{"id":"E","text":"Eliminate all dairy from the diet"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Musculoskeletal', 'Older adult health', 'Bone health', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_308017', 'SATA', 'A nurse reviews recommended vaccines for a healthy 66-year-old adult. Which vaccines are routinely recommended? Select all that apply.', 'Influenza, pneumococcal, and shingles vaccines are routinely recommended for older adults.', '{"options":[{"id":"A","text":"Annual influenza vaccine"},{"id":"B","text":"Pneumococcal vaccine"},{"id":"C","text":"Shingles (herpes zoster) vaccine"},{"id":"D","text":"Rotavirus vaccine"},{"id":"E","text":"Newborn hepatitis B birth dose"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Adult immunizations', 'Older adult', 'Easy', 'Remember', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_308018', 'SELECT_N', 'Which 3 findings indicate that a client is ready to learn new health information?', 'Asking questions, comfort, and expressed motivation signal readiness to learn.', '{"options":[{"id":"A","text":"The client asks questions about the condition"},{"id":"B","text":"The client is free of severe pain"},{"id":"C","text":"The client states a goal to manage the illness"},{"id":"D","text":"The client is highly anxious and unable to focus"},{"id":"E","text":"The client is heavily sedated"},{"id":"F","text":"The client refuses to discuss the diagnosis"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Readiness to learn', 'Teaching', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_308019', 'TF', 'Placing a healthy newborn on the back to sleep reduces the risk of sudden infant death syndrome (SIDS).', 'The supine sleep position is recommended to reduce the risk of SIDS.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Newborn care', 'Safe sleep', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_308020', 'TF', 'Clients should be taught that sunscreen is only necessary on sunny days and can be skipped when it is cloudy.', 'Ultraviolet rays penetrate clouds, so sunscreen is recommended even on cloudy days.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Integumentary', 'Skin cancer prevention', 'Sun safety', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_308021', 'MATRIX', 'For each developmental milestone, click to specify whether it is typically expected in infancy (birth to 12 months) or in the toddler period (1 to 3 years).', 'Sitting and first words occur in infancy; stair climbing and two-word phrases emerge in the toddler years.', '{"row_label":"Milestone","rows":[{"id":"r1","text":"Sits without support"},{"id":"r2","text":"Walks up stairs"},{"id":"r3","text":"Says first single words"},{"id":"r4","text":"Speaks in short two-word phrases"}],"columns":[{"id":"c1","text":"Infancy"},{"id":"c2","text":"Toddler"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Developmental milestones', 'Age expectations', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_308022', 'MATRIX_MR', 'For each vaccine, select all groups for whom it is routinely recommended.', 'Influenza is recommended across ages; rotavirus is for infants; shingles is for older adults.', '{"row_label":"Vaccine","rows":[{"id":"r1","text":"Influenza vaccine"},{"id":"r2","text":"Rotavirus vaccine"},{"id":"r3","text":"Shingles (herpes zoster) vaccine"}],"columns":[{"id":"c1","text":"Infants/Children"},{"id":"c2","text":"Older Adults"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1"],"r3":["c2"]},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunization audience', 'Age groups', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_308023', 'CLOZE', 'A nurse advises a healthy adult about routine screening. Blood pressure should be checked to screen for {1}, and a fasting blood glucose or A1C is used to screen for {2}.', 'Blood pressure screens for hypertension; fasting glucose or A1C screens for diabetes.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hypertension"},{"id":"c2","text":"anemia"},{"id":"c3","text":"asthma"}]},{"id":"b2","choices":[{"id":"c1","text":"diabetes"},{"id":"c2","text":"glaucoma"},{"id":"c3","text":"arthritis"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Endocrine', 'Health screening', 'Diabetes', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_308024', 'HIGHLIGHT', 'Highlight the findings a nurse should teach a pregnant client to report right away. The client reports [[vaginal bleeding]], mild [[occasional heartburn]], [[blurred vision]], normal [[fetal movement]], and [[persistent severe headache]].', 'Bleeding, visual changes, and severe headache are warning signs requiring immediate reporting.', '{"chunks":[{"id":"h1","text":"vaginal bleeding"},{"id":"h2","text":"occasional heartburn"},{"id":"h3","text":"blurred vision"},{"id":"h4","text":"fetal movement"},{"id":"h5","text":"persistent severe headache"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Bleeding may indicate a serious complication.","h2":"Mild heartburn is a common, expected discomfort.","h3":"Visual changes may signal preeclampsia.","h4":"Normal fetal movement is reassuring.","h5":"Severe headache may signal preeclampsia."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal warning signs', 'Assessment', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_308025', 'BOWTIE', 'An adult with a family history of heart disease wants to reduce risk. Complete the diagram by selecting actions to take, the focus, and parameters to monitor.', 'Diet and exercise reduce cardiovascular risk; blood pressure and cholesterol are monitored.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Adopt a low-sodium, low-fat diet"},{"id":"lt2","text":"Exercise regularly"},{"id":"lt3","text":"Begin daily tobacco use"},{"id":"lt4","text":"Increase fried food intake"}]},"centre":{"label":"Focus","tokens":[{"id":"ct1","text":"Cardiovascular risk reduction"},{"id":"ct2","text":"Increasing body weight"},{"id":"ct3","text":"Reducing physical activity"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood pressure"},{"id":"rt2","text":"Cholesterol levels"},{"id":"rt3","text":"Hair growth"},{"id":"rt4","text":"Nail length"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Health maintenance', 'Risk reduction', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_308026', 'DRAG_CLOZE', 'A nurse teaches about routine adult screening. Colorectal cancer screening for average-risk adults typically begins at age [1], and breast cancer screening uses [2].', 'Colorectal screening begins at 45 for average-risk adults; mammography screens for breast cancer.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"45 years"},{"id":"t2","text":"mammography"},{"id":"t3","text":"18 years"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Adult screening', 'Recommendations', 'Easy', 'Remember', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_308027', 'DRAG_ORDER', 'A nurse plans a health-education session for a client. Place the teaching steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client''s learning needs and readiness"},{"id":"t2","text":"Set mutual learning goals"},{"id":"t3","text":"Provide the health teaching"},{"id":"t4","text":"Have the client demonstrate or restate the information"},{"id":"t5","text":"Document the teaching and response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Health teaching', 'Teaching process', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300001', 'MCQ', 'A charge nurse is assigning tasks. Which task is MOST appropriate to delegate to unlicensed assistive personnel (UAP)?', 'UAP may collect data such as routine vitals on stable clients; assessment, teaching, and IV care stay with the nurse.', '{"options":[{"id":"A","text":"Taking routine vital signs on a stable client"},{"id":"B","text":"Teaching a client about a new medication"},{"id":"C","text":"Assessing a new admission"},{"id":"D","text":"Adjusting an IV infusion rate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Vital signs on a stable client are within UAP scope.","B":"Incorrect. Client teaching requires a nurse.","C":"Incorrect. Initial assessment cannot be delegated.","D":"Incorrect. IV management is a nursing task."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300002', 'MCQ', 'A nurse is giving a shift report using the SBAR format. Which information belongs in the ''B'' (Background) section?', 'In SBAR, Background provides the diagnosis and relevant clinical history that frames the situation.', '{"options":[{"id":"A","text":"The client''s admitting diagnosis and relevant history"},{"id":"B","text":"The nurse''s recommendation for follow-up"},{"id":"C","text":"The current vital signs and assessment"},{"id":"D","text":"The reason the nurse is calling"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Background covers the diagnosis and pertinent history.","B":"Incorrect. That is the Recommendation section.","C":"Incorrect. That is the Assessment section.","D":"Incorrect. That is the Situation section."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300003', 'MCQ', 'A client is scheduled for surgery. What is the nurse''s PRIMARY role regarding informed consent?', 'Obtaining informed consent (explaining the procedure) is the provider''s duty; the nurse witnesses the signature and confirms understanding.', '{"options":[{"id":"A","text":"Witness the client''s signature and confirm understanding"},{"id":"B","text":"Explain the surgical risks and alternatives"},{"id":"C","text":"Decide whether the surgery should proceed"},{"id":"D","text":"Sign the consent on the client''s behalf"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The nurse witnesses the signature and verifies the client understands.","B":"Incorrect. The provider performing the procedure explains risks.","C":"Incorrect. That is not the nurse''s decision.","D":"Incorrect. The nurse never signs for the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300004', 'MCQ', 'A newly admitted client asks the nurse about creating a living will. What is the nurse''s BEST response?', 'Under the Patient Self-Determination Act, clients must be informed of their right to create advance directives; the nurse provides information and resources.', '{"options":[{"id":"A","text":"Provide information about advance directives and offer resources"},{"id":"B","text":"Tell the client this is not necessary while hospitalized"},{"id":"C","text":"Refer the client to complete it only after discharge"},{"id":"D","text":"Explain that only the provider can discuss this"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Clients have the right to be informed about advance directives.","B":"Incorrect. This dismisses the client''s right.","C":"Incorrect. Delaying is unnecessary.","D":"Incorrect. Nurses can provide advance directive information."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300005', 'MCQ', 'Which action by a nurse is a violation of client confidentiality?', 'Sharing protected health information with people not involved in the client''s care violates confidentiality/HIPAA.', '{"options":[{"id":"A","text":"Discussing a client''s diagnosis with a friend in the cafeteria"},{"id":"B","text":"Reporting assessment findings to the oncoming nurse"},{"id":"C","text":"Documenting care in the electronic health record"},{"id":"D","text":"Calling the provider about a critical lab value"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sharing client information with unauthorized people violates HIPAA.","B":"Incorrect. Handoff to the care team is appropriate.","C":"Incorrect. Documentation is required.","D":"Incorrect. This is appropriate care coordination."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300006', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'Using the ABC framework, a new breathing problem is the highest priority.', '{"options":[{"id":"A","text":"A client reporting new shortness of breath"},{"id":"B","text":"A client requesting a pain medication refill"},{"id":"C","text":"A client due for a scheduled dressing change"},{"id":"D","text":"A client asking about the lunch menu"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A new airway/breathing problem takes priority.","B":"Incorrect. This can wait.","C":"Incorrect. Routine care is not urgent.","D":"Incorrect. This is not a priority."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300007', 'MCQ', 'Which task is appropriate for the RN to assign to a licensed practical nurse (LPN)?', 'LPNs may administer routine medications to stable clients; assessment, care planning, and complex teaching remain with the RN.', '{"options":[{"id":"A","text":"Administering oral medications to a stable client"},{"id":"B","text":"Developing the initial plan of care"},{"id":"C","text":"Performing the admission assessment"},{"id":"D","text":"Providing discharge teaching to a new diabetic"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. LPNs may administer routine oral medications.","B":"Incorrect. Care planning is an RN responsibility.","C":"Incorrect. Initial assessment is an RN task.","D":"Incorrect. Complex teaching is an RN task."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'LPN', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300008', 'MCQ', 'A client tells the nurse he does not understand why a test was ordered and wants more information. Which action BEST demonstrates client advocacy?', 'The nurse advocates by ensuring the client''s concerns reach the provider and are addressed.', '{"options":[{"id":"A","text":"Contact the provider to clarify and ensure the client''s questions are answered"},{"id":"B","text":"Tell the client to sign the form and ask later"},{"id":"C","text":"Cancel the test without notifying anyone"},{"id":"D","text":"Reassure the client the provider knows best"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocating means ensuring the client gets the information needed.","B":"Incorrect. This ignores the client''s need.","C":"Incorrect. This is outside the nurse''s authority.","D":"Incorrect. This dismisses the client''s right to information."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300009', 'MCQ', 'A nurse suspects that a child in the emergency department is a victim of abuse. What is the nurse''s legal obligation?', 'Nurses are mandatory reporters; suspected abuse must be reported to the proper authorities.', '{"options":[{"id":"A","text":"Report the suspicion to the appropriate authorities"},{"id":"B","text":"Wait until abuse is confirmed before acting"},{"id":"C","text":"Confront the parents directly"},{"id":"D","text":"Document the finding but take no further action"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandatory reporters of suspected abuse.","B":"Incorrect. Suspicion is enough to require reporting.","C":"Incorrect. This is not the nurse''s role and may endanger the child.","D":"Incorrect. Documentation alone does not fulfill the duty to report."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300010', 'MCQ', 'A nurse reads a prescription that is unclear and possibly incorrect. What should the nurse do?', 'An unclear or questionable order must always be clarified with the prescriber before implementation.', '{"options":[{"id":"A","text":"Contact the prescriber to clarify before administering"},{"id":"B","text":"Administer the order as best understood"},{"id":"C","text":"Ask another nurse to interpret it"},{"id":"D","text":"Skip the order entirely without notifying anyone"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Unclear orders must be clarified before acting.","B":"Incorrect. Guessing risks a medication error.","C":"Incorrect. Only the prescriber can clarify their order.","D":"Incorrect. Omitting care without follow-up is unsafe."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300011', 'MCQ', 'A client recovering from a stroke has difficulty swallowing. To which member of the healthcare team should the nurse recommend a referral?', 'A speech-language pathologist evaluates and treats dysphagia (swallowing difficulty).', '{"options":[{"id":"A","text":"Speech-language pathologist"},{"id":"B","text":"Respiratory therapist"},{"id":"C","text":"Social worker"},{"id":"D","text":"Physical therapist"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The SLP evaluates and manages swallowing difficulties.","B":"Incorrect. Respiratory therapy manages breathing, not swallowing.","C":"Incorrect. Social work addresses psychosocial and discharge needs.","D":"Incorrect. PT addresses mobility, not swallowing."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Referrals', 'Multidisciplinary collaboration', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_300012', 'MCQ', 'When should discharge planning for a hospitalized client ideally begin?', 'Effective discharge planning starts at admission so needs and resources are arranged in time.', '{"options":[{"id":"A","text":"At the time of admission"},{"id":"B","text":"The day before the anticipated discharge"},{"id":"C","text":"Only after the provider writes the discharge order"},{"id":"D","text":"When the client first requests to go home"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Discharge planning begins on admission.","B":"Incorrect. This is too late to coordinate needs.","C":"Incorrect. Planning should already be underway.","D":"Incorrect. Planning should not wait for the request."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge planning', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_300013', 'SATA', 'Which tasks can the nurse appropriately delegate to unlicensed assistive personnel (UAP)? Select all that apply.', 'UAP may perform stable ADLs and data collection; evaluation, care planning, and medication administration remain with the nurse.', '{"options":[{"id":"A","text":"Assisting a stable client with bathing"},{"id":"B","text":"Feeding a client who has no swallowing difficulty"},{"id":"C","text":"Measuring and recording intake and output"},{"id":"D","text":"Evaluating the effectiveness of pain medication"},{"id":"E","text":"Creating the client''s plan of care"},{"id":"F","text":"Administering an intramuscular injection"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_300014', 'SATA', 'Which actions help the nurse protect client confidentiality? Select all that apply.', 'Protecting confidentiality means limiting disclosure to the care team, securing records, logging off, and avoiding social media posts.', '{"options":[{"id":"A","text":"Logging off the computer after charting"},{"id":"B","text":"Sharing information only with the care team"},{"id":"C","text":"Avoiding posting client details on social media"},{"id":"D","text":"Discussing clients by name in a public elevator"},{"id":"E","text":"Leaving printed reports on an unattended counter"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_300015', 'SATA', 'Which elements must be met for consent to be considered informed? Select all that apply.', 'Informed consent requires disclosure of the procedure and its risks/benefits, voluntary agreement, and a competent client.', '{"options":[{"id":"A","text":"The client received an explanation of the procedure"},{"id":"B","text":"The risks and benefits were disclosed"},{"id":"C","text":"The client gave consent voluntarily"},{"id":"D","text":"The client is competent to make the decision"},{"id":"E","text":"The nurse decided the procedure was necessary"},{"id":"F","text":"Consent was given under time pressure from staff"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_300016', 'SATA', 'Which tasks are within the scope of a licensed practical nurse (LPN)? Select all that apply.', 'LPNs reinforce teaching, give routine medications, and monitor stable clients; initial assessment and care planning are RN duties.', '{"options":[{"id":"A","text":"Reinforcing teaching the RN has already provided"},{"id":"B","text":"Administering routine oral medications"},{"id":"C","text":"Monitoring a stable client and reporting changes"},{"id":"D","text":"Performing the initial admission assessment"},{"id":"E","text":"Developing the nursing plan of care"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'LPN', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_300017', 'SATA', 'Which are recognized rights of the hospitalized client? Select all that apply.', 'Clients have the right to refuse treatment, to privacy, and to information; they are not obligated to accept care or justify refusals.', '{"options":[{"id":"A","text":"The right to refuse treatment"},{"id":"B","text":"The right to privacy and confidentiality"},{"id":"C","text":"The right to be informed about the plan of care"},{"id":"D","text":"The obligation to accept all recommended treatments"},{"id":"E","text":"The requirement to justify a refusal to staff"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_300018', 'SELECT_N', 'Select the 3 tasks the nurse can appropriately delegate to unlicensed assistive personnel.', 'UAP may ambulate stable clients, reposition, and record weights; assessment and teaching remain with the nurse.', '{"options":[{"id":"A","text":"Ambulating a stable client in the hallway"},{"id":"B","text":"Turning and repositioning a bedbound client"},{"id":"C","text":"Weighing a client and recording the result"},{"id":"D","text":"Assessing a new pressure injury"},{"id":"E","text":"Teaching wound-care technique to a caregiver"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_300019', 'SELECT_N', 'A nurse must prioritize care. Select the 2 clients who need to be assessed FIRST.', 'Low oxygen saturation and sudden chest pain are airway/circulation emergencies that take priority over comfort requests.', '{"options":[{"id":"A","text":"A client with an oxygen saturation of 86%"},{"id":"B","text":"A client reporting sudden severe chest pain"},{"id":"C","text":"A client requesting help to the bathroom"},{"id":"D","text":"A client asking when breakfast will arrive"},{"id":"E","text":"A client who wants an extra blanket"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_300020', 'TF', 'The initial nursing assessment of a newly admitted client can be delegated to unlicensed assistive personnel.', 'Initial assessment requires nursing judgment and cannot be delegated to UAP.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_300021', 'TF', 'A competent client has the right to refuse a treatment even if the healthcare team disagrees with the decision.', 'Autonomy gives a competent client the right to refuse treatment, regardless of the team''s opinion.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_300022', 'MATRIX', 'For each task, click to indicate the most appropriate team member to perform it.', 'Assessment and teaching require the RN; routine vitals and ADL assistance may be delegated to UAP.', '{"row_label":"Task","rows":[{"id":"r1","text":"Performing an initial admission assessment"},{"id":"r2","text":"Recording a stable client''s vital signs"},{"id":"r3","text":"Providing discharge medication teaching"},{"id":"r4","text":"Assisting a stable client with bathing"}],"columns":[{"id":"c1","text":"RN"},{"id":"c2","text":"UAP"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Scope of practice', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_300023', 'MATRIX_MR', 'For each task, select every team member permitted to perform it (may be more than one).', 'RNs and LPNs may give routine medications; care planning is RN-only; data collection and repositioning may be done by all three.', '{"row_label":"Task","rows":[{"id":"r1","text":"Administer routine oral medication"},{"id":"r2","text":"Measure and record intake and output"},{"id":"r3","text":"Develop the initial plan of care"},{"id":"r4","text":"Reposition a stable bedbound client"}],"columns":[{"id":"c1","text":"RN"},{"id":"c2","text":"LPN"},{"id":"c3","text":"UAP"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1","c2","c3"],"r3":["c1"],"r4":["c1","c2","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'Delegation', 'Easy', 'Apply', '{}', 9, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_300024', 'CLOZE', 'When calling a provider using SBAR, the nurse states the reason for the call in the {1} step and offers a suggested action in the {2} step.', 'In SBAR, Situation names the reason for the call and Recommendation states the nurse''s suggested action.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"Situation"},{"id":"c2","text":"Assessment"},{"id":"c3","text":"Background"}]},{"id":"b2","choices":[{"id":"c1","text":"Recommendation"},{"id":"c2","text":"Background"},{"id":"c3","text":"Situation"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_300025', 'HIGHLIGHT', 'Highlight the findings the nurse should report to the provider immediately. The client is resting comfortably. Temperature [[37.0°C]]. Blood pressure [[90/50 mmHg]]. Oxygen saturation [[85% on room air]]. The client [[ate most of breakfast]]. The client reports [[new confusion]].', 'Hypotension, hypoxemia, and new confusion are abnormal findings that require prompt provider notification.', '{"chunks":[{"id":"h1","text":"37.0°C"},{"id":"h2","text":"90/50 mmHg"},{"id":"h3","text":"85% on room air"},{"id":"h4","text":"ate most of breakfast"},{"id":"h5","text":"new confusion"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Normal temperature — no report needed.","h2":"Hypotension — should be reported.","h3":"Hypoxemia — needs immediate report.","h4":"Normal finding — no report needed.","h5":"New neurologic change — report immediately."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Reporting to provider', 'Prioritization', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_300026', 'BOWTIE', 'The charge nurse is organizing the shift. Complete the diagram by selecting the priority focus, the actions to take, and what to monitor.', 'Safe management of care means prioritizing the unstable client, delegating within scope, and monitoring acuity and delegated task completion.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Assess the unstable client first"},{"id":"lt2","text":"Delegate routine vitals to the UAP"},{"id":"lt3","text":"Delay all documentation until end of shift"},{"id":"lt4","text":"Assign the admission assessment to the UAP"}]},"centre":{"label":"Priority focus","tokens":[{"id":"ct1","text":"Safe assignment and prioritization"},{"id":"ct2","text":"Reducing the client''s hospital bill"},{"id":"ct3","text":"Finishing the shift early"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Changes in client acuity"},{"id":"rt2","text":"Completion of delegated tasks"},{"id":"rt3","text":"The cafeteria menu"},{"id":"rt4","text":"Staff parking availability"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and prioritization', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_300027', 'DRAG_ORDER', 'Place the steps for discharging a client from the hospital in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Verify the provider''s discharge order"},{"id":"t2","text":"Review discharge instructions and teaching with the client"},{"id":"t3","text":"Confirm the client has transportation and prescriptions"},{"id":"t4","text":"Escort the client out per facility policy"},{"id":"t5","text":"Document the discharge in the record"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge process', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301001', 'MCQ', 'A nurse is planning care for a group of clients. Which task is MOST appropriate to delegate to unlicensed assistive personnel (UAP)?', 'UAP may collect data such as routine vitals on stable clients but cannot assess, teach, or plan care.', '{"options":[{"id":"A","text":"Taking routine vital signs on a stable client"},{"id":"B","text":"Teaching a client about a new medication"},{"id":"C","text":"Assessing a client''s surgical wound"},{"id":"D","text":"Developing the plan of care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Routine vital signs on a stable client are within UAP scope.","B":"Incorrect. Client teaching requires a licensed nurse.","C":"Incorrect. Assessment cannot be delegated to UAP.","D":"Incorrect. Care planning is a nursing responsibility."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301002', 'MCQ', 'A nurse is giving a shift report using SBAR. Which information belongs in the ''Background'' section?', 'In SBAR, Background provides pertinent history and context leading up to the current situation.', '{"options":[{"id":"A","text":"The client''s admitting diagnosis and relevant history"},{"id":"B","text":"The nurse''s suggestion to increase the IV rate"},{"id":"C","text":"The client''s current blood pressure reading"},{"id":"D","text":"The reason the nurse is calling right now"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Background covers the pertinent history and context.","B":"Incorrect. That is Recommendation.","C":"Incorrect. Current findings belong to Assessment.","D":"Incorrect. That is Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff', 'SBAR', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301003', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'Airway/breathing and new cardiac symptoms take priority over stable or comfort needs.', '{"options":[{"id":"A","text":"A client reporting new shortness of breath and chest tightness"},{"id":"B","text":"A client requesting pain medication for a chronic backache"},{"id":"C","text":"A client waiting for discharge teaching"},{"id":"D","text":"A client asking for a second breakfast tray"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. New respiratory and cardiac symptoms are the highest priority.","B":"Incorrect. Chronic stable pain is not the most urgent.","C":"Incorrect. Discharge teaching is not time-critical.","D":"Incorrect. This is a low-priority comfort request."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301004', 'MCQ', 'A nurse wants to protect client privacy. Which action best maintains confidentiality?', 'HIPAA requires client information be shared only with those directly involved in care.', '{"options":[{"id":"A","text":"Discussing client information only with those involved in the client''s care"},{"id":"B","text":"Posting a de-identified case on a personal social media page"},{"id":"C","text":"Leaving the computer logged in for the next nurse"},{"id":"D","text":"Sharing the client''s diagnosis with a curious visitor"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sharing on a need-to-know basis protects confidentiality.","B":"Incorrect. Posting client cases online risks a privacy breach.","C":"Incorrect. Unattended access exposes protected data.","D":"Incorrect. Visitors are not entitled to protected information."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301005', 'MCQ', 'A client is scheduled for surgery. What is the nurse''s primary role regarding informed consent?', 'The provider obtains informed consent; the nurse witnesses the signature and confirms it is voluntary and informed.', '{"options":[{"id":"A","text":"Witnessing the client''s signature and confirming it is voluntary"},{"id":"B","text":"Explaining the surgical risks and benefits in detail"},{"id":"C","text":"Deciding whether the surgery is necessary"},{"id":"D","text":"Signing the consent on the client''s behalf"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The nurse witnesses the signature and verifies voluntariness.","B":"Incorrect. The surgeon explains the procedure, risks, and benefits.","C":"Incorrect. This is a provider decision.","D":"Incorrect. The nurse never signs for a competent client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301006', 'MCQ', 'Which task is appropriate for the RN to assign to a licensed practical nurse (LPN)?', 'LPNs administer routine medications and reinforce teaching; RNs retain assessment, planning, and complex interventions.', '{"options":[{"id":"A","text":"Administering oral medications to a stable client"},{"id":"B","text":"Creating the initial nursing care plan"},{"id":"C","text":"Performing the admission assessment"},{"id":"D","text":"Administering the first dose of IV chemotherapy"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. LPNs may administer many routine medications to stable clients.","B":"Incorrect. Care planning is the RN''s responsibility.","C":"Incorrect. Initial assessment is an RN function.","D":"Incorrect. This requires specialized RN skill."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'LPN scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301007', 'MCQ', 'A client asks the nurse about a living will. Which statement best describes its purpose?', 'A living will is an advance directive expressing a client''s treatment wishes when they cannot communicate.', '{"options":[{"id":"A","text":"It states the client''s wishes for care if they become unable to decide"},{"id":"B","text":"It transfers the client''s property to family members"},{"id":"C","text":"It names a person to manage the client''s finances"},{"id":"D","text":"It guarantees the client will receive all possible treatments"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A living will documents future care preferences.","B":"Incorrect. That describes a financial will.","C":"Incorrect. That is financial power of attorney.","D":"Incorrect. A living will may also limit treatment."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Advance directives', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301008', 'MCQ', 'A nurse receives a written order that is illegible. What should the nurse do?', 'An unclear order must be clarified with the prescriber before implementation to prevent errors.', '{"options":[{"id":"A","text":"Contact the prescriber to clarify the order before carrying it out"},{"id":"B","text":"Interpret the order based on the client''s diagnosis"},{"id":"C","text":"Ask another nurse to guess what it says"},{"id":"D","text":"Give the medication and clarify later"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Clarify unclear orders directly with the prescriber.","B":"Incorrect. Guessing an order is unsafe.","C":"Incorrect. A second guess is still a guess.","D":"Incorrect. Never administer an unverified order."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301009', 'MCQ', 'A client states, ''I don''t understand why I need this test.'' Which nursing action best demonstrates advocacy?', 'The nurse advocates by ensuring the client understands the test so they can make an informed decision.', '{"options":[{"id":"A","text":"Arranging for the provider to explain the test to the client"},{"id":"B","text":"Telling the client the test is required and cannot be refused"},{"id":"C","text":"Proceeding with the test to avoid delays"},{"id":"D","text":"Documenting that the client is being difficult"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocacy ensures the client receives the information needed to decide.","B":"Incorrect. Clients have the right to refuse.","C":"Incorrect. This ignores the client''s concern.","D":"Incorrect. This is judgmental and not advocacy."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Client advocacy', 'Rights', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301010', 'MCQ', 'A nurse diagnoses a client with active tuberculosis. Which action is legally required?', 'Active tuberculosis is a mandatory reportable disease that must be reported to public health authorities.', '{"options":[{"id":"A","text":"Report the case to the public health department"},{"id":"B","text":"Keep the diagnosis confidential from all agencies"},{"id":"C","text":"Wait until the client is discharged to report"},{"id":"D","text":"Report only if the client consents"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TB is a reportable communicable disease.","B":"Incorrect. Reportable diseases must be disclosed to public health.","C":"Incorrect. Reporting should be timely.","D":"Incorrect. Mandatory reporting does not require consent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Community Health', 'Multisystem', 'Mandatory reporting', 'Communicable disease', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301011', 'MCQ', 'A client recovering from a stroke has difficulty swallowing safely. Which referral is most appropriate?', 'A speech-language pathologist assesses and manages dysphagia after stroke.', '{"options":[{"id":"A","text":"Speech-language pathologist"},{"id":"B","text":"Respiratory therapist"},{"id":"C","text":"Social worker"},{"id":"D","text":"Pharmacist"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. SLPs evaluate and treat swallowing difficulties.","B":"Incorrect. RTs manage breathing, not swallowing.","C":"Incorrect. Social work addresses psychosocial needs.","D":"Incorrect. Pharmacists focus on medications."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Referrals', 'Multidisciplinary collaboration', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_301012', 'MCQ', 'Which entry is the most appropriate nursing documentation?', 'Documentation should be factual, objective, and measurable rather than judgmental or vague.', '{"options":[{"id":"A","text":"Client reports pain of 7 out of 10 in the right knee"},{"id":"B","text":"Client seems to be exaggerating the pain"},{"id":"C","text":"Client is doing fine today"},{"id":"D","text":"Client is probably fine and does not need medication"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Objective, measurable, and factual.","B":"Incorrect. This is a subjective judgment.","C":"Incorrect. Vague and non-specific.","D":"Incorrect. Speculative and non-factual."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Documentation', 'Terminology', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_301013', 'SATA', 'Which tasks can the nurse appropriately delegate to unlicensed assistive personnel? Select all that apply.', 'UAP perform routine ADLs and data collection; evaluation, planning, and IV medications remain with licensed staff.', '{"options":[{"id":"A","text":"Assisting a stable client to the bathroom"},{"id":"B","text":"Measuring and recording intake and output"},{"id":"C","text":"Feeding a client who has no swallowing difficulty"},{"id":"D","text":"Evaluating the effectiveness of pain medication"},{"id":"E","text":"Developing the client''s discharge plan"},{"id":"F","text":"Providing IV push medication"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_301014', 'SATA', 'Which are basic rights of a hospitalized client? Select all that apply.', 'Clients have rights to refuse care, confidentiality, and information, but not to another client''s records or unavailable treatments.', '{"options":[{"id":"A","text":"The right to refuse treatment"},{"id":"B","text":"The right to confidentiality of health information"},{"id":"C","text":"The right to receive information about their care"},{"id":"D","text":"The right to demand a specific unavailable medication"},{"id":"E","text":"The right to review another client''s chart"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Client rights', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_301015', 'SATA', 'Which items should be included in a nursing shift handoff report? Select all that apply.', 'Handoff should convey clinically relevant, factual information, not personal opinions or gossip.', '{"options":[{"id":"A","text":"Current diagnosis and reason for admission"},{"id":"B","text":"Pending tests and treatments"},{"id":"C","text":"Recent changes in the client''s condition"},{"id":"D","text":"The nurse''s personal opinion of the client''s family"},{"id":"E","text":"Gossip about the client from other staff"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff', 'SBAR', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_301016', 'SATA', 'Which actions could result in a breach of client confidentiality? Select all that apply.', 'Public discussion, social media posts, and unsecured documents breach confidentiality; private handoff and ID checks do not.', '{"options":[{"id":"A","text":"Discussing a client''s case in a crowded elevator"},{"id":"B","text":"Sharing a client photo on social media"},{"id":"C","text":"Leaving printed reports at the public copier"},{"id":"D","text":"Reporting handoff to the oncoming nurse in a private area"},{"id":"E","text":"Verifying a client''s identity before treatment"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_301017', 'SATA', 'Which actions are appropriate when preparing a client for discharge? Select all that apply.', 'Effective discharge planning includes medication review, follow-up, and understandable written instructions.', '{"options":[{"id":"A","text":"Reviewing medications the client will take at home"},{"id":"B","text":"Confirming follow-up appointments are scheduled"},{"id":"C","text":"Providing written instructions in the client''s language"},{"id":"D","text":"Withholding the discharge summary from the client"},{"id":"E","text":"Removing the client''s IV only after they leave the building"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge planning', 'Admit/transfer/discharge', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_301018', 'SELECT_N', 'A nurse is prioritizing care for a group of clients. Select the 3 clients who should be seen first.', 'Low oxygen saturation, neurologic changes, and cardiac chest pain are urgent and take priority over comfort or routine needs.', '{"options":[{"id":"A","text":"A client with an oxygen saturation of 85% on room air"},{"id":"B","text":"A client with new confusion and slurred speech"},{"id":"C","text":"A client with chest pain radiating to the jaw"},{"id":"D","text":"A client requesting a warm blanket"},{"id":"E","text":"A client asking about visiting hours"},{"id":"F","text":"A client due for routine morning medications"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_301019', 'TF', 'It is appropriate for a registered nurse to delegate the initial assessment of a newly admitted client to unlicensed assistive personnel.', 'Initial assessment requires nursing judgment and cannot be delegated to UAP.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Assessment scope', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_301020', 'TF', 'A do-not-resuscitate (DNR) order means that cardiopulmonary resuscitation will not be performed if the client''s heart stops.', 'A DNR order directs staff to withhold CPR while other comfort and supportive care continues.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Advance directives', 'DNR', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_301021', 'MATRIX', 'For each task, click to specify whether it can be delegated to a UAP or must be performed by the registered nurse.', 'UAP handle ADLs and data collection; assessment and teaching require the RN.', '{"row_label":"Task","rows":[{"id":"r1","text":"Bathing a stable client"},{"id":"r2","text":"Assessing a new client''s breath sounds"},{"id":"r3","text":"Recording the client''s food intake"},{"id":"r4","text":"Teaching insulin self-injection"},{"id":"r5","text":"Ambulating a stable client"}],"columns":[{"id":"c1","text":"Delegate to UAP"},{"id":"c2","text":"RN only"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Scope of practice', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_301022', 'MATRIX_MR', 'For each client need, select all team members who could appropriately address it.', 'Matching each need to the correct discipline supports effective multidisciplinary collaboration.', '{"row_label":"Team member","rows":[{"id":"r1","text":"Client needs help arranging home care after discharge"},{"id":"r2","text":"Client needs a diabetic meal plan"},{"id":"r3","text":"Client needs gait training and mobility exercises"},{"id":"r4","text":"Client with obesity needs both weight-loss diet and exercise support"}],"columns":[{"id":"c1","text":"Physical therapist"},{"id":"c2","text":"Dietitian"},{"id":"c3","text":"Social worker"}]}'::jsonb, '{"cells":{"r1":["c3"],"r2":["c2"],"r3":["c1"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', 'Referrals', 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_301023', 'CLOZE', 'When calling the provider about a deteriorating client, the nurse should begin by stating the {1} using SBAR, and should end the call with a clear {2}.', 'SBAR begins with the situation and ends with a recommendation to the provider.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"situation"},{"id":"c2","text":"discharge date"},{"id":"c3","text":"insurance status"}]},{"id":"b2","choices":[{"id":"c1","text":"recommendation"},{"id":"c2","text":"apology"},{"id":"c3","text":"personal opinion"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff', 'SBAR', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_301024', 'HIGHLIGHT', 'Highlight the actions in the note that violate client confidentiality. The nurse [[verified the client''s identity with two identifiers]], then [[posted the client''s diagnosis on social media]], later [[discussed the case loudly in the cafeteria]], and finally [[reported handoff privately to the oncoming nurse]].', 'Social media posts and public discussion of a client breach confidentiality; ID verification and private handoff do not.', '{"chunks":[{"id":"h1","text":"verified the client''s identity with two identifiers"},{"id":"h2","text":"posted the client''s diagnosis on social media"},{"id":"h3","text":"discussed the case loudly in the cafeteria"},{"id":"h4","text":"reported handoff privately to the oncoming nurse"}]}'::jsonb, '{"correct_ids":["h2","h3"],"feedback":{"h1":"This is safe practice, not a violation.","h2":"Social media posting breaches confidentiality.","h3":"Public discussion breaches confidentiality.","h4":"Private handoff is appropriate."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Fundamentals of Nursing', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_301025', 'BOWTIE', 'A charge nurse is assigning care. Complete the diagram by selecting the situation, the appropriate actions, and what to monitor.', 'Safe delegation assigns appropriate tasks to UAP, keeps assessment/planning with the RN, and monitors task completion and client safety.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Delegate stable-client bathing to UAP"},{"id":"lt2","text":"Keep new admission assessments with the RN"},{"id":"lt3","text":"Assign IV chemotherapy to the UAP"},{"id":"lt4","text":"Have the UAP develop the care plan"}]},"centre":{"label":"Situation","tokens":[{"id":"ct1","text":"Understaffed shift requiring safe delegation"},{"id":"ct2","text":"A cardiac arrest in progress"},{"id":"ct3","text":"A routine discharge with no staffing issue"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Completion of delegated tasks"},{"id":"rt2","text":"Client safety outcomes"},{"id":"rt3","text":"The UAP''s lunch schedule"},{"id":"rt4","text":"The provider''s parking location"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Supervision', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_301026', 'DRAG_CLOZE', 'For a surgical procedure, the [1] is responsible for explaining the risks and benefits, while the [2] witnesses the client''s signature on the consent form.', 'The provider explains the procedure and risks; the nurse witnesses the voluntary signature.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"surgeon"},{"id":"t2","text":"nurse"},{"id":"t3","text":"unit clerk"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_301027', 'DRAG_ORDER', 'A nurse receives a new medication order. Place the steps for safely implementing the order in the correct sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Read and verify the complete order"},{"id":"t2","text":"Clarify any unclear part with the prescriber"},{"id":"t3","text":"Check the medication against the five rights"},{"id":"t4","text":"Administer the medication to the client"},{"id":"t5","text":"Document the administration"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', 'Medication administration', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302001', 'MCQ', 'A charge nurse is delegating tasks to unlicensed assistive personnel (UAP). Which task is most appropriate to delegate?', 'UAP may perform routine, predictable tasks such as vital signs on stable clients; assessment, teaching, and evaluation stay with the nurse.', '{"options":[{"id":"A","text":"Taking routine vital signs on a stable client"},{"id":"B","text":"Teaching a client about a new medication"},{"id":"C","text":"Evaluating a client''s response to therapy"},{"id":"D","text":"Developing the plan of care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Routine vitals on stable clients are within UAP scope.","B":"Incorrect. Client teaching requires a nurse.","C":"Incorrect. Evaluation is a nursing responsibility.","D":"Incorrect. Care planning cannot be delegated to UAP."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302002', 'MCQ', 'A nurse is giving a shift handoff using SBAR. Which information belongs in the ''Background'' component?', 'In SBAR, Background provides context such as the diagnosis and relevant history leading up to the current situation.', '{"options":[{"id":"A","text":"The client''s admitting diagnosis and relevant history"},{"id":"B","text":"The nurse''s recommendation for the next shift"},{"id":"C","text":"The current vital signs and assessment findings"},{"id":"D","text":"The reason the nurse is calling right now"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Background covers diagnosis and pertinent history.","B":"Incorrect. That is the Recommendation.","C":"Incorrect. That is the Assessment.","D":"Incorrect. That is the Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302003', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'Using the ABC framework, a client with respiratory compromise and low oxygen saturation is seen first.', '{"options":[{"id":"A","text":"A client with new-onset shortness of breath and an oxygen saturation of 86%"},{"id":"B","text":"A client requesting pain medication for chronic back pain"},{"id":"C","text":"A client awaiting discharge teaching"},{"id":"D","text":"A client asking for help to the bathroom"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Airway/breathing compromise is the priority.","B":"Incorrect. Stable chronic pain is not the highest priority.","C":"Incorrect. Discharge teaching is not urgent.","D":"Incorrect. Important but not life-threatening."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302004', 'MCQ', 'A client is scheduled for surgery. The nurse''s role regarding informed consent is to:', 'The provider obtains informed consent by explaining the procedure; the nurse witnesses the signature and confirms understanding.', '{"options":[{"id":"A","text":"Witness the client''s signature and verify the client understands"},{"id":"B","text":"Explain the surgical procedure and its risks"},{"id":"C","text":"Decide whether the client should proceed with surgery"},{"id":"D","text":"Sign the consent form on the client''s behalf"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The nurse witnesses consent and confirms understanding.","B":"Incorrect. The provider explains the procedure and risks.","C":"Incorrect. The client makes that decision.","D":"Incorrect. The nurse does not sign for the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302005', 'MCQ', 'Which nurse action is a violation of client confidentiality under HIPAA?', 'Discussing protected health information with people not involved in the client''s care breaches confidentiality.', '{"options":[{"id":"A","text":"Discussing a client''s diagnosis with a friend in the cafeteria"},{"id":"B","text":"Reporting a communicable disease to public health authorities"},{"id":"C","text":"Sharing information with the client''s assigned physician"},{"id":"D","text":"Documenting care in the electronic health record"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sharing client information with non-involved persons violates privacy.","B":"Incorrect. This is a legally required disclosure.","C":"Incorrect. Care-team sharing is permitted.","D":"Incorrect. Documentation is appropriate."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302006', 'MCQ', 'A client asks the nurse about a durable power of attorney for health care. The nurse explains that it:', 'A durable power of attorney for health care designates a proxy to make decisions when the client is unable to.', '{"options":[{"id":"A","text":"Names a person to make health decisions if the client cannot"},{"id":"B","text":"Is a court order that overrides the client''s wishes"},{"id":"C","text":"Only takes effect after the client''s death"},{"id":"D","text":"Requires two physicians to activate at admission"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. It designates a health-care proxy.","B":"Incorrect. It reflects, not overrides, the client''s wishes.","C":"Incorrect. It applies while the client is living but incapacitated.","D":"Incorrect. That is not its definition."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302007', 'MCQ', 'A client tells the nurse he does not understand why a test was ordered and wants more information before consenting. The nurse acts as an advocate by:', 'Advocacy supports the client''s right to be informed; the nurse notifies the provider to answer questions before consent.', '{"options":[{"id":"A","text":"Notifying the provider that the client has questions before signing"},{"id":"B","text":"Telling the client to sign so the test is not delayed"},{"id":"C","text":"Cancelling the test without informing anyone"},{"id":"D","text":"Reassuring the client that the provider knows best"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocacy ensures the client''s concerns are addressed.","B":"Incorrect. This ignores the client''s right to information.","C":"Incorrect. This exceeds the nurse''s authority.","D":"Incorrect. This dismisses the client''s autonomy."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302008', 'MCQ', 'Which task is appropriate for the RN to assign to a licensed practical nurse (LPN)?', 'LPNs can administer routine medications and provide care to stable clients; initial assessment and care planning stay with the RN.', '{"options":[{"id":"A","text":"Administering oral medications to a stable client"},{"id":"B","text":"Performing the initial admission assessment"},{"id":"C","text":"Creating the client''s plan of care"},{"id":"D","text":"Administering the first dose of IV chemotherapy"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. LPNs may administer routine medications to stable clients.","B":"Incorrect. Initial assessment is an RN responsibility.","C":"Incorrect. Care planning is an RN task.","D":"Incorrect. This requires an RN."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'LPN scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302009', 'MCQ', 'A client being discharged will need daily wound care at home but lives alone. The nurse should initiate a referral to:', 'Skilled wound care at home for a client living alone is met by a home health nursing referral.', '{"options":[{"id":"A","text":"Home health nursing services"},{"id":"B","text":"A dietitian"},{"id":"C","text":"Physical therapy"},{"id":"D","text":"Pastoral care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Home health can provide skilled wound care at home.","B":"Incorrect. Nutrition is not the identified need.","C":"Incorrect. Mobility is not the identified need.","D":"Incorrect. Spiritual care is not the identified need."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Referrals', 'Case management', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302010', 'MCQ', 'A nurse suspects that an older adult client is being neglected by a caregiver. The nurse''s legal obligation is to:', 'Nurses are mandatory reporters and must report reasonable suspicion of abuse or neglect to authorities.', '{"options":[{"id":"A","text":"Report the suspicion to the appropriate authorities"},{"id":"B","text":"Wait until there is definitive proof before acting"},{"id":"C","text":"Confront the caregiver directly and alone"},{"id":"D","text":"Ignore it because it is a family matter"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandatory reporters of suspected abuse or neglect.","B":"Incorrect. Reasonable suspicion is enough to report.","C":"Incorrect. This is unsafe and not the nurse''s role.","D":"Incorrect. Failure to report is a legal violation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302011', 'MCQ', 'A nurse reads a new order that is unclear and possibly incorrect. The nurse should:', 'The nurse verifies and clarifies any unclear or questionable order with the prescriber before implementing it.', '{"options":[{"id":"A","text":"Clarify the order with the prescribing provider before acting"},{"id":"B","text":"Carry out the order as written to avoid a delay"},{"id":"C","text":"Ask another nurse to interpret what was meant"},{"id":"D","text":"Document that the order was unclear and take no action"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Unclear or questionable orders must be clarified before implementation.","B":"Incorrect. Implementing an unsafe order is negligent.","C":"Incorrect. Guessing does not verify the order.","D":"Incorrect. The nurse must actively seek clarification."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Order verification', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_302012', 'MCQ', 'When transferring a client to another unit, the most important action to ensure continuity of care is to:', 'A complete handoff report to the receiving nurse ensures safe, continuous care during transfer.', '{"options":[{"id":"A","text":"Provide a complete handoff report to the receiving nurse"},{"id":"B","text":"Send the client''s belongings ahead of the client"},{"id":"C","text":"Delete the previous unit''s documentation"},{"id":"D","text":"Wait for the family to arrive before transferring"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A thorough handoff maintains continuity and safety.","B":"Incorrect. Belongings are secondary to information transfer.","C":"Incorrect. The record must remain intact.","D":"Incorrect. This is not required for continuity."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Continuity of care', 'Transfer', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_302013', 'SATA', 'Which tasks can the nurse appropriately delegate to unlicensed assistive personnel? Select all that apply.', 'UAP may assist with ADLs, collect basic data, and transport stable clients; assessment, medication administration, and evaluation are nursing tasks.', '{"options":[{"id":"A","text":"Assisting a stable client with feeding"},{"id":"B","text":"Measuring and recording intake and output"},{"id":"C","text":"Transporting a stable client to radiology"},{"id":"D","text":"Assessing a new client''s skin integrity on admission"},{"id":"E","text":"Administering an intramuscular injection"},{"id":"F","text":"Evaluating the effect of a pain medication"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_302014', 'SATA', 'Which of the following are basic client rights the nurse must uphold? Select all that apply.', 'Clients have the right to refuse care, to privacy, and to information about their care; they cannot demand any treatment or have their own diagnosis withheld from them.', '{"options":[{"id":"A","text":"The right to refuse treatment"},{"id":"B","text":"The right to privacy and confidentiality"},{"id":"C","text":"The right to be informed about the plan of care"},{"id":"D","text":"The right to demand a specific unproven experimental drug"},{"id":"E","text":"The right to have staff withhold the diagnosis from the client"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_302015', 'SATA', 'Which activities are part of a quality/performance improvement program on a nursing unit? Select all that apply.', 'Quality improvement uses data tracking and non-punitive review of events to identify and correct system problems, not individual blame or concealment.', '{"options":[{"id":"A","text":"Tracking rates of falls and pressure injuries"},{"id":"B","text":"Reviewing near-miss and error reports to find patterns"},{"id":"C","text":"Auditing hand-hygiene compliance"},{"id":"D","text":"Assigning individual blame and disciplining a nurse for a system error"},{"id":"E","text":"Hiding adverse events from the review committee"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality improvement', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_302016', 'SATA', 'Which are principles of accurate nursing documentation? Select all that apply.', 'Documentation should be timely, factual, and objective; errors are corrected with a single line and initials, never pre-charted or erased.', '{"options":[{"id":"A","text":"Chart care promptly after it is provided"},{"id":"B","text":"Record objective, factual observations"},{"id":"C","text":"Draw a single line through an error and initial it"},{"id":"D","text":"Chart interventions before they are performed"},{"id":"E","text":"Use correction fluid to erase mistakes"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_302017', 'SATA', 'A client recovering from a stroke needs a coordinated care team. Which referrals are appropriate for the nurse to help arrange? Select all that apply.', 'Stroke rehabilitation involves a multidisciplinary team; referrals must address genuine client needs, not administrative delay.', '{"options":[{"id":"A","text":"Physical therapy for mobility"},{"id":"B","text":"Speech-language pathology for swallowing"},{"id":"C","text":"Occupational therapy for activities of daily living"},{"id":"D","text":"Social work for discharge planning"},{"id":"E","text":"A referral solely to delay the client''s discharge"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_302018', 'SELECT_N', 'Which 2 clients should the nurse assess first at the start of the shift?', 'Chest pain and severe hypoxia are potentially life-threatening and take priority over stable, routine needs.', '{"options":[{"id":"A","text":"A client with chest pain radiating to the left arm"},{"id":"B","text":"A client with an oxygen saturation of 84% on room air"},{"id":"C","text":"A client requesting a snack"},{"id":"D","text":"A client due for routine morning medications"},{"id":"E","text":"A client waiting for a ride home after discharge"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_302019', 'SELECT_N', 'Which 3 strategies support effective time management for a nurse during a busy shift?', 'Prioritizing by acuity, clustering care, and delegating appropriately are core time-management strategies.', '{"options":[{"id":"A","text":"Prioritizing tasks by client acuity"},{"id":"B","text":"Clustering care activities during one room visit"},{"id":"C","text":"Delegating appropriate tasks to team members"},{"id":"D","text":"Attempting to complete every task alone"},{"id":"E","text":"Postponing all documentation until the end of shift"},{"id":"F","text":"Treating every task as equally urgent"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Time management', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_302020', 'TF', 'A nurse is legally required to report a reasonable suspicion of child abuse even without definitive proof.', 'Nurses are mandatory reporters and must report reasonable suspicion of abuse; proof is not required.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_302021', 'TF', 'Once a nurse delegates a task to unlicensed assistive personnel, the nurse is no longer accountable for the outcome of that task.', 'The delegating nurse retains accountability for the overall outcome and must supervise and follow up on delegated tasks.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Accountability', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_302022', 'MATRIX', 'For each task, click to indicate whether it may be delegated to unlicensed assistive personnel (UAP) or must be performed by the registered nurse (RN).', 'UAP may perform routine ADLs and data collection on stable clients; assessment and care planning require the RN.', '{"row_label":"Task","rows":[{"id":"r1","text":"Recording a stable client''s oral intake"},{"id":"r2","text":"Performing an initial admission assessment"},{"id":"r3","text":"Assisting a stable client to ambulate"},{"id":"r4","text":"Developing the client''s plan of care"},{"id":"r5","text":"Bathing a stable client"}],"columns":[{"id":"c1","text":"Delegate to UAP"},{"id":"c2","text":"Requires RN"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Scope of practice', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_302023', 'MATRIX_MR', 'For each client need, select all disciplines that are appropriate referrals (may be more than one).', 'Referrals are matched to the specific need: financial/discharge concerns to social work, nutrition to the dietitian, and mobility to physical therapy.', '{"row_label":"Scenario","rows":[{"id":"r1","text":"Client needs help affording home medications after discharge"},{"id":"r2","text":"Newly diagnosed diabetic needs meal-planning education"},{"id":"r3","text":"Client is weak and unsteady but wants to return home alone"}],"columns":[{"id":"c1","text":"Physical Therapy"},{"id":"c2","text":"Dietitian"},{"id":"c3","text":"Social Work"}]}'::jsonb, '{"cells":{"r1":["c3"],"r2":["c2"],"r3":["c1","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Referrals', 'Multidisciplinary collaboration', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_302024', 'CLOZE', 'For a valid informed consent, the {1} is responsible for explaining the procedure and its risks, while the nurse is responsible for {2}.', 'The provider explains the procedure and risks; the nurse witnesses the consent and confirms the client understands.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"provider performing the procedure"},{"id":"c2","text":"unit secretary"},{"id":"c3","text":"client''s family"}]},{"id":"b2","choices":[{"id":"c1","text":"witnessing the signature and confirming understanding"},{"id":"c2","text":"deciding whether surgery should occur"},{"id":"c3","text":"signing on the client''s behalf"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_302025', 'HIGHLIGHT', 'Highlight each action that violates client confidentiality. The nurse [[posts a photo of the busy unit on social media showing a client''s face]]. The nurse [[looks up the record of a neighbor who is not assigned to the nurse]]. The nurse [[reports care to the oncoming assigned nurse]]. The nurse [[discusses a celebrity client''s condition with a coworker not involved in the care]]. The nurse [[verifies the client''s identity before giving medication]].', 'Posting identifiable clients online, accessing unassigned records, and discussing clients with uninvolved staff all breach confidentiality; handoff and ID verification are appropriate.', '{"chunks":[{"id":"h1","text":"posts a photo of the busy unit on social media showing a client''s face"},{"id":"h2","text":"looks up the record of a neighbor who is not assigned to the nurse"},{"id":"h3","text":"discusses a celebrity client''s condition with a coworker not involved in the care"},{"id":"h4","text":"reports care to the oncoming assigned nurse"},{"id":"h5","text":"verifies the client''s identity before giving medication"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"Posting an identifiable client online breaches privacy.","h2":"Accessing records without a care reason is a violation.","h3":"Sharing with uninvolved staff violates confidentiality.","h4":"Handoff to the care team is appropriate.","h5":"This is a safe, appropriate action."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_302026', 'BOWTIE', 'A client''s oxygen saturation suddenly drops to 85% with new shortness of breath. Complete the diagram by selecting the priority actions, the priority problem, and the parameters to monitor.', 'Acute hypoxia signals impaired gas exchange; the nurse applies oxygen and positions upright while monitoring oxygenation and respiratory status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Apply supplemental oxygen"},{"id":"lt2","text":"Raise the head of the bed"},{"id":"lt3","text":"Offer the client oral fluids"},{"id":"lt4","text":"Delay reassessment until next rounds"}]},"centre":{"label":"Priority problem","tokens":[{"id":"ct1","text":"Impaired gas exchange"},{"id":"ct2","text":"Risk for constipation"},{"id":"ct3","text":"Deficient knowledge"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate and effort"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Skin turgor"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Deteriorating client', 'Easy', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_302027', 'DRAG_ORDER', 'Place the steps of preparing a client for a safe discharge in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Confirm the provider''s discharge order"},{"id":"t2","text":"Review discharge instructions and medications with the client"},{"id":"t3","text":"Verify the client can teach back the instructions"},{"id":"t4","text":"Arrange needed referrals and follow-up appointments"},{"id":"t5","text":"Escort the client from the unit and document the discharge"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge process', 'Case management', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303001', 'MCQ', 'A charge nurse is assigning tasks. Which task is MOST appropriate to delegate to unlicensed assistive personnel (UAP)?', 'UAP may perform routine, stable tasks such as vital signs; assessment, teaching, and planning stay with the nurse.', '{"options":[{"id":"A","text":"Taking vital signs on a stable client"},{"id":"B","text":"Teaching a client about a new medication"},{"id":"C","text":"Assessing a new admission"},{"id":"D","text":"Developing the plan of care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Routine vital signs on a stable client are within UAP scope.","B":"Incorrect. Client teaching requires a licensed nurse.","C":"Incorrect. Assessment cannot be delegated to UAP.","D":"Incorrect. Care planning is a nursing responsibility."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303002', 'MCQ', 'A nurse is giving a handoff report using SBAR. Which information belongs in the ''Recommendation'' portion?', 'In SBAR, Recommendation states the suggested next action or need.', '{"options":[{"id":"A","text":"Suggesting the client be evaluated by the provider for chest pain"},{"id":"B","text":"The client''s admitting diagnosis"},{"id":"C","text":"The current blood pressure reading"},{"id":"D","text":"The client''s name and room number"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Recommendation states what the nurse thinks should happen next.","B":"Incorrect. That is Background.","C":"Incorrect. That is Assessment.","D":"Incorrect. That is Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff', 'SBAR', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303003', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'Airway and breathing problems take priority over comfort and routine needs (ABCs).', '{"options":[{"id":"A","text":"A client reporting new shortness of breath and oxygen saturation of 86%"},{"id":"B","text":"A client requesting pain medication for a headache"},{"id":"C","text":"A client waiting for discharge teaching"},{"id":"D","text":"A client asking about the lunch menu"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An airway/breathing problem is the highest priority.","B":"Incorrect. Pain is important but not life-threatening.","C":"Incorrect. Discharge teaching is not urgent.","D":"Incorrect. This is a low-priority request."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303004', 'MCQ', 'A client is scheduled for surgery. Whose responsibility is it to obtain informed consent for the procedure?', 'The provider performing the procedure is responsible for obtaining informed consent; the nurse witnesses the signing.', '{"options":[{"id":"A","text":"The surgeon performing the procedure"},{"id":"B","text":"The circulating nurse"},{"id":"C","text":"The unit charge nurse"},{"id":"D","text":"The unlicensed assistive personnel"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The provider performing the procedure obtains informed consent.","B":"Incorrect. The nurse witnesses the signature, not obtains consent.","C":"Incorrect. This is not the charge nurse''s role.","D":"Incorrect. UAP cannot obtain consent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303005', 'MCQ', 'A nurse is discussing a client''s care. Which action best protects client confidentiality?', 'Client information should only be shared with those directly involved in the client''s care.', '{"options":[{"id":"A","text":"Discussing the client only with team members involved in the client''s care"},{"id":"B","text":"Talking about the client in the elevator with a coworker"},{"id":"C","text":"Posting an anonymized case on social media"},{"id":"D","text":"Leaving the client''s chart open at the nurses'' station"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sharing information is limited to those directly involved in care.","B":"Incorrect. Public areas risk breach of confidentiality.","C":"Incorrect. Social media posts about clients violate privacy.","D":"Incorrect. This exposes protected information."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303006', 'MCQ', 'A client asks the nurse what a living will is. Which response by the nurse is correct?', 'A living will documents a client''s wishes for medical treatment should they become unable to communicate.', '{"options":[{"id":"A","text":"\"It states your wishes for medical treatment if you cannot speak for yourself.\""},{"id":"B","text":"\"It transfers all your property to your family.\""},{"id":"C","text":"\"It is a court order requiring specific treatment.\""},{"id":"D","text":"\"It names a person to manage your finances.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A living will documents treatment preferences in advance.","B":"Incorrect. That describes a last will and testament.","C":"Incorrect. It is not a court order.","D":"Incorrect. That describes a power of attorney for finances."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303007', 'MCQ', 'A nurse receives a provider order that is illegible. What should the nurse do?', 'An unclear or illegible order must be clarified with the prescriber before it is carried out.', '{"options":[{"id":"A","text":"Contact the provider to clarify the order"},{"id":"B","text":"Interpret the order based on the client''s diagnosis"},{"id":"C","text":"Ask another nurse to guess the order"},{"id":"D","text":"Skip the order until the next shift"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Unclear orders must be clarified before implementation.","B":"Incorrect. Guessing an order is unsafe.","C":"Incorrect. Guessing risks error.","D":"Incorrect. Delaying may harm the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303008', 'MCQ', 'A client states, "I don''t understand what the surgery involves." Which action by the nurse best demonstrates client advocacy?', 'The nurse advocates by ensuring the client''s questions are answered by the provider before consent is signed.', '{"options":[{"id":"A","text":"Notify the surgeon that the client has questions before signing consent"},{"id":"B","text":"Ask the client to sign and reassure them it will be fine"},{"id":"C","text":"Explain the surgical technique in detail yourself"},{"id":"D","text":"Tell the client to search the internet for information"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocacy ensures the client is fully informed before consenting.","B":"Incorrect. This does not address the knowledge gap.","C":"Incorrect. Explaining the procedure is the surgeon''s role.","D":"Incorrect. This does not advocate for the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303009', 'MCQ', 'A nurse suspects that a child in the emergency department is a victim of abuse. What is the nurse''s legal obligation?', 'Nurses are mandatory reporters and must report reasonable suspicion of child abuse.', '{"options":[{"id":"A","text":"Report the suspicion to child protective services"},{"id":"B","text":"Wait until abuse is proven before reporting"},{"id":"C","text":"Confront the parents directly"},{"id":"D","text":"Do nothing unless the family consents"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandatory reporters of suspected child abuse.","B":"Incorrect. Reporting is based on reasonable suspicion, not proof.","C":"Incorrect. Confrontation is not the nurse''s role.","D":"Incorrect. Consent is not required to report."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303010', 'MCQ', 'A client being discharged will need help with dressing changes at home. Which referral is most appropriate?', 'A home health nursing referral provides skilled care such as dressing changes in the home.', '{"options":[{"id":"A","text":"Home health nursing"},{"id":"B","text":"Physical therapy"},{"id":"C","text":"Speech therapy"},{"id":"D","text":"Financial counseling"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Home health provides skilled wound care in the home.","B":"Incorrect. PT addresses mobility, not wound care.","C":"Incorrect. Speech therapy addresses communication and swallowing.","D":"Incorrect. This does not meet the wound care need."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Referrals', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303011', 'MCQ', 'Which task is within the scope of practice of a licensed practical nurse (LPN)?', 'LPNs may reinforce teaching and perform many tasks, but initial assessment and care planning are RN responsibilities.', '{"options":[{"id":"A","text":"Reinforcing teaching that the RN has already provided"},{"id":"B","text":"Creating the initial nursing care plan"},{"id":"C","text":"Performing the admission assessment"},{"id":"D","text":"Administering the first dose of IV chemotherapy"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. LPNs may reinforce established teaching.","B":"Incorrect. Care planning is an RN function.","C":"Incorrect. Initial assessment is an RN function.","D":"Incorrect. This requires an RN with special certification."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', 'LPN scope', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_303012', 'MCQ', 'A client is being transferred from the ICU to a medical-surgical unit. What is the priority nursing action to ensure continuity of care?', 'A complete handoff report ensures the receiving nurse has the information needed for safe, continuous care.', '{"options":[{"id":"A","text":"Give a complete handoff report to the receiving nurse"},{"id":"B","text":"Delete the ICU documentation"},{"id":"C","text":"Discontinue all current medications"},{"id":"D","text":"Tell the client to explain their own care to the new nurse"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A thorough handoff ensures safe continuity of care.","B":"Incorrect. Records are retained, not deleted.","C":"Incorrect. Medications require a provider order.","D":"Incorrect. The nurse is responsible for the handoff."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Continuity of care', 'Transfer', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_303013', 'SATA', 'Which tasks can the nurse appropriately delegate to unlicensed assistive personnel? Select all that apply.', 'UAP may perform stable ADLs and data collection; evaluation, medication administration, and interpretation are nursing functions.', '{"options":[{"id":"A","text":"Feeding a stable client who has no swallowing difficulty"},{"id":"B","text":"Assisting a client to the bathroom"},{"id":"C","text":"Measuring and recording intake and output"},{"id":"D","text":"Evaluating the effectiveness of a pain medication"},{"id":"E","text":"Administering a subcutaneous injection"},{"id":"F","text":"Interpreting laboratory results"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_303014', 'SATA', 'Which are examples of a client''s rights while hospitalized? Select all that apply.', 'Clients have rights to refuse treatment, privacy, and informed decision-making; they cannot demand unproven treatments or care without documentation.', '{"options":[{"id":"A","text":"The right to refuse treatment"},{"id":"B","text":"The right to privacy and confidentiality"},{"id":"C","text":"The right to receive information to make informed decisions"},{"id":"D","text":"The right to demand a specific unproven experimental drug on request"},{"id":"E","text":"The right to have all care provided without any documentation"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_303015', 'SATA', 'Which are principles of accurate nursing documentation? Select all that apply.', 'Documentation should be objective, timely, and errors corrected transparently; blank spaces and pre-charting are unsafe.', '{"options":[{"id":"A","text":"Chart objectively and factually"},{"id":"B","text":"Document care as soon as possible after it is provided"},{"id":"C","text":"Correct errors by drawing a single line through them and initialing"},{"id":"D","text":"Leave blank spaces so others can add entries later"},{"id":"E","text":"Chart interventions in advance before performing them"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_303016', 'SATA', 'A nurse is coordinating an interdisciplinary team. Which team members might contribute to a stroke client''s rehabilitation plan? Select all that apply.', 'Rehabilitation of a stroke client involves PT, OT, speech therapy, and nutrition; uninvolved community members are not team members.', '{"options":[{"id":"A","text":"Physical therapist"},{"id":"B","text":"Speech-language pathologist"},{"id":"C","text":"Occupational therapist"},{"id":"D","text":"Dietitian"},{"id":"E","text":"The client''s next-door neighbor"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_303017', 'SATA', 'Which actions are part of a quality/performance improvement process on a nursing unit? Select all that apply.', 'Quality improvement uses data, trend analysis, and evidence-based change; it is non-punitive and includes near-misses.', '{"options":[{"id":"A","text":"Collecting data on medication error rates"},{"id":"B","text":"Identifying trends that can be improved"},{"id":"C","text":"Implementing evidence-based changes"},{"id":"D","text":"Assigning blame to individual staff for every error"},{"id":"E","text":"Ignoring near-miss events because no harm occurred"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality improvement', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_303018', 'SELECT_N', 'A nurse is prioritizing care for a group of clients. Which 2 clients should be seen first?', 'Airway compromise and new neurological changes are urgent and take priority over comfort and routine needs.', '{"options":[{"id":"A","text":"A client with an oxygen saturation of 84% and labored breathing"},{"id":"B","text":"A client with new confusion and slurred speech"},{"id":"C","text":"A client requesting a warm blanket"},{"id":"D","text":"A client waiting for routine morning medications"},{"id":"E","text":"A client asking when discharge paperwork will be ready"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', 'Acuity', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_303019', 'TF', 'A registered nurse may delegate the initial assessment of a newly admitted client to unlicensed assistive personnel.', 'Initial assessment requires nursing judgment and cannot be delegated to UAP; it remains an RN responsibility.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_303020', 'TF', 'A competent adult client has the right to refuse a prescribed treatment even if the nurse disagrees with the decision.', 'Competent adults have the legal right to refuse treatment; the nurse''s role is to ensure the decision is informed.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_303021', 'MATRIX', 'For each task, click to indicate whether it can be delegated to a UAP or must be performed by the RN.', 'Stable ADLs and routine data collection are UAP tasks; care planning and teaching are RN-only functions.', '{"row_label":"Task","rows":[{"id":"r1","text":"Assisting a stable client with a bath"},{"id":"r2","text":"Obtaining a routine blood pressure"},{"id":"r3","text":"Developing the plan of care"},{"id":"r4","text":"Providing discharge teaching"}],"columns":[{"id":"c1","text":"Delegate to UAP"},{"id":"c2","text":"RN only"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_303022', 'MATRIX_MR', 'For each task, select every provider who may appropriately perform it.', 'Vital signs are within all three roles; reinforcing teaching is RN/LPN; initial assessment is RN only.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Measuring routine vital signs on a stable client"},{"id":"r2","text":"Reinforcing previously provided teaching"},{"id":"r3","text":"Performing the initial admission assessment"}],"columns":[{"id":"c1","text":"RN"},{"id":"c2","text":"LPN"},{"id":"c3","text":"UAP"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1","c2"],"r3":["c1"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'LPN and RN roles', 'Easy', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_303023', 'CLOZE', 'When prioritizing care using the ABC framework, the nurse addresses a client''s {1} before attending to a client''s {2}.', 'Airway problems are addressed first; a stable comfort need such as chronic pain is lower priority.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"airway obstruction"},{"id":"c2","text":"request for a snack"},{"id":"c3","text":"discharge paperwork"}]},{"id":"b2","choices":[{"id":"c1","text":"mild chronic knee pain"},{"id":"c2","text":"sudden absent breath sounds"},{"id":"c3","text":"severe active bleeding"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritization', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_303024', 'HIGHLIGHT', 'Highlight each action that would violate client confidentiality. The nurse [[discusses the client''s diagnosis with a friend who is not involved in care]]. The nurse [[reports the client''s status to the oncoming nurse]]. The nurse [[posts details about the client on social media]]. The nurse [[leaves the computer logged in and unattended]]. The nurse [[shares information with the treating physician]].', 'Disclosures to those not involved in care and unsecured records violate confidentiality; sharing with caregivers does not.', '{"chunks":[{"id":"h1","text":"discusses the client''s diagnosis with a friend who is not involved in care"},{"id":"h2","text":"reports the client''s status to the oncoming nurse"},{"id":"h3","text":"posts details about the client on social media"},{"id":"h4","text":"leaves the computer logged in and unattended"},{"id":"h5","text":"shares information with the treating physician"}]}'::jsonb, '{"correct_ids":["h1","h3","h4"],"feedback":{"h1":"Violation — sharing with someone not involved in care.","h2":"Appropriate — handoff to a caregiver is permitted.","h3":"Violation — social media disclosure breaches privacy.","h4":"Violation — exposes protected information.","h5":"Appropriate — the physician is involved in care."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_303025', 'BOWTIE', 'A nurse is planning assignments for the shift. Complete the diagram to reflect safe delegation.', 'Stable, routine tasks are delegated; assessment and teaching stay with the RN, guided by scope of practice.', '{"left":{"label":"Appropriate to delegate to UAP","tokens":[{"id":"lt1","text":"Assist a stable client with feeding"},{"id":"lt2","text":"Record intake and output"},{"id":"lt3","text":"Administer IV push medication"},{"id":"lt4","text":"Evaluate response to therapy"}]},"centre":{"label":"Guiding principle","tokens":[{"id":"ct1","text":"Delegate stable, routine tasks; keep nursing judgment tasks"},{"id":"ct2","text":"Delegate any task to reduce nurse workload"},{"id":"ct3","text":"Never delegate any task to UAP"}]},"right":{"label":"Must remain with the RN","tokens":[{"id":"rt1","text":"Initial client assessment"},{"id":"rt2","text":"Client teaching"},{"id":"rt3","text":"Assisting with ambulation of a stable client"},{"id":"rt4","text":"Taking a routine temperature"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_303026', 'DRAG_CLOZE', 'In SBAR communication, the [1] component states the client''s current problem, and the [2] component provides relevant history.', 'Situation states the current problem; Background provides relevant history in SBAR handoff.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"Situation"},{"id":"t2","text":"Background"},{"id":"t3","text":"Recommendation"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff', 'SBAR', 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_303027', 'DRAG_ORDER', 'Place the steps of the client discharge process in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Confirm the provider''s discharge order"},{"id":"t2","text":"Complete discharge teaching with the client"},{"id":"t3","text":"Verify the client has transportation and prescriptions"},{"id":"t4","text":"Escort the client out per facility policy"},{"id":"t5","text":"Document the discharge"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313001', 'MCQ', 'A nurse is preparing to give a medication and checks the client''s name and date of birth on the wristband against the medication record. Which of the six rights of medication administration is the nurse verifying?', 'Checking two identifiers on the wristband confirms the right client before administration.', '{"options":[{"id":"A","text":"Right client"},{"id":"B","text":"Right dose"},{"id":"C","text":"Right route"},{"id":"D","text":"Right time"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers confirm the right client.","B":"Incorrect. Dose is verified against the order, not the wristband.","C":"Incorrect. Route is how the drug is given.","D":"Incorrect. Time refers to scheduling."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Rights of medication administration', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313002', 'MCQ', 'A nurse is teaching a client about subcutaneous insulin injection. Which injection site rotation instruction is correct?', 'Rotating within one area prevents lipohypertrophy while keeping absorption consistent.', '{"options":[{"id":"A","text":"Rotate sites within the same anatomical area to promote consistent absorption"},{"id":"B","text":"Inject into the same exact spot each time"},{"id":"C","text":"Massage the site vigorously after injecting"},{"id":"D","text":"Inject only into muscle tissue"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rotating within one area gives predictable absorption and prevents lipohypertrophy.","B":"Incorrect. This causes lipohypertrophy and erratic absorption.","C":"Incorrect. Massaging alters absorption rate.","D":"Incorrect. Insulin is given subcutaneously."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin administration', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313003', 'MCQ', 'A client is prescribed warfarin. Which laboratory value should the nurse monitor to evaluate the therapeutic effect?', 'The INR is used to monitor and adjust warfarin therapy.', '{"options":[{"id":"A","text":"INR"},{"id":"B","text":"Serum potassium"},{"id":"C","text":"Blood glucose"},{"id":"D","text":"Serum creatinine"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. INR monitors warfarin therapy.","B":"Incorrect. Not used to monitor warfarin.","C":"Incorrect. Unrelated to warfarin.","D":"Incorrect. Reflects renal function, not warfarin effect."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313004', 'MCQ', 'A nurse administers morphine to a client for pain. Which assessment is the priority before and after administration?', 'Respiratory depression is the most dangerous opioid effect, making respiratory rate the priority.', '{"options":[{"id":"A","text":"Respiratory rate"},{"id":"B","text":"Bowel sounds"},{"id":"C","text":"Pupil color"},{"id":"D","text":"Skin turgor"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Opioids depress respiration; this is the priority assessment.","B":"Incorrect. Constipation matters but is not the priority safety concern.","C":"Incorrect. Pupil size may change but is not the priority.","D":"Incorrect. Not related to opioid safety."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioid analgesics', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313005', 'MCQ', 'Which medication is the antidote for opioid-induced respiratory depression?', 'Naloxone is the opioid antagonist used to reverse respiratory depression.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Flumazenil"},{"id":"C","text":"Protamine sulfate"},{"id":"D","text":"Vitamin K"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone reverses opioid effects.","B":"Incorrect. Flumazenil reverses benzodiazepines.","C":"Incorrect. Reverses heparin.","D":"Incorrect. Reverses warfarin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioid reversal', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313006', 'MCQ', 'A client is taking furosemide. Which electrolyte imbalance should the nurse monitor for?', 'Furosemide, a loop diuretic, causes potassium loss and risk of hypokalemia.', '{"options":[{"id":"A","text":"Hypokalemia"},{"id":"B","text":"Hyperkalemia"},{"id":"C","text":"Hypercalcemia"},{"id":"D","text":"Hypernatremia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Loop diuretics cause potassium loss.","B":"Incorrect. This occurs with potassium-sparing diuretics.","C":"Incorrect. Furosemide promotes calcium loss.","D":"Incorrect. Sodium is lost with furosemide."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313007', 'MCQ', 'Before administering the first dose of an antibiotic, which pre-administration data is most important for the nurse to review?', 'Reviewing allergy history before the first antibiotic dose prevents anaphylaxis.', '{"options":[{"id":"A","text":"The client''s drug allergy history"},{"id":"B","text":"The client''s favorite foods"},{"id":"C","text":"The client''s exercise routine"},{"id":"D","text":"The client''s sleep schedule"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Allergy history prevents a serious reaction.","B":"Incorrect. Not relevant to safety.","C":"Incorrect. Not a priority.","D":"Incorrect. Not the priority pre-administration check."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotic administration', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313008', 'MCQ', 'A nurse notes redness, warmth, and tenderness along the vein at a peripheral IV site. Which action should the nurse take FIRST?', 'Redness, warmth, and tenderness indicate phlebitis; the catheter must be removed.', '{"options":[{"id":"A","text":"Discontinue the IV and remove the catheter"},{"id":"B","text":"Increase the infusion rate"},{"id":"C","text":"Apply a cold pack and continue the infusion"},{"id":"D","text":"Flush the line with heparin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are signs of phlebitis; stop the infusion and remove the catheter.","B":"Incorrect. This worsens the problem.","C":"Incorrect. The catheter should be removed first.","D":"Incorrect. Do not flush an inflamed site."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'IV site care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313009', 'MCQ', 'A nurse wastes a partial dose of a controlled opioid. Which action is required?', 'Wasting a controlled substance requires witness verification and co-signature.', '{"options":[{"id":"A","text":"Have a second licensed nurse witness and co-sign the waste"},{"id":"B","text":"Discard the remainder privately and document later"},{"id":"C","text":"Return the remaining medication to the stock bottle"},{"id":"D","text":"Give the remaining dose to another client in pain"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Controlled-substance waste requires a witness.","B":"Incorrect. A witness is required at the time of waste.","C":"Incorrect. Never return controlled substances to stock.","D":"Incorrect. Medications are client-specific."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Controlled substances', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_313010', 'MCQ', 'A nurse begins a blood transfusion. During which time period should the nurse remain with the client and monitor most closely?', 'Acute transfusion reactions most often occur in the first 15 minutes, requiring close monitoring.', '{"options":[{"id":"A","text":"The first 15 minutes"},{"id":"B","text":"The last 15 minutes"},{"id":"C","text":"Only after the transfusion is complete"},{"id":"D","text":"Two hours after starting"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Most severe reactions occur early in the transfusion.","B":"Incorrect. Early monitoring is the priority.","C":"Incorrect. Reactions occur during infusion.","D":"Incorrect. The critical window is at the start."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Blood product administration', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_313011', 'TF', 'Only 0.9% normal saline should be used to prime tubing and administer with a blood transfusion.', 'Normal saline is the only compatible IV fluid for blood products; dextrose causes hemolysis and lactated Ringer''s causes clotting.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Blood product administration', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_313012', 'SATA', 'A nurse monitors a client receiving a blood transfusion. Which findings suggest an acute transfusion reaction? Select all that apply.', 'Fever, chills, back pain, hives, and dyspnea are classic signs of a transfusion reaction.', '{"options":[{"id":"A","text":"Fever and chills"},{"id":"B","text":"Low back pain"},{"id":"C","text":"Hives and itching"},{"id":"D","text":"Dyspnea"},{"id":"E","text":"Gradual improvement in energy"},{"id":"F","text":"Normal blood pressure with no symptoms"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Acute transfusion reaction', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_313013', 'SATA', 'A nurse is preparing to administer oral medications. Which actions promote safe medication administration? Select all that apply.', 'Verification, identifiers, allergy checks, and timely documentation are core safe-administration practices.', '{"options":[{"id":"A","text":"Verify the medication against the order three times"},{"id":"B","text":"Use two client identifiers"},{"id":"C","text":"Check for allergies before giving"},{"id":"D","text":"Document the medication after it is given"},{"id":"E","text":"Leave medications at the bedside for later"},{"id":"F","text":"Crush all tablets to make swallowing easier"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Safe medication administration', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_313014', 'SATA', 'A nurse teaches a client about insulin storage and use. Which statements by the client indicate correct understanding? Select all that apply.', 'Insulin is refrigerated when unopened, gently mixed if cloudy, and never used if frozen or discolored.', '{"options":[{"id":"A","text":"I will keep my unopened insulin in the refrigerator"},{"id":"B","text":"I will roll cloudy insulin gently between my hands to mix it"},{"id":"C","text":"I will check the expiration date before use"},{"id":"D","text":"I will inject cold insulin straight from the freezer"},{"id":"E","text":"I will use insulin that looks discolored or clumped"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin education', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_313015', 'SATA', 'A nurse teaches a client taking warfarin at home. Which instructions are appropriate? Select all that apply.', 'Warfarin clients monitor for bleeding, prevent injury, keep vitamin K consistent, and avoid extra doses or aspirin.', '{"options":[{"id":"A","text":"Report unusual bruising or bleeding"},{"id":"B","text":"Use a soft toothbrush and electric razor"},{"id":"C","text":"Keep a consistent intake of vitamin K foods"},{"id":"D","text":"Take extra doses if you miss one"},{"id":"E","text":"Take aspirin freely for headaches"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulant education', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_313016', 'SATA', 'A nurse prepares to administer digoxin to a client. Which nursing actions are appropriate? Select all that apply.', 'Digoxin requires apical pulse assessment, holding for bradycardia, and monitoring potassium.', '{"options":[{"id":"A","text":"Count the apical pulse for one full minute before giving"},{"id":"B","text":"Hold the dose if the apical pulse is below 60 bpm"},{"id":"C","text":"Monitor the serum potassium level"},{"id":"D","text":"Administer without checking the heart rate"},{"id":"E","text":"Give the dose if the pulse is 44 bpm"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin administration', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_313017', 'SELECT_N', 'A nurse monitors a peripheral IV infusion. Which 2 findings indicate infiltration?', 'Infiltration causes cool, swollen tissue and slowed flow as fluid leaks into surrounding tissue.', '{"options":[{"id":"A","text":"Cool, swollen skin around the site"},{"id":"B","text":"Slowed or stopped infusion flow"},{"id":"C","text":"Red streak up the vein"},{"id":"D","text":"Purulent drainage at the site"},{"id":"E","text":"Warmth and fever"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'IV infusion monitoring', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_313018', 'MATRIX', 'For each medication, click to specify its correct reversal agent (antidote).', 'Vitamin K reverses warfarin, protamine reverses heparin, and naloxone reverses opioids.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Warfarin"},{"id":"r2","text":"Heparin"},{"id":"r3","text":"Morphine"},{"id":"r4","text":"Fentanyl"}],"columns":[{"id":"c1","text":"Vitamin K"},{"id":"c2","text":"Protamine sulfate"},{"id":"c3","text":"Naloxone"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c3"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication reversal agents', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_313019', 'MATRIX_MR', 'For each injection route, select all correct descriptors (may apply to more than one).', 'Subcutaneous and insulin injections go into subcutaneous tissue; IM injections go into muscle; all use a 45-90 degree angle range.', '{"row_label":"Route","rows":[{"id":"r1","text":"Subcutaneous injection"},{"id":"r2","text":"Intramuscular injection"},{"id":"r3","text":"Insulin injection"}],"columns":[{"id":"c1","text":"Uses a 45-90 degree angle"},{"id":"c2","text":"Given into subcutaneous tissue"},{"id":"c3","text":"Given into muscle"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1","c3"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Injection routes', NULL, 'Easy', 'Understand', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_313020', 'CLOZE', 'A nurse administers regular insulin. This insulin is classified as {1} and the nurse should watch for hypoglycemia around {2} after administration.', 'Regular insulin is short-acting with a peak around 2 to 4 hours, when hypoglycemia is most likely.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"short-acting"},{"id":"c2","text":"long-acting"},{"id":"c3","text":"intermediate-acting"}]},{"id":"b2","choices":[{"id":"c1","text":"2 to 4 hours"},{"id":"c2","text":"18 hours"},{"id":"c3","text":"5 minutes"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin onset', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_313021', 'HIGHLIGHT', 'A nurse reviews a client 30 minutes after giving morphine. Highlight the findings that require immediate follow-up. The client reports [[relief of pain]]. Respiratory rate [[8 breaths per minute]]. The client is [[very difficult to arouse]]. SpO2 [[97% on room air]]. Blood pressure 118/74.', 'A low respiratory rate and excessive sedation after an opioid indicate dangerous respiratory depression.', '{"chunks":[{"id":"h1","text":"relief of pain"},{"id":"h2","text":"8 breaths per minute"},{"id":"h3","text":"very difficult to arouse"},{"id":"h4","text":"97% on room air"}]}'::jsonb, '{"correct_ids":["h2","h3"],"feedback":{"h1":"This is the desired effect, no follow-up needed.","h2":"Respiratory depression requires immediate follow-up.","h3":"Excessive sedation signals opioid toxicity.","h4":"Normal oxygen saturation, no follow-up needed."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioid adverse effects', NULL, 'Easy', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_313022', 'BOWTIE', 'A client taking insulin becomes shaky, diaphoretic, and has a blood glucose of 54 mg/dL. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Hypoglycemia is treated with fast-acting carbohydrate and rechecking glucose, while monitoring glucose and level of consciousness.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Give 15 g of a fast-acting carbohydrate"},{"id":"lt2","text":"Recheck blood glucose in 15 minutes"},{"id":"lt3","text":"Administer a rapid dose of insulin"},{"id":"lt4","text":"Withhold all food and fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Hypoglycemia"},{"id":"ct2","text":"Diabetic ketoacidosis"},{"id":"ct3","text":"Hyperosmolar state"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood glucose level"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Urine ketones"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Hypoglycemia management', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_313023', 'DRAG_CLOZE', 'Before giving digoxin, the nurse counts the [1] for one full minute and holds the dose if the rate is below [2] beats per minute.', 'Digoxin requires a one-minute apical pulse; the dose is held for a rate below 60 bpm.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"apical pulse"},{"id":"t2","text":"60"},{"id":"t3","text":"radial pulse"},{"id":"t4","text":"100"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin safety', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_313024', 'DRAG_ORDER', 'Place the steps for administering an intramuscular injection in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and don gloves"},{"id":"t2","text":"Cleanse the injection site with an alcohol swab"},{"id":"t3","text":"Insert the needle at a 90-degree angle"},{"id":"t4","text":"Inject the medication slowly"},{"id":"t5","text":"Withdraw the needle and apply gentle pressure"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IM injection procedure', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314001', 'MCQ', 'A nurse is teaching a client who takes warfarin. Which routine laboratory test is used to monitor the therapeutic effect of this medication?', 'Warfarin therapy is monitored using the INR to keep clotting within a therapeutic range.', '{"options":[{"id":"A","text":"INR (international normalized ratio)"},{"id":"B","text":"Serum potassium"},{"id":"C","text":"Fasting blood glucose"},{"id":"D","text":"Serum creatinine"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. INR monitors warfarin''s anticoagulant effect.","B":"Incorrect. Potassium is not used to monitor warfarin.","C":"Incorrect. Glucose is unrelated to warfarin monitoring.","D":"Incorrect. Creatinine monitors renal function, not warfarin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314002', 'MCQ', 'A nurse prepares to administer lispro (rapid-acting) insulin to a client before breakfast. When should the nurse administer this insulin?', 'Rapid-acting insulins such as lispro have a quick onset and are given within 15 minutes of the meal.', '{"options":[{"id":"A","text":"Within 15 minutes before the meal"},{"id":"B","text":"One hour after the meal"},{"id":"C","text":"At bedtime only"},{"id":"D","text":"Two hours before the meal"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rapid-acting insulin is given right before eating.","B":"Incorrect. Giving it after the meal risks hyperglycemia then hypoglycemia.","C":"Incorrect. Bedtime dosing is for long-acting insulin.","D":"Incorrect. This risks hypoglycemia before food is eaten."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Rapid-acting insulin', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314003', 'MCQ', 'A nurse is reviewing the rights of medication administration. Which of the following is one of the recognized rights?', 'The rights include right client, drug, dose, route, time, and documentation.', '{"options":[{"id":"A","text":"Right dose"},{"id":"B","text":"Right pharmacy"},{"id":"C","text":"Right insurance"},{"id":"D","text":"Right manufacturer"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Right dose is a core right of medication administration.","B":"Incorrect. This is not one of the rights.","C":"Incorrect. This is not a right of administration.","D":"Incorrect. This is not a right of administration."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Rights of medication administration', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314004', 'MCQ', 'A client who received morphine has a respiratory rate of 6 breaths/min and is difficult to arouse. Which medication should the nurse anticipate administering?', 'Naloxone is the opioid antagonist used to reverse respiratory depression from opioids.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Flumazenil"},{"id":"C","text":"Protamine sulfate"},{"id":"D","text":"Vitamin K"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone reverses opioid-induced respiratory depression.","B":"Incorrect. Flumazenil reverses benzodiazepines, not opioids.","C":"Incorrect. Protamine reverses heparin.","D":"Incorrect. Vitamin K reverses warfarin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Naloxone', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314005', 'MCQ', 'A nurse is administering furosemide to a client. Which electrolyte should the nurse monitor most closely because of this drug?', 'Loop diuretics such as furosemide promote potassium excretion, risking hypokalemia.', '{"options":[{"id":"A","text":"Potassium"},{"id":"B","text":"Calcium only"},{"id":"C","text":"Phosphate"},{"id":"D","text":"Chloride only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Furosemide causes potassium loss (hypokalemia).","B":"Incorrect. Potassium is the primary concern.","C":"Incorrect. Phosphate is not the main concern with furosemide.","D":"Incorrect. Potassium loss is the priority monitoring focus."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Furosemide', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314006', 'MCQ', 'A nurse notes swelling, coolness, and pallor at a peripheral IV site with a sluggish flow. Which action should the nurse take FIRST?', 'Swelling, coolness, and pallor indicate infiltration; the infusion is stopped and the catheter removed.', '{"options":[{"id":"A","text":"Stop the infusion and remove the catheter"},{"id":"B","text":"Increase the infusion rate"},{"id":"C","text":"Apply a warm compress and continue"},{"id":"D","text":"Flush the line with saline under pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are signs of infiltration; the IV should be stopped and discontinued.","B":"Incorrect. Increasing the rate worsens tissue infiltration.","C":"Incorrect. Continuing the infusion into tissue causes harm.","D":"Incorrect. Flushing pushes more fluid into the tissue."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV site care', 'Infiltration', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314007', 'MCQ', 'A nurse wastes a partial dose of a controlled opioid. Which action is required?', 'Wasting a controlled substance must be witnessed and co-signed by a second nurse.', '{"options":[{"id":"A","text":"Have a second nurse witness and co-sign the waste"},{"id":"B","text":"Discard it privately and document later"},{"id":"C","text":"Return the remainder to the client''s drawer"},{"id":"D","text":"Give the remaining amount to another client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Controlled-substance waste requires a witness and co-signature.","B":"Incorrect. Waste must be witnessed.","C":"Incorrect. Leftover controlled drugs are never returned to stock.","D":"Incorrect. Medications are never shared between clients."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Controlled substances', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314008', 'MCQ', 'Before administering a first dose of penicillin, which pre-administration action is most important for the nurse to perform?', 'Assessing for allergies before a first antibiotic dose prevents a serious hypersensitivity reaction.', '{"options":[{"id":"A","text":"Ask the client about drug allergies"},{"id":"B","text":"Check the client''s blood glucose"},{"id":"C","text":"Weigh the client''s daily intake"},{"id":"D","text":"Obtain a 12-lead ECG"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Screening for allergies prevents an anaphylactic reaction.","B":"Incorrect. Glucose is unrelated to penicillin safety.","C":"Incorrect. This is not the priority before penicillin.","D":"Incorrect. An ECG is not required before penicillin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Allergy screening', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314009', 'MCQ', 'A nurse is preparing to hang a unit of packed red blood cells. Which IV solution should be used to prime the line?', 'Only 0.9% normal saline is compatible with blood products; other fluids cause hemolysis or clotting.', '{"options":[{"id":"A","text":"0.9% sodium chloride (normal saline)"},{"id":"B","text":"5% dextrose in water"},{"id":"C","text":"Lactated Ringer''s solution"},{"id":"D","text":"0.45% sodium chloride"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Normal saline is the only compatible solution for blood.","B":"Incorrect. Dextrose causes red cell hemolysis.","C":"Incorrect. The calcium in LR can cause clotting.","D":"Incorrect. Only 0.9% normal saline is compatible."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood product administration', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314010', 'MCQ', 'A nurse teaches a client starting an antihypertensive medication. Which instruction helps prevent orthostatic hypotension?', 'Rising slowly gives the cardiovascular system time to adjust, preventing orthostatic hypotension.', '{"options":[{"id":"A","text":"Rise slowly from a sitting or lying position"},{"id":"B","text":"Stand up quickly to keep blood flowing"},{"id":"C","text":"Skip the dose if you feel fine"},{"id":"D","text":"Double the dose if a reading is high"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Changing position slowly prevents dizziness and falls.","B":"Incorrect. Rising quickly worsens orthostatic drops.","C":"Incorrect. Doses should not be skipped.","D":"Incorrect. Clients should never self-adjust doses."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'Orthostatic hypotension', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_314011', 'MCQ', 'A client is receiving total parenteral nutrition (TPN). Which laboratory value should the nurse monitor most frequently?', 'TPN contains concentrated dextrose, so blood glucose is monitored closely for hyperglycemia.', '{"options":[{"id":"A","text":"Blood glucose"},{"id":"B","text":"Serum amylase"},{"id":"C","text":"Urine specific gravity"},{"id":"D","text":"Serum bilirubin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TPN''s high dextrose content requires frequent glucose monitoring.","B":"Incorrect. Amylase is not the priority TPN value.","C":"Incorrect. This is not the primary TPN concern.","D":"Incorrect. Bilirubin is not routinely monitored with TPN."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Parenteral nutrition', 'TPN', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_314012', 'SATA', 'A nurse reviews safe practices for high-alert medications. Which actions are appropriate? Select all that apply.', 'Independent double-checks, second-nurse verification, smart pumps, and clear labeling reduce errors with high-alert drugs.', '{"options":[{"id":"A","text":"Use an independent double-check for IV heparin"},{"id":"B","text":"Store concentrated electrolytes in patient care units without restriction"},{"id":"C","text":"Verify insulin doses with a second nurse"},{"id":"D","text":"Use a smart infusion pump with dose limits for high-risk drips"},{"id":"E","text":"Label all high-alert medications clearly"},{"id":"F","text":"Round all dosage calculations up to the nearest whole number"}]}'::jsonb, '{"answers":["A","C","D","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', 'Safe handling', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_314013', 'SATA', 'A nurse teaches a client about signs of hypoglycemia from insulin. Which signs should the client watch for? Select all that apply.', 'Shakiness, sweating, confusion, and palpitations are classic signs of hypoglycemia; thirst and fruity breath suggest hyperglycemia.', '{"options":[{"id":"A","text":"Shakiness"},{"id":"B","text":"Sweating"},{"id":"C","text":"Confusion"},{"id":"D","text":"Increased thirst"},{"id":"E","text":"Fruity breath odor"},{"id":"F","text":"Palpitations"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Hypoglycemia', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_314014', 'SATA', 'A nurse suspects a transfusion reaction during a blood transfusion. Which immediate actions are appropriate? Select all that apply.', 'Stopping the transfusion, maintaining saline access, notifying the provider, and monitoring vitals are priority actions; the bag is kept for testing.', '{"options":[{"id":"A","text":"Stop the transfusion"},{"id":"B","text":"Keep the IV line open with normal saline"},{"id":"C","text":"Notify the provider"},{"id":"D","text":"Continue the transfusion at a slower rate"},{"id":"E","text":"Discard the blood bag immediately"},{"id":"F","text":"Monitor the client''s vital signs"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood transfusion reaction', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_314015', 'SATA', 'A nurse performs medication reconciliation on admission. Which information should the nurse collect? Select all that apply.', 'Reconciliation captures all prescription, OTC, and herbal products plus allergies to prevent errors and interactions.', '{"options":[{"id":"A","text":"Prescription medication names and doses"},{"id":"B","text":"Over-the-counter medications"},{"id":"C","text":"Herbal and dietary supplements"},{"id":"D","text":"The client''s favorite foods"},{"id":"E","text":"Known medication allergies"},{"id":"F","text":"The client''s employer name"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication reconciliation', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_314016', 'SATA', 'A nurse teaches a client about safe medication storage and disposal at home. Which instructions are correct? Select all that apply.', 'Original containers, child safety, take-back programs, and cool dry storage promote safety; sharing drugs and humid storage are unsafe.', '{"options":[{"id":"A","text":"Keep medications in their original labeled containers"},{"id":"B","text":"Store medications out of the reach of children"},{"id":"C","text":"Use a drug take-back program for unused opioids"},{"id":"D","text":"Share leftover antibiotics with family members who feel ill"},{"id":"E","text":"Keep medications in a cool, dry place away from heat"},{"id":"F","text":"Store all medications in a bathroom cabinet for humidity"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Safe storage and disposal', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_314017', 'SELECT_N', 'Before administering digoxin, which 2 assessments should the nurse complete?', 'Digoxin requires an apical pulse check (hold if below 60) and potassium review, since hypokalemia increases toxicity risk.', '{"options":[{"id":"A","text":"Count the apical heart rate for one full minute"},{"id":"B","text":"Review the most recent serum potassium level"},{"id":"C","text":"Measure the client''s height"},{"id":"D","text":"Check the client''s visual acuity chart"},{"id":"E","text":"Obtain a urine culture"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', 'Pre-administration check', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_314018', 'TF', 'Protamine sulfate is the antidote used to reverse the effects of heparin.', 'Protamine sulfate neutralizes heparin and is used to reverse excessive anticoagulation.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin antidote', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_314019', 'MATRIX', 'For each medication, click to indicate its correct reversal agent.', 'Naloxone reverses opioids (morphine, hydromorphone, fentanyl); vitamin K reverses warfarin.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Morphine"},{"id":"r2","text":"Warfarin"},{"id":"r3","text":"Hydromorphone"},{"id":"r4","text":"Fentanyl"}],"columns":[{"id":"c1","text":"Naloxone"},{"id":"c2","text":"Vitamin K"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication-antidote pairing', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_314020', 'MATRIX_MR', 'For each site, select all injection routes that are appropriate (may support more than one).', 'The deltoid and vastus lateralis are IM sites; the abdomen and fatty upper arm are subcutaneous sites.', '{"row_label":"Route","rows":[{"id":"r1","text":"Deltoid"},{"id":"r2","text":"Abdomen"},{"id":"r3","text":"Vastus lateralis"},{"id":"r4","text":"Upper outer arm (fatty tissue)"}],"columns":[{"id":"c1","text":"Subcutaneous"},{"id":"c2","text":"Intramuscular"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1"],"r3":["c2"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Injection routes', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_314021', 'CLOZE', 'When mixing two insulins in one syringe, the nurse draws up the {1} insulin first, then the {2} insulin, to avoid contaminating the vial.', 'The clear (regular) insulin is drawn first, then the cloudy (NPH), to prevent contaminating the clear vial.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"clear (regular)"},{"id":"c2","text":"cloudy (NPH)"}]},{"id":"b2","choices":[{"id":"c1","text":"cloudy (NPH)"},{"id":"c2","text":"clear (regular)"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Mixing insulins', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_314022', 'HIGHLIGHT', 'The nurse assesses a peripheral IV site. Highlight the findings that indicate phlebitis and require intervention. The site shows [[redness along the vein]], the dressing is [[clean and dry]], there is [[warmth to the touch]], the client reports [[tenderness]], and the flush was [[without resistance]].', 'Redness, warmth, and tenderness along the vein are classic signs of phlebitis requiring catheter removal.', '{"chunks":[{"id":"h1","text":"redness along the vein"},{"id":"h2","text":"clean and dry"},{"id":"h3","text":"warmth to the touch"},{"id":"h4","text":"tenderness"},{"id":"h5","text":"without resistance"}]}'::jsonb, '{"correct_ids":["h1","h3","h4"],"feedback":{"h1":"Redness along the vein is a sign of phlebitis.","h2":"A clean dry dressing is a normal finding.","h3":"Warmth indicates inflammation of the vein.","h4":"Tenderness along the vein suggests phlebitis.","h5":"A flush without resistance is a normal finding."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV complications', 'Phlebitis', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_314023', 'BOWTIE', 'A client has opioid-induced respiratory depression. Complete the diagram by selecting the actions to take, the condition, and the parameters to monitor.', 'Opioid respiratory depression is treated with naloxone and airway support, monitoring respiratory rate and oxygen saturation.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer naloxone as prescribed"},{"id":"lt2","text":"Stimulate and support the airway"},{"id":"lt3","text":"Administer an additional opioid dose"},{"id":"lt4","text":"Encourage the client to walk"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Opioid-induced respiratory depression"},{"id":"ct2","text":"Anaphylaxis"},{"id":"ct3","text":"Hypoglycemia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Respiratory rate"},{"id":"rt2","text":"Oxygen saturation"},{"id":"rt3","text":"Blood glucose"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioid overdose', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_314024', 'DRAG_ORDER', 'Place the steps for administering an intramuscular injection in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and don gloves"},{"id":"t2","text":"Cleanse the injection site with an antiseptic swab"},{"id":"t3","text":"Insert the needle at a 90-degree angle"},{"id":"t4","text":"Inject the medication steadily"},{"id":"t5","text":"Withdraw the needle and dispose of it in a sharps container"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IM injection procedure', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315001', 'MCQ', 'A nurse is preparing to administer a scheduled oral medication. Which action verifies the correct client before giving the drug?', 'Two client identifiers are the standard for confirming the right client before administration.', '{"options":[{"id":"A","text":"Check two client identifiers such as name and date of birth"},{"id":"B","text":"Ask the roommate to confirm the client''s name"},{"id":"C","text":"Match the room number to the medication record"},{"id":"D","text":"Confirm the client answers to the name called out"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers confirm the right client.","B":"Incorrect. Others should not verify identity.","C":"Incorrect. Room numbers change and are unreliable.","D":"Incorrect. Confused clients may answer to any name."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Rights of administration', 'Client identification', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315002', 'MCQ', 'A nurse administers regular insulin at 0800. When should the nurse be most alert for signs of hypoglycemia?', 'Regular (short-acting) insulin peaks in roughly 2 to 4 hours, the period of highest hypoglycemia risk.', '{"options":[{"id":"A","text":"Within 15 minutes"},{"id":"B","text":"2 to 4 hours later"},{"id":"C","text":"10 to 12 hours later"},{"id":"D","text":"24 hours later"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. That reflects rapid-acting insulin.","B":"Correct. Regular insulin peaks in about 2 to 4 hours.","C":"Incorrect. That reflects long-acting insulin.","D":"Incorrect. This is far beyond regular insulin''s action."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Onset of action', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315003', 'MCQ', 'A client taking warfarin has an elevated INR with bleeding. Which medication does the nurse anticipate administering as the antidote?', 'Vitamin K is the antidote for warfarin toxicity.', '{"options":[{"id":"A","text":"Vitamin K (phytonadione)"},{"id":"B","text":"Protamine sulfate"},{"id":"C","text":"Naloxone"},{"id":"D","text":"Flumazenil"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Vitamin K reverses warfarin.","B":"Incorrect. Protamine reverses heparin.","C":"Incorrect. Naloxone reverses opioids.","D":"Incorrect. Flumazenil reverses benzodiazepines."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin antidote', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315004', 'MCQ', 'A client is unresponsive with a respiratory rate of 6 after receiving morphine. Which medication should the nurse prepare to administer?', 'Naloxone is the opioid antagonist used to reverse respiratory depression.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Acetylcysteine"},{"id":"C","text":"Vitamin K"},{"id":"D","text":"Digoxin immune Fab"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone reverses opioid respiratory depression.","B":"Incorrect. That is for acetaminophen overdose.","C":"Incorrect. That reverses warfarin.","D":"Incorrect. That treats digoxin toxicity."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Overdose reversal', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315005', 'MCQ', 'A nurse is monitoring a client receiving furosemide. Which laboratory value is most important to monitor for a common adverse effect?', 'Loop diuretics such as furosemide cause potassium loss, so potassium must be monitored.', '{"options":[{"id":"A","text":"Potassium"},{"id":"B","text":"Calcium"},{"id":"C","text":"Bilirubin"},{"id":"D","text":"Amylase"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Furosemide can cause hypokalemia.","B":"Incorrect. Not the primary concern with furosemide.","C":"Incorrect. Not relevant to furosemide therapy.","D":"Incorrect. Not associated with furosemide."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Diuretics', 'Furosemide monitoring', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315006', 'MCQ', 'Before administering the first dose of penicillin, which question is most important for the nurse to ask the client?', 'Assessing for a penicillin allergy before the first dose prevents a potentially fatal reaction.', '{"options":[{"id":"A","text":"Have you ever had an allergic reaction to penicillin?"},{"id":"B","text":"When did you last eat?"},{"id":"C","text":"Do you take a daily multivitamin?"},{"id":"D","text":"How much water do you usually drink?"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Allergy assessment prevents anaphylaxis.","B":"Incorrect. Food timing is not the priority here.","C":"Incorrect. Not the priority safety question.","D":"Incorrect. Not relevant to first-dose safety."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Allergy assessment', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315007', 'MCQ', 'A nurse notes the IV site is cool, swollen, and pale with a slowed infusion. Which action should the nurse take first?', 'A cool, swollen, pale site indicates infiltration; the infusion is stopped and the IV removed.', '{"options":[{"id":"A","text":"Stop the infusion and discontinue the IV"},{"id":"B","text":"Increase the infusion rate"},{"id":"C","text":"Apply a warm compress and continue"},{"id":"D","text":"Flush the line with saline"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are signs of infiltration; stop the infusion.","B":"Incorrect. This worsens tissue injury.","C":"Incorrect. Continuing the infusion is unsafe.","D":"Incorrect. Flushing pushes more fluid into tissue."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV site care', 'Infiltration', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315008', 'MCQ', 'During a blood transfusion, a client develops fever, chills, and low back pain. What should the nurse do first?', 'Signs of a transfusion reaction require immediately stopping the transfusion.', '{"options":[{"id":"A","text":"Stop the transfusion"},{"id":"B","text":"Slow the transfusion rate"},{"id":"C","text":"Administer the next unit"},{"id":"D","text":"Document and continue monitoring"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping the transfusion is the priority.","B":"Incorrect. The transfusion must be stopped, not slowed.","C":"Incorrect. Never continue during a reaction.","D":"Incorrect. Action is needed before documenting."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood-product administration', 'Transfusion reaction', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315009', 'MCQ', 'Which site is preferred for an intramuscular injection in an adult because it is away from major nerves and blood vessels?', 'The ventrogluteal site is preferred for IM injections because it avoids major nerves and vessels.', '{"options":[{"id":"A","text":"Ventrogluteal"},{"id":"B","text":"Abdomen"},{"id":"C","text":"Inner forearm"},{"id":"D","text":"Upper back"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The ventrogluteal site is safest for adults.","B":"Incorrect. The abdomen is a subcutaneous site.","C":"Incorrect. That is an intradermal site.","D":"Incorrect. Not a standard IM site."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'Medication routes', 'IM injection site', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315010', 'MCQ', 'A nurse discards half of a prefilled opioid syringe. What action is required for correct controlled-substance handling?', 'Wasting a controlled substance requires a second nurse to witness and co-sign.', '{"options":[{"id":"A","text":"Waste the unused portion with a second nurse witnessing"},{"id":"B","text":"Discard the unused portion alone and document later"},{"id":"C","text":"Return the unused portion to the medication drawer"},{"id":"D","text":"Give the remaining half to another client in pain"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A witness is required for controlled-substance waste.","B":"Incorrect. A witness is required.","C":"Incorrect. Opioids are not returned for reuse.","D":"Incorrect. Medications are client-specific."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Controlled substances', 'Wasting', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_315011', 'MCQ', 'A nurse teaches a client about taking oral tetracycline. Which instruction is correct?', 'Tetracycline absorption is reduced by dairy products and antacids, which should be avoided.', '{"options":[{"id":"A","text":"Avoid taking it with milk or antacids"},{"id":"B","text":"Take it with a large glass of milk"},{"id":"C","text":"Take an antacid together for stomach upset"},{"id":"D","text":"Double the dose if a dose is missed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Dairy and antacids reduce absorption.","B":"Incorrect. Calcium binds the drug.","C":"Incorrect. Antacids impair absorption.","D":"Incorrect. Doses are never doubled."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Medication education', 'Antacid timing', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_315012', 'SATA', 'A nurse reviews the rights of medication administration. Which are recognized rights? Select all that apply.', 'The core rights include right client, drug, dose, route, and time; pharmacy and insurance are not rights.', '{"options":[{"id":"A","text":"Right client"},{"id":"B","text":"Right dose"},{"id":"C","text":"Right route"},{"id":"D","text":"Right time"},{"id":"E","text":"Right pharmacy chain"},{"id":"F","text":"Right insurance plan"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Rights of administration', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_315013', 'SATA', 'A client is starting opioid therapy for pain. Which adverse effects should the nurse teach the client to expect or report? Select all that apply.', 'Opioids commonly cause constipation, sedation, and, at high doses, respiratory depression.', '{"options":[{"id":"A","text":"Constipation"},{"id":"B","text":"Drowsiness"},{"id":"C","text":"Respiratory depression"},{"id":"D","text":"Diarrhea"},{"id":"E","text":"Increased urination"},{"id":"F","text":"Improved appetite"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_315014', 'SATA', 'A nurse cares for a client receiving total parenteral nutrition (TPN). Which nursing actions are appropriate? Select all that apply.', 'TPN requires glucose monitoring, sterile handling, and gradual weaning; rapid changes and bedside additives are unsafe.', '{"options":[{"id":"A","text":"Monitor blood glucose regularly"},{"id":"B","text":"Use sterile technique for tubing changes"},{"id":"C","text":"Do not abruptly stop the infusion"},{"id":"D","text":"Infuse rapidly to catch up if behind"},{"id":"E","text":"Add medications directly to the TPN bag at bedside"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'TPN', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_315015', 'SATA', 'A nurse teaches a client starting an antihypertensive. Which points should the teaching include? Select all that apply.', 'Antihypertensive teaching stresses slow position changes, continuity of therapy, and reporting ACE-inhibitor cough.', '{"options":[{"id":"A","text":"Change positions slowly to prevent dizziness"},{"id":"B","text":"Do not stop the medication abruptly"},{"id":"C","text":"Report a persistent dry cough with ACE inhibitors"},{"id":"D","text":"Stop the drug once blood pressure is normal"},{"id":"E","text":"Double the dose if a reading is high"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_315016', 'SATA', 'Which medications are considered high-alert drugs requiring extra safety checks? Select all that apply.', 'Insulin, heparin, and concentrated electrolytes are high-alert drugs; acetaminophen and stool softeners are not.', '{"options":[{"id":"A","text":"Insulin"},{"id":"B","text":"Heparin"},{"id":"C","text":"Concentrated potassium chloride"},{"id":"D","text":"Acetaminophen"},{"id":"E","text":"Docusate sodium"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_315017', 'SELECT_N', 'A nurse must administer IV potassium chloride safely. Which 2 practices are required?', 'IV potassium must be diluted and pump-controlled, and adequate urine output confirmed; it is never given IV push.', '{"options":[{"id":"A","text":"Always dilute and infuse using an infusion pump"},{"id":"B","text":"Verify urine output is adequate before infusing"},{"id":"C","text":"Give as a rapid IV push"},{"id":"D","text":"Administer undiluted for faster effect"},{"id":"E","text":"Infuse without monitoring the ECG"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Electrolytes', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_315018', 'TF', 'Protamine sulfate is the antidote used to reverse the effects of heparin.', 'Protamine sulfate neutralizes heparin and is its recognized antidote.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_315019', 'MATRIX', 'For each medication, click to indicate whether it is typically administered by the oral or subcutaneous route.', 'Metformin and lisinopril are oral; enoxaparin and routine insulin are given subcutaneously.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Metformin tablet"},{"id":"r2","text":"Enoxaparin"},{"id":"r3","text":"Lisinopril tablet"},{"id":"r4","text":"Regular insulin (for routine dosing)"}],"columns":[{"id":"c1","text":"Oral"},{"id":"c2","text":"Subcutaneous"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication reconciliation', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_315020', 'MATRIX_MR', 'For each medication, select all parameters the nurse should monitor to evaluate response and safety.', 'Insulin monitoring targets glucose; beta-blockers affect BP and heart rate; ACE inhibitors target BP.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Insulin"},{"id":"r2","text":"Metoprolol"},{"id":"r3","text":"Lisinopril"}],"columns":[{"id":"c1","text":"Blood pressure"},{"id":"c2","text":"Blood glucose"},{"id":"c3","text":"Heart rate"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c3"],"r3":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Response evaluation', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_315021', 'CLOZE', 'Before administering digoxin, the nurse should assess the client''s {1}. The nurse should hold the dose if the value is below {2} beats per minute.', 'Digoxin is held for an apical pulse below 60 beats per minute due to bradycardia risk.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"apical pulse"},{"id":"c2","text":"temperature"},{"id":"c3","text":"respiratory rate"}]},{"id":"b2","choices":[{"id":"c1","text":"60"},{"id":"c2","text":"100"},{"id":"c3","text":"40"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_315022', 'HIGHLIGHT', 'A nurse monitors a client 10 minutes into a transfusion. Vital signs and findings: [[temperature 39.2°C]], blood pressure 110/70, [[reports itching with hives]], [[new low back pain]], respiratory rate 16, and [[oxygen saturation 98%]].', 'Fever, hives, and back pain are signs of a transfusion reaction; a normal SpO2 is not concerning.', '{"chunks":[{"id":"h1","text":"temperature 39.2°C"},{"id":"h2","text":"reports itching with hives"},{"id":"h3","text":"new low back pain"},{"id":"h4","text":"oxygen saturation 98%"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"Fever suggests a transfusion reaction.","h2":"Hives suggest an allergic reaction.","h3":"Back pain suggests a hemolytic reaction.","h4":"A normal finding, no follow-up needed."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Blood-product administration', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_315023', 'BOWTIE', 'A client on insulin becomes shaky, diaphoretic, and confused with a glucose of 52 mg/dL. Complete the diagram.', 'Hypoglycemia is treated with fast carbohydrate and rechecked glucose, monitoring glucose and consciousness.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Give 15 g of a fast-acting carbohydrate"},{"id":"lt2","text":"Recheck blood glucose in 15 minutes"},{"id":"lt3","text":"Administer the next insulin dose"},{"id":"lt4","text":"Withhold all oral intake"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Hypoglycemia"},{"id":"ct2","text":"Diabetic ketoacidosis"},{"id":"ct3","text":"Hyperosmolar state"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood glucose level"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Urine specific gravity"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_315024', 'DRAG_CLOZE', 'A provider orders 500 mg of a medication available as 250 mg per tablet. The nurse should administer [1] tablet(s). The order is given [2].', '500 mg divided by 250 mg per tablet equals 2 tablets, given as a twice-daily schedule.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"2"},{"id":"t2","text":"twice daily"},{"id":"t3","text":"4"},{"id":"t4","text":"once weekly"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Dosage calculation', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316001', 'MCQ', 'A client is prescribed warfarin. Which laboratory test does the nurse use to monitor its therapeutic effect?', 'Warfarin therapy is guided by the INR, derived from the prothrombin time.', '{"options":[{"id":"A","text":"INR"},{"id":"B","text":"aPTT"},{"id":"C","text":"Platelet count"},{"id":"D","text":"Fibrinogen"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Warfarin is monitored with the INR/PT.","B":"Incorrect. aPTT monitors heparin.","C":"Incorrect. Not the primary monitoring test for warfarin.","D":"Incorrect. Not used to titrate warfarin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316002', 'MCQ', 'A client receiving a heparin infusion develops bleeding. Which medication does the nurse anticipate as the antidote?', 'Protamine sulfate is the specific antidote for heparin.', '{"options":[{"id":"A","text":"Protamine sulfate"},{"id":"B","text":"Vitamin K"},{"id":"C","text":"Naloxone"},{"id":"D","text":"Flumazenil"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Protamine sulfate reverses heparin.","B":"Incorrect. Vitamin K reverses warfarin.","C":"Incorrect. Naloxone reverses opioids.","D":"Incorrect. Flumazenil reverses benzodiazepines."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin antidote', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316003', 'MCQ', 'A nurse administers regular insulin subcutaneously at 0800. When should the nurse be most alert for hypoglycemia given its peak action of 2 to 4 hours?', 'Regular insulin peaks in 2-4 hours, so hypoglycemia is most likely 1000-1200 after an 0800 dose.', '{"options":[{"id":"A","text":"Between 1000 and 1200"},{"id":"B","text":"At 0815"},{"id":"C","text":"At 1800"},{"id":"D","text":"At 2200"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Regular insulin peaks 2-4 hours after administration.","B":"Incorrect. This is before the onset.","C":"Incorrect. This is past the peak window.","D":"Incorrect. This is well beyond the peak."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Onset', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316004', 'MCQ', 'The nurse prepares to give an intramuscular injection to an adult. Which site is preferred for its distance from major nerves and blood vessels?', 'The ventrogluteal site is free of major nerves and vessels, making it the preferred IM site.', '{"options":[{"id":"A","text":"Ventrogluteal"},{"id":"B","text":"Dorsogluteal"},{"id":"C","text":"Abdomen"},{"id":"D","text":"Antecubital"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The ventrogluteal site is safest for IM injections.","B":"Incorrect. It is near the sciatic nerve and no longer recommended.","C":"Incorrect. The abdomen is a subcutaneous site.","D":"Incorrect. This is used for venipuncture."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'Injection technique', 'IM sites', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316005', 'MCQ', 'A client is starting furosemide. Which food should the nurse encourage to help prevent an electrolyte imbalance?', 'Loop diuretics cause potassium loss; potassium-rich foods such as bananas help offset hypokalemia.', '{"options":[{"id":"A","text":"Bananas"},{"id":"B","text":"White rice"},{"id":"C","text":"Egg whites"},{"id":"D","text":"Butter"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Furosemide wastes potassium; bananas replace it.","B":"Incorrect. Low in potassium.","C":"Incorrect. Not a notable potassium source.","D":"Incorrect. Not a potassium source."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Loop diuretic teaching', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316006', 'MCQ', 'A client has a respiratory rate of 6 breaths per minute after receiving morphine. Which medication does the nurse prepare to administer?', 'Naloxone is the opioid antagonist used for morphine-induced respiratory depression.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Acetylcysteine"},{"id":"C","text":"Atropine"},{"id":"D","text":"Digoxin immune Fab"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone reverses opioid-induced respiratory depression.","B":"Incorrect. That is for acetaminophen overdose.","C":"Incorrect. Atropine is for bradycardia.","D":"Incorrect. That reverses digoxin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Overdose reversal', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316007', 'MCQ', 'Before administering a medication, the nurse checks the client''s name and date of birth on the wristband against the record. Which right of medication administration is being verified?', 'Using two identifiers confirms the right client before administration.', '{"options":[{"id":"A","text":"Right client"},{"id":"B","text":"Right dose"},{"id":"C","text":"Right route"},{"id":"D","text":"Right time"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers verify the right client.","B":"Incorrect. That involves the amount.","C":"Incorrect. That involves how it is given.","D":"Incorrect. That involves scheduling."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Fundamentals of Nursing', 'Multisystem', 'Rights of administration', 'Verification', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316008', 'MCQ', 'A nurse notes cool, pale, swollen tissue around a peripheral IV site with a slowed infusion. Which action should the nurse take first?', 'Signs of infiltration require stopping the infusion and removing the IV catheter.', '{"options":[{"id":"A","text":"Stop the infusion and remove the catheter"},{"id":"B","text":"Increase the infusion rate"},{"id":"C","text":"Apply heat and continue"},{"id":"D","text":"Flush the catheter with saline"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Infiltration requires stopping and discontinuing the line.","B":"Incorrect. This worsens tissue damage.","C":"Incorrect. The line must be discontinued first.","D":"Incorrect. Flushing pushes more fluid into tissue."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV therapy', 'Infiltration', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316009', 'MCQ', 'Minutes after starting an IV antibiotic, a client reports throat tightness and difficulty breathing. Which action should the nurse take first?', 'In a suspected allergic reaction, stopping the offending medication is the first priority.', '{"options":[{"id":"A","text":"Stop the antibiotic infusion"},{"id":"B","text":"Document the finding"},{"id":"C","text":"Slow the infusion rate"},{"id":"D","text":"Offer the client water"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping the drug halts further exposure in a suspected anaphylactic reaction.","B":"Incorrect. Documentation is not the priority.","C":"Incorrect. The drug must be stopped, not slowed.","D":"Incorrect. This risks aspiration during airway compromise."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Anaphylaxis', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_316010', 'MCQ', 'A client is receiving total parenteral nutrition (TPN). Which laboratory value should the nurse monitor most closely?', 'TPN contains concentrated dextrose, so blood glucose must be monitored closely.', '{"options":[{"id":"A","text":"Blood glucose"},{"id":"B","text":"Serum amylase"},{"id":"C","text":"Bilirubin"},{"id":"D","text":"Uric acid"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TPN''s high dextrose content requires close glucose monitoring.","B":"Incorrect. Not the priority for TPN.","C":"Incorrect. Not the primary TPN concern.","D":"Incorrect. Not routinely monitored for TPN."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'TPN', 'Monitoring', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_316011', 'SATA', 'The nurse reviews the rights of safe medication administration. Which are included among the classic rights? Select all that apply.', 'The classic rights include client, drug, dose, route, and time; insurance and pharmacy are not among them.', '{"options":[{"id":"A","text":"Right client"},{"id":"B","text":"Right dose"},{"id":"C","text":"Right route"},{"id":"D","text":"Right time"},{"id":"E","text":"Right insurance"},{"id":"F","text":"Right pharmacy"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Fundamentals of Nursing', 'Multisystem', 'Rights of administration', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_316012', 'SATA', 'A nurse teaches a client about self-administration of subcutaneous insulin. Which instructions are appropriate? Select all that apply.', 'Site rotation, correct storage, gentle mixing of NPH, and a 90-degree angle are correct; massaging and needle reuse are unsafe.', '{"options":[{"id":"A","text":"Rotate injection sites"},{"id":"B","text":"Store the vial in use safely and follow the label''s storage guidance"},{"id":"C","text":"Roll cloudy NPH insulin gently between the palms before drawing up"},{"id":"D","text":"Inject at a 90-degree angle in most adults"},{"id":"E","text":"Massage the site vigorously after injection"},{"id":"F","text":"Reuse the same needle for a week to save supplies"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_316013', 'SATA', 'A client is receiving an opioid for pain. Which are expected side effects the nurse should monitor for? Select all that apply.', 'Opioids commonly cause constipation, sedation, and respiratory depression.', '{"options":[{"id":"A","text":"Constipation"},{"id":"B","text":"Sedation"},{"id":"C","text":"Respiratory depression"},{"id":"D","text":"Diarrhea"},{"id":"E","text":"Hypertension"},{"id":"F","text":"Tachypnea"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Side effects', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_316014', 'SATA', 'Which nursing actions are appropriate when handling controlled substances? Select all that apply.', 'Controlled substances require shift counts, witnessed waste, and secure locked storage.', '{"options":[{"id":"A","text":"Count the controlled substances at each shift change with another nurse"},{"id":"B","text":"Have a second nurse witness and document any wasted portion"},{"id":"C","text":"Store the medications in a locked cabinet"},{"id":"D","text":"Leave the narcotic drawer unlocked for quick access during a busy shift"},{"id":"E","text":"Discard unused portions in the regular trash"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Controlled substances', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_316015', 'SATA', 'A client receiving a blood transfusion develops fever, chills, and low back pain. Which actions should the nurse take? Select all that apply.', 'A suspected transfusion reaction requires stopping the blood, maintaining IV access with saline, and notifying the provider; the bag is retained for evaluation.', '{"options":[{"id":"A","text":"Stop the transfusion"},{"id":"B","text":"Keep the IV line open with normal saline"},{"id":"C","text":"Notify the provider"},{"id":"D","text":"Continue the transfusion at a slower rate"},{"id":"E","text":"Discard the blood bag immediately without saving it"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Blood transfusion', 'Reaction', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_316016', 'SELECT_N', 'Which 2 medications are considered high-alert medications requiring an independent double-check?', 'Insulin and IV heparin are classic high-alert medications carrying heightened risk of harm.', '{"options":[{"id":"A","text":"Insulin"},{"id":"B","text":"IV heparin"},{"id":"C","text":"Acetaminophen"},{"id":"D","text":"Docusate sodium"},{"id":"E","text":"Bisacodyl"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-alert medications', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_316017', 'TF', 'Vitamin K is the antidote used to reverse the effects of warfarin.', 'Vitamin K reverses warfarin by restoring clotting factor synthesis.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin antidote', 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_316018', 'MATRIX', 'For each medication, click to indicate its correct antidote or reversal agent.', 'Naloxone reverses opioids, vitamin K reverses warfarin, and protamine reverses heparin.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Morphine"},{"id":"r2","text":"Warfarin"},{"id":"r3","text":"Heparin"},{"id":"r4","text":"Hydromorphone"}],"columns":[{"id":"c1","text":"Naloxone"},{"id":"c2","text":"Vitamin K"},{"id":"c3","text":"Protamine sulfate"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Antidotes', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_316019', 'MATRIX_MR', 'For each insulin, select all descriptions that apply.', 'Lispro is rapid-acting, glargine is long-acting, and regular insulin is the only one given IV.', '{"row_label":"Insulin","rows":[{"id":"r1","text":"Lispro"},{"id":"r2","text":"Glargine"},{"id":"r3","text":"Regular insulin"}],"columns":[{"id":"c1","text":"Rapid-acting"},{"id":"c2","text":"Long-acting"},{"id":"c3","text":"Can be given IV"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Classification', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_316020', 'CLOZE', 'A client is receiving an IV heparin infusion. The nurse monitors the {1} to evaluate its therapeutic effect and keeps {2} available in case of bleeding.', 'Heparin is monitored with the aPTT and reversed with protamine sulfate.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"aPTT"},{"id":"c2","text":"INR"},{"id":"c3","text":"blood glucose"}]},{"id":"b2","choices":[{"id":"c1","text":"protamine sulfate"},{"id":"c2","text":"vitamin K"},{"id":"c3","text":"naloxone"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Monitoring', 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_316021', 'HIGHLIGHT', 'A nurse reviews a client taking digoxin. Highlight the findings that suggest possible digoxin toxicity. The client reports [[nausea]] and states [[I see yellow-green halos around lights]]. Heart rate is [[48 bpm]]. Blood pressure is [[122/78]]. Temperature is [[37.0°C]].', 'Nausea, yellow-green visual halos, and bradycardia are classic signs of digoxin toxicity.', '{"chunks":[{"id":"h1","text":"nausea"},{"id":"h2","text":"I see yellow-green halos around lights"},{"id":"h3","text":"48 bpm"},{"id":"h4","text":"122/78"},{"id":"h5","text":"37.0°C"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"Nausea is an early sign of digoxin toxicity.","h2":"Visual halos are a classic toxicity cue.","h3":"Bradycardia is a sign of digoxin toxicity.","h4":"This blood pressure is normal.","h5":"This temperature is normal."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', 'Toxicity cues', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_316022', 'BOWTIE', 'A client who received insulin becomes diaphoretic, shaky, and reports a blood glucose of 55 mg/dL. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Insulin-induced hypoglycemia is treated with fast-acting carbohydrate and a recheck, monitoring glucose and mental status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Give 15 g of fast-acting carbohydrate"},{"id":"lt2","text":"Recheck blood glucose in 15 minutes"},{"id":"lt3","text":"Administer additional insulin"},{"id":"lt4","text":"Withhold all oral intake"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Hypoglycemia"},{"id":"ct2","text":"Diabetic ketoacidosis"},{"id":"ct3","text":"Hyperosmolar state"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood glucose"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Urine ketones"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Hypoglycemia', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_316023', 'DRAG_CLOZE', 'A client''s respiratory rate falls to 6 after morphine. The nurse recognizes [1] as the priority concern and prepares to administer [2].', 'Opioid-induced respiratory depression is reversed with naloxone.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"respiratory depression"},{"id":"t2","text":"naloxone"},{"id":"t3","text":"constipation"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Reversal', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_316024', 'DRAG_ORDER', 'Place the steps for safe oral medication administration in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene"},{"id":"t2","text":"Verify the medication against the order"},{"id":"t3","text":"Identify the client using two identifiers"},{"id":"t4","text":"Administer the medication"},{"id":"t5","text":"Document the administration"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Fundamentals of Nursing', 'Multisystem', 'Medication administration', 'Oral med steps', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320001', 'MCQ', 'A nurse is caring for a client with a chest tube connected to a water-seal drainage system. The nurse notes gentle bubbling in the water-seal chamber that fluctuates with respiration. Which action should the nurse take?', 'Fluctuation in the water-seal chamber with respiration (tidaling) is a normal, expected finding.', '{"options":[{"id":"A","text":"Continue to monitor, as this is an expected finding"},{"id":"B","text":"Clamp the chest tube immediately"},{"id":"C","text":"Notify the provider of a system malfunction"},{"id":"D","text":"Milk the tubing toward the drainage collection chamber"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Tidaling (fluctuation with respiration) reflects normal function.","B":"Incorrect. Clamping can cause a tension pneumothorax.","C":"Incorrect. This is a normal finding, not a malfunction.","D":"Incorrect. Milking is not routinely done and can damage tissue."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320002', 'MCQ', 'A nurse is teaching a client about caring for a new colostomy. Which stoma appearance should the nurse teach the client to report to the provider?', 'A dark purple or black stoma indicates ischemia and must be reported immediately.', '{"options":[{"id":"A","text":"A pink, moist stoma"},{"id":"B","text":"A dark purple or black stoma"},{"id":"C","text":"A stoma that protrudes slightly above the skin"},{"id":"D","text":"Minor bleeding when cleansing the stoma"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Pink and moist is a healthy stoma.","B":"Correct. A dusky, purple, or black stoma suggests impaired blood flow.","C":"Incorrect. A slightly protruding stoma is normal.","D":"Incorrect. Slight bleeding with cleansing is common."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320003', 'MCQ', 'A nurse is assessing an arteriovenous (AV) fistula in a client''s left arm before hemodialysis. Which finding indicates the fistula is patent and functioning?', 'A palpable thrill and audible bruit confirm a patent, functioning AV fistula.', '{"options":[{"id":"A","text":"A palpable thrill and audible bruit over the site"},{"id":"B","text":"A blood pressure cuff reading obtained from that arm"},{"id":"C","text":"Absence of a pulse distal to the fistula"},{"id":"D","text":"Cool, pale skin over the fistula"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A thrill and bruit confirm blood flow through the fistula.","B":"Incorrect. BP should never be taken in the fistula arm.","C":"Incorrect. This suggests compromised circulation.","D":"Incorrect. This suggests poor perfusion."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320004', 'MCQ', 'A nurse is preparing to perform endotracheal suctioning on a client. Which intervention should the nurse implement to reduce the risk of hypoxemia?', 'Hyperoxygenation before suctioning helps prevent suction-induced hypoxemia.', '{"options":[{"id":"A","text":"Hyperoxygenate the client before suctioning"},{"id":"B","text":"Apply suction while inserting the catheter"},{"id":"C","text":"Suction continuously for 30 seconds"},{"id":"D","text":"Instill 10 mL of saline before each pass"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pre-oxygenation prevents suction-induced hypoxemia.","B":"Incorrect. Suction is applied only during withdrawal.","C":"Incorrect. Suctioning should not exceed 10-15 seconds.","D":"Incorrect. Routine saline instillation is not recommended."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320005', 'MCQ', 'A client''s serum sodium level is 128 mEq/L. The nurse recognizes this laboratory value as indicating which condition?', 'A serum sodium of 128 mEq/L is below the normal range of 135-145 mEq/L, indicating hyponatremia.', '{"options":[{"id":"A","text":"Hyponatremia"},{"id":"B","text":"Hypernatremia"},{"id":"C","text":"Hyperkalemia"},{"id":"D","text":"Normal sodium level"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Normal sodium is 135-145 mEq/L; 128 is low.","B":"Incorrect. Hypernatremia is a high sodium level.","C":"Incorrect. This value describes sodium, not potassium.","D":"Incorrect. 128 mEq/L is below the normal range."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Fluid and electrolyte imbalance', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320006', 'MCQ', 'A nurse is caring for a newborn receiving phototherapy for hyperbilirubinemia. Which nursing action is appropriate?', 'Eye shields protect the newborn''s retina from potential damage during phototherapy.', '{"options":[{"id":"A","text":"Cover the newborn''s eyes with protective shields"},{"id":"B","text":"Dress the newborn in a long-sleeved gown"},{"id":"C","text":"Apply lotion to the skin before treatment"},{"id":"D","text":"Keep the newborn at least 3 feet from the light"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Eye shields protect the retina from the light.","B":"Incorrect. Skin exposure maximizes light effectiveness.","C":"Incorrect. Lotions can cause burns under phototherapy.","D":"Incorrect. The light is positioned per protocol, not 3 feet away."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320007', 'MCQ', 'A nurse is reviewing findings for a client with suspected sepsis. Which set of vital signs is most consistent with early sepsis?', 'Fever, tachycardia, and tachypnea are hallmark systemic responses in early sepsis.', '{"options":[{"id":"A","text":"Temperature 38.9°C, heart rate 112 bpm, respirations 24/min"},{"id":"B","text":"Temperature 36.5°C, heart rate 68 bpm, respirations 14/min"},{"id":"C","text":"Temperature 37.0°C, heart rate 60 bpm, respirations 12/min"},{"id":"D","text":"Temperature 36.8°C, blood pressure 130/80 mmHg, respirations 16/min"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Fever, tachycardia, and tachypnea are classic early sepsis signs.","B":"Incorrect. These are normal vital signs.","C":"Incorrect. These reflect a stable client.","D":"Incorrect. These are within normal limits."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320008', 'MCQ', 'A nurse is changing a dressing on a client''s surgical wound. Which principle should the nurse follow to prevent infection?', 'Sterile technique during a surgical dressing change prevents introduction of pathogens.', '{"options":[{"id":"A","text":"Use sterile technique when handling the wound"},{"id":"B","text":"Clean the wound from the outer edges toward the center"},{"id":"C","text":"Reuse the same gauze to cover the entire wound"},{"id":"D","text":"Leave the old dressing off for one hour before reapplying"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sterile technique prevents wound contamination.","B":"Incorrect. Clean from center outward, least to most contaminated.","C":"Incorrect. This spreads contamination.","D":"Incorrect. This exposes the wound to contamination."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320009', 'MCQ', 'A nurse observes a client''s cardiac monitor showing a regular rhythm with a rate of 40 bpm, a P wave before each QRS, and a normal PR interval. The nurse identifies this rhythm as which of the following?', 'A regular rhythm under 60 bpm with normal P waves and PR interval is sinus bradycardia.', '{"options":[{"id":"A","text":"Sinus bradycardia"},{"id":"B","text":"Sinus tachycardia"},{"id":"C","text":"Atrial fibrillation"},{"id":"D","text":"Ventricular fibrillation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A rate under 60 with normal conduction is sinus bradycardia.","B":"Incorrect. Tachycardia has a rate over 100.","C":"Incorrect. A-fib is irregular with no clear P waves.","D":"Incorrect. V-fib is a chaotic, lethal rhythm with no organized complexes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Telemetry', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320010', 'MCQ', 'A nurse is monitoring a client with a head injury for increased intracranial pressure (ICP). Which early sign should the nurse recognize?', 'A declining level of consciousness is the earliest and most sensitive indicator of increased ICP.', '{"options":[{"id":"A","text":"Decreasing level of consciousness"},{"id":"B","text":"Fixed, dilated pupils"},{"id":"C","text":"Cushing''s triad"},{"id":"D","text":"Absent gag reflex"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A change in level of consciousness is the earliest sign of rising ICP.","B":"Incorrect. This is a late sign.","C":"Incorrect. Cushing''s triad is a late, ominous sign.","D":"Incorrect. This occurs with severe, late deterioration."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320011', 'MCQ', 'A nurse is caring for a client with a temperature of 40.0°C. Which intervention should the nurse implement to help lower the client''s temperature?', 'A cooling blanket promotes heat dissipation and helps reduce a high fever.', '{"options":[{"id":"A","text":"Apply a cooling blanket as prescribed"},{"id":"B","text":"Cover the client with several warm blankets"},{"id":"C","text":"Encourage the client to wear thick clothing"},{"id":"D","text":"Restrict all oral fluids"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A cooling blanket promotes heat loss for high fever.","B":"Incorrect. This traps heat and worsens the fever.","C":"Incorrect. This retains body heat.","D":"Incorrect. Fluids are needed to replace losses in fever."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Temperature regulation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320012', 'MCQ', 'A high-pressure alarm sounds on the ventilator of a client who is intubated and coughing forcefully. Which is the most likely cause?', 'A high-pressure alarm indicates increased airway resistance, commonly from secretions, coughing, or kinking.', '{"options":[{"id":"A","text":"Secretions obstructing the airway"},{"id":"B","text":"A disconnection in the ventilator circuit"},{"id":"C","text":"A cuff leak in the endotracheal tube"},{"id":"D","text":"The client being extubated"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Secretions or coughing increase airway resistance and pressure.","B":"Incorrect. A disconnection triggers a low-pressure alarm.","C":"Incorrect. A leak causes a low-pressure alarm.","D":"Incorrect. Extubation causes a low-pressure/apnea alarm."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_320013', 'MCQ', 'A nurse is caring for a client on the first day after abdominal surgery who has a nasogastric tube set to low intermittent suction. The nurse notes the tube has stopped draining. Which action should the nurse take first?', 'Checking the tube for kinks or obstruction is the first and least invasive step when an NG tube stops draining.', '{"options":[{"id":"A","text":"Check the tube for kinks or obstruction"},{"id":"B","text":"Remove the nasogastric tube"},{"id":"C","text":"Increase the suction to high continuous"},{"id":"D","text":"Advance the tube 5 cm further"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Assessing for a mechanical cause is the first, least invasive step.","B":"Incorrect. Removal requires an order and is not the first action.","C":"Incorrect. This can damage gastric mucosa.","D":"Incorrect. Repositioning is not done without assessment or order."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_320014', 'SATA', 'A nurse is assessing a client for signs of hypovolemic shock. Which findings should the nurse expect? Select all that apply.', 'Hypovolemic shock produces tachycardia, hypotension, cool clammy skin, and oliguria as the body compensates for low volume.', '{"options":[{"id":"A","text":"Tachycardia"},{"id":"B","text":"Hypotension"},{"id":"C","text":"Cool, clammy skin"},{"id":"D","text":"Decreased urine output"},{"id":"E","text":"Bounding peripheral pulses"},{"id":"F","text":"Flushed, warm skin"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Hypovolemic shock', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_320015', 'SATA', 'A nurse is caring for a client with a serum potassium of 6.5 mEq/L. Which findings should the nurse monitor for? Select all that apply.', 'Hyperkalemia causes cardiac dysrhythmias, peaked T waves, and muscle weakness due to altered membrane excitability.', '{"options":[{"id":"A","text":"Cardiac dysrhythmias"},{"id":"B","text":"Muscle weakness"},{"id":"C","text":"Peaked T waves on the ECG"},{"id":"D","text":"Constipation"},{"id":"E","text":"Increased urine output"},{"id":"F","text":"Hypertension"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Hyperkalemia', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_320016', 'SATA', 'A nurse is caring for a client with a chest tube. Which findings should the nurse report to the provider immediately? Select all that apply.', 'Continuous vigorous bubbling suggests an air leak, sudden dyspnea suggests displacement, and heavy bright-red drainage suggests hemorrhage.', '{"options":[{"id":"A","text":"Continuous vigorous bubbling in the water-seal chamber"},{"id":"B","text":"Sudden onset of severe shortness of breath"},{"id":"C","text":"Drainage of more than 100 mL of bright red blood per hour"},{"id":"D","text":"Gentle tidaling in the water-seal chamber"},{"id":"E","text":"An intact occlusive dressing at the insertion site"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube care', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_320017', 'SATA', 'A nurse is assessing an older adult client for fluid volume deficit. Which findings support this diagnosis? Select all that apply.', 'Fluid volume deficit causes dry mucous membranes, poor skin turgor, and concentrated urine; the other options indicate fluid overload.', '{"options":[{"id":"A","text":"Dry mucous membranes"},{"id":"B","text":"Poor skin turgor"},{"id":"C","text":"Concentrated, dark urine"},{"id":"D","text":"Bounding, full pulses"},{"id":"E","text":"Jugular vein distension"},{"id":"F","text":"Crackles in the lung bases"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Dehydration', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_320018', 'SATA', 'A nurse is monitoring a client for fluid volume overload. Which assessment findings should the nurse expect? Select all that apply.', 'Fluid overload produces edema, weight gain, and bounding pulses from excess circulating volume.', '{"options":[{"id":"A","text":"Peripheral edema"},{"id":"B","text":"Weight gain"},{"id":"C","text":"Bounding pulses"},{"id":"D","text":"Sunken eyes"},{"id":"E","text":"Decreased blood pressure"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Fluid overload', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_320019', 'SATA', 'A nurse is assessing a surgical wound for signs of infection. Which findings indicate a possible wound infection? Select all that apply.', 'Purulent drainage, spreading redness, and warmth are classic signs of wound infection.', '{"options":[{"id":"A","text":"Purulent drainage"},{"id":"B","text":"Increasing redness around the wound"},{"id":"C","text":"Warmth at the wound site"},{"id":"D","text":"Approximated wound edges"},{"id":"E","text":"Pink granulation tissue"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound healing', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_320020', 'SELECT_N', 'A nurse is caring for a client receiving peritoneal dialysis. Which 2 findings should the nurse report to the provider immediately?', 'Cloudy outflow and fever are signs of peritonitis, a serious complication requiring prompt reporting.', '{"options":[{"id":"A","text":"Cloudy dialysate outflow"},{"id":"B","text":"Fever of 38.6°C"},{"id":"C","text":"Clear, pale-yellow dialysate outflow"},{"id":"D","text":"Mild fullness during the dwell"},{"id":"E","text":"Warmed dialysate solution before instillation"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_320021', 'TF', 'Cyanosis of the lips and nail beds is a sign of inadequate tissue oxygenation.', 'Central cyanosis reflects reduced oxygen saturation of hemoglobin and indicates impaired oxygenation.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Impaired oxygenation', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_320022', 'MATRIX', 'For each finding, click to specify whether it is associated with hypocalcemia or hypercalcemia.', 'Low calcium increases neuromuscular excitability (tetany, Trousseau''s); high calcium depresses it (weak reflexes, constipation).', '{"row_label":"Finding","rows":[{"id":"r1","text":"Positive Trousseau''s sign"},{"id":"r2","text":"Muscle cramps and tetany"},{"id":"r3","text":"Decreased deep tendon reflexes"},{"id":"r4","text":"Constipation"}],"columns":[{"id":"c1","text":"Hypocalcemia"},{"id":"c2","text":"Hypercalcemia"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Fluid and electrolyte imbalance', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_320023', 'MATRIX_MR', 'For each acid-base disturbance, select all matching arterial blood gas findings.', 'Respiratory acidosis shows a low pH with retained CO2; respiratory alkalosis shows a high pH; metabolic acidosis shows a low pH.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Respiratory acidosis"},{"id":"r2","text":"Respiratory alkalosis"},{"id":"r3","text":"Metabolic acidosis"}],"columns":[{"id":"c1","text":"Low pH"},{"id":"c2","text":"High pH"},{"id":"c3","text":"High CO2"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c2"],"r3":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Acid-base balance', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_320024', 'CLOZE', 'A client is diaphoretic, shaky, and confused with a blood glucose of 52 mg/dL. The nurse recognizes this as {1} and, if the client can swallow, should first provide {2}.', 'A glucose of 52 mg/dL with adrenergic symptoms is hypoglycemia, treated with 15 g of fast-acting carbohydrate when the client can swallow.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hypoglycemia"},{"id":"c2","text":"hyperglycemia"},{"id":"c3","text":"diabetic ketoacidosis"}]},{"id":"b2","choices":[{"id":"c1","text":"15 g of fast-acting oral carbohydrate"},{"id":"c2","text":"a dose of long-acting insulin"},{"id":"c3","text":"a high-protein meal"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Hypoglycemia', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_320025', 'HIGHLIGHT', 'The nurse reviews a postoperative client''s assessment. Highlight the findings that require immediate follow-up. Temperature [[37.1°C]]. Blood pressure [[88/54]]. Heart rate [[126]]. SpO2 [[97% on room air]]. Reports [[increasing incisional pain unrelieved by medication]].', 'Hypotension, tachycardia, and worsening unrelieved pain are concerning postoperative cues requiring follow-up.', '{"chunks":[{"id":"h1","text":"37.1°C"},{"id":"h2","text":"88/54"},{"id":"h3","text":"126"},{"id":"h4","text":"97% on room air"},{"id":"h5","text":"increasing incisional pain unrelieved by medication"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Normal temperature.","h2":"Hypotension — needs follow-up.","h3":"Tachycardia — needs follow-up.","h4":"Normal oxygen saturation.","h5":"Unrelieved worsening pain may signal a complication."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Complication recognition', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_320026', 'BOWTIE', 'A client with pneumonia has an SpO2 of 88% and increased work of breathing. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Impaired gas exchange is managed with oxygen and upright positioning while monitoring oxygenation and respiratory rate.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer prescribed oxygen"},{"id":"lt2","text":"Raise the head of the bed"},{"id":"lt3","text":"Lay the client flat"},{"id":"lt4","text":"Restrict all fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Impaired gas exchange"},{"id":"ct2","text":"Fluid volume deficit"},{"id":"ct3","text":"Hyperglycemia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate"},{"id":"rt3","text":"Blood glucose"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Impaired oxygenation', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_320027', 'DRAG_CLOZE', 'A client who is hyperventilating from anxiety blows off excess carbon dioxide, which causes the pH to [1] and results in respiratory [2].', 'Hyperventilation lowers CO2, raising pH and producing respiratory alkalosis.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"rise"},{"id":"t2","text":"alkalosis"},{"id":"t3","text":"acidosis"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acid-base balance', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_320028', 'DRAG_ORDER', 'A client''s chest tube becomes accidentally disconnected from the drainage system. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Submerge the tube end in sterile water"},{"id":"t2","text":"Reconnect a new sterile drainage system"},{"id":"t3","text":"Notify the provider"},{"id":"t4","text":"Assess the client''s respiratory status"},{"id":"t5","text":"Document the event"}]}'::jsonb, '{"slots":{"s1":"t4","s2":"t1","s3":"t2","s4":"t3","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Emergency care procedures', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321001', 'MCQ', 'A nurse is caring for a client with a chest tube connected to a water-seal drainage system. Which finding is expected and does NOT require intervention?', 'Tidaling of the water-seal fluid with breathing is a normal, expected finding in a functioning chest drainage system.', '{"options":[{"id":"A","text":"Gentle tidaling of fluid in the water-seal chamber with respiration"},{"id":"B","text":"Continuous bubbling in the water-seal chamber"},{"id":"C","text":"The chest tube disconnected from the drainage tubing"},{"id":"D","text":"Sudden absence of drainage with new shortness of breath"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Tidaling reflects normal pressure changes and is expected.","B":"Incorrect. Continuous bubbling suggests an air leak.","C":"Incorrect. A disconnection is an emergency.","D":"Incorrect. This suggests obstruction and needs action."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321002', 'MCQ', 'A nurse is teaching a client about a new colostomy. Which characteristic of a healthy stoma should the nurse describe?', 'A viable, well-perfused stoma appears pink to red and moist; dusky or pale color signals compromised circulation.', '{"options":[{"id":"A","text":"Pink to red and moist"},{"id":"B","text":"Pale and dry"},{"id":"C","text":"Dusky blue or black"},{"id":"D","text":"Bright yellow"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A healthy stoma is pink-red and moist.","B":"Incorrect. Pale/dry suggests poor perfusion.","C":"Incorrect. Dark color indicates ischemia/necrosis.","D":"Incorrect. Not a normal stoma color."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321003', 'MCQ', 'A nurse is performing endotracheal suctioning. To reduce the risk of hypoxemia, the nurse should apply suction for no longer than which duration per pass?', 'Suction passes should be limited to 10-15 seconds to minimize hypoxemia and mucosal trauma.', '{"options":[{"id":"A","text":"10 to 15 seconds"},{"id":"B","text":"30 to 40 seconds"},{"id":"C","text":"60 seconds"},{"id":"D","text":"90 seconds"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Limit each suction pass to 10-15 seconds.","B":"Incorrect. Too long — causes hypoxemia.","C":"Incorrect. Far too long.","D":"Incorrect. Dangerous duration."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321004', 'MCQ', 'A nurse is caring for a client with an arteriovenous (AV) fistula in the left arm for hemodialysis. Which action should the nurse take?', 'Blood pressure measurement, venipuncture, and IVs are avoided in the fistula extremity to preserve access patency.', '{"options":[{"id":"A","text":"Avoid taking blood pressure in the left arm"},{"id":"B","text":"Draw all blood samples from the fistula arm"},{"id":"C","text":"Apply a tight compression dressing over the fistula"},{"id":"D","text":"Start a peripheral IV in the fistula arm"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Protect the fistula arm from BP cuffs and venipuncture.","B":"Incorrect. Venipuncture in the fistula arm is avoided.","C":"Incorrect. Pressure can occlude the fistula.","D":"Incorrect. IVs are avoided in the fistula arm."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321005', 'MCQ', 'A nurse assesses a client in the early compensatory stage of hypovolemic shock. Which finding does the nurse expect?', 'In compensatory hypovolemic shock the body increases heart rate to maintain cardiac output.', '{"options":[{"id":"A","text":"Increased heart rate"},{"id":"B","text":"Bradycardia"},{"id":"C","text":"Warm, flushed skin"},{"id":"D","text":"Bounding peripheral pulses"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Tachycardia is an early compensatory response.","B":"Incorrect. Not typical of early shock.","C":"Incorrect. Skin is cool and clammy in hypovolemic shock.","D":"Incorrect. Pulses are weak and thready."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Shock', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321006', 'MCQ', 'A nurse is caring for a newborn receiving phototherapy for hyperbilirubinemia. Which nursing action is appropriate?', 'Opaque eye shields protect the newborn''s retinas during phototherapy while skin exposure is maximized.', '{"options":[{"id":"A","text":"Cover the newborn''s eyes with protective shields"},{"id":"B","text":"Dress the newborn in a long-sleeved gown"},{"id":"C","text":"Apply lotion to the exposed skin"},{"id":"D","text":"Keep the lights off during feedings and all care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Eye protection prevents retinal damage.","B":"Incorrect. Skin exposure maximizes therapy.","C":"Incorrect. Lotions can cause burns under lights.","D":"Incorrect. Exposure should be maximized, not minimized."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321007', 'MCQ', 'A nurse is caring for a client with increased intracranial pressure. Which position best promotes venous drainage from the brain?', 'Elevating the head 30 degrees with the head midline and neck neutral optimizes venous outflow and lowers ICP.', '{"options":[{"id":"A","text":"Head of bed elevated 30 degrees with head midline"},{"id":"B","text":"Flat supine with the neck flexed"},{"id":"C","text":"Trendelenburg position"},{"id":"D","text":"Prone with head turned to the side"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This promotes cerebral venous drainage.","B":"Incorrect. Neck flexion impedes venous return.","C":"Incorrect. Head-down increases ICP.","D":"Incorrect. Head turning obstructs jugular drainage."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321008', 'MCQ', 'A nurse reviews assessment data for a client with suspected sepsis. Which finding is most consistent with early sepsis?', 'Early sepsis commonly presents with fever, tachycardia, and tachypnea as the systemic inflammatory response begins.', '{"options":[{"id":"A","text":"Fever and tachycardia"},{"id":"B","text":"Hypertension and bradycardia"},{"id":"C","text":"Hypothermia with normal heart rate"},{"id":"D","text":"Bounding pulses and dry skin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Fever with tachycardia is common in early sepsis.","B":"Incorrect. Not typical of sepsis.","C":"Incorrect. Less common early presentation.","D":"Incorrect. Not characteristic."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321009', 'MCQ', 'A nurse is changing a dressing on a clean surgical wound. Which technique should the nurse use?', 'Surgical wound dressing changes are performed with sterile technique to prevent surgical site infection.', '{"options":[{"id":"A","text":"Sterile (aseptic) technique"},{"id":"B","text":"Clean technique with bare hands"},{"id":"C","text":"No gloves if the wound looks healed"},{"id":"D","text":"Double-gloving with non-sterile gloves"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Surgical wound dressing changes use sterile technique.","B":"Incorrect. Not appropriate for a surgical wound.","C":"Incorrect. Gloves are always required.","D":"Incorrect. Non-sterile gloves do not maintain asepsis."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321010', 'MCQ', 'A nurse monitoring a client on telemetry observes a heart rate of 45 beats per minute with a regular rhythm. This finding is best described as:', 'A regular rhythm with a rate below 60 beats per minute is sinus bradycardia.', '{"options":[{"id":"A","text":"Sinus bradycardia"},{"id":"B","text":"Sinus tachycardia"},{"id":"C","text":"Atrial fibrillation"},{"id":"D","text":"Ventricular fibrillation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A regular rhythm under 60 bpm is sinus bradycardia.","B":"Incorrect. Tachycardia is over 100 bpm.","C":"Incorrect. AF is irregularly irregular.","D":"Incorrect. VF is chaotic and pulseless."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Telemetry', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321011', 'MCQ', 'A nurse reviews a client''s laboratory results and notes a serum potassium of 6.2 mEq/L. This value indicates:', 'The normal serum potassium range is 3.5-5.0 mEq/L; a value of 6.2 mEq/L is hyperkalemia.', '{"options":[{"id":"A","text":"Hyperkalemia"},{"id":"B","text":"Hypokalemia"},{"id":"C","text":"Hypernatremia"},{"id":"D","text":"A normal potassium level"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Potassium above 5.0 mEq/L is hyperkalemia.","B":"Incorrect. Low potassium is below 3.5 mEq/L.","C":"Incorrect. That refers to sodium.","D":"Incorrect. Normal is 3.5-5.0 mEq/L."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321012', 'MCQ', 'A nurse is caring for a client with a temperature of 39.4°C (103°F). Which nursing intervention is appropriate to promote heat loss?', 'Removing excess coverings and applying cool compresses facilitate heat loss for a febrile client.', '{"options":[{"id":"A","text":"Apply a cool compress and remove excess blankets"},{"id":"B","text":"Cover the client with several warm blankets"},{"id":"C","text":"Increase the room temperature"},{"id":"D","text":"Restrict all oral fluids"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These measures promote heat loss.","B":"Incorrect. This traps heat.","C":"Incorrect. This impairs heat loss.","D":"Incorrect. Fluids are encouraged with fever."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Fundamentals of Nursing', 'Multisystem', 'Temperature regulation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_321013', 'MCQ', 'The high-pressure alarm sounds on a mechanically ventilated client''s ventilator. Which is the most likely cause?', 'A high-pressure ventilator alarm often signals increased airway resistance from secretions, kinking, or coughing.', '{"options":[{"id":"A","text":"Secretions obstructing the airway"},{"id":"B","text":"A disconnection in the ventilator circuit"},{"id":"C","text":"A cuff leak in the endotracheal tube"},{"id":"D","text":"The client is fully sedated and relaxed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Secretions increase airway resistance and pressure.","B":"Incorrect. Disconnection triggers a low-pressure alarm.","C":"Incorrect. A leak lowers pressure.","D":"Incorrect. This does not raise pressure."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_321014', 'SATA', 'A nurse assesses a client for fluid volume deficit (dehydration). Which findings support this diagnosis? Select all that apply.', 'Fluid volume deficit produces dry mucous membranes, poor turgor, tachycardia, and concentrated urine.', '{"options":[{"id":"A","text":"Dry mucous membranes"},{"id":"B","text":"Poor skin turgor"},{"id":"C","text":"Increased heart rate"},{"id":"D","text":"Concentrated, dark urine"},{"id":"E","text":"Bounding peripheral pulses"},{"id":"F","text":"Distended neck veins"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Dehydration', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_321015', 'SATA', 'A nurse plans interventions to promote airway clearance in a postoperative client. Which measures are appropriate? Select all that apply.', 'Incentive spirometry, deep breathing/coughing, hydration, and repositioning all promote airway clearance.', '{"options":[{"id":"A","text":"Encourage use of an incentive spirometer"},{"id":"B","text":"Teach deep breathing and coughing"},{"id":"C","text":"Encourage adequate fluid intake to thin secretions"},{"id":"D","text":"Assist with frequent position changes"},{"id":"E","text":"Keep the client flat and immobile"},{"id":"F","text":"Withhold oral fluids to reduce secretions"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Pulmonary hygiene', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_321016', 'SATA', 'A nurse monitors a postoperative client for signs of hemorrhage. Which findings should the nurse report? Select all that apply.', 'Hypotension, tachycardia, increasing bloody drainage, and restlessness are early signs of postoperative hemorrhage.', '{"options":[{"id":"A","text":"Falling blood pressure"},{"id":"B","text":"Rising heart rate"},{"id":"C","text":"Increasing bright red drainage on the dressing"},{"id":"D","text":"Restlessness and anxiety"},{"id":"E","text":"Warm, dry, pink skin"},{"id":"F","text":"Blood pressure of 122/78 mmHg"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative care', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_321017', 'SATA', 'A nurse assesses a client for hypoglycemia. Which manifestations support this finding? Select all that apply.', 'Hypoglycemia produces adrenergic and neuroglycopenic signs: sweating, tremor, tachycardia, and confusion.', '{"options":[{"id":"A","text":"Diaphoresis"},{"id":"B","text":"Shakiness/tremor"},{"id":"C","text":"Confusion"},{"id":"D","text":"Tachycardia"},{"id":"E","text":"Fruity breath odor"},{"id":"F","text":"Increased urine output"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Hypoglycemia', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_321018', 'SATA', 'A nurse cares for a client receiving peritoneal dialysis. Which findings indicate a complication that should be reported? Select all that apply.', 'Cloudy effluent, fever, and abdominal pain suggest peritonitis; poor drainage signals catheter malfunction.', '{"options":[{"id":"A","text":"Cloudy dialysate outflow"},{"id":"B","text":"Fever and abdominal pain"},{"id":"C","text":"Markedly reduced outflow volume"},{"id":"D","text":"Clear, pale-yellow dialysate outflow"},{"id":"E","text":"Outflow volume roughly equal to inflow"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_321019', 'SATA', 'A nurse assesses a client for fluid volume overload. Which findings are consistent with this condition? Select all that apply.', 'Fluid overload presents with edema, crackles, JVD, and weight gain, opposite to the signs of deficit.', '{"options":[{"id":"A","text":"Peripheral edema"},{"id":"B","text":"Bilateral crackles in the lungs"},{"id":"C","text":"Distended jugular veins"},{"id":"D","text":"Sudden weight gain"},{"id":"E","text":"Poor skin turgor"},{"id":"F","text":"Dry mucous membranes"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Fluid volume overload', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_321020', 'SELECT_N', 'A nurse cares for a client with a central venous catheter. Which 2 actions help prevent central line-associated bloodstream infection?', 'Hand hygiene and hub scrubbing (aseptic technique) are core measures to prevent CLABSI.', '{"options":[{"id":"A","text":"Perform hand hygiene before accessing the line"},{"id":"B","text":"Scrub the catheter hub with antiseptic before each use"},{"id":"C","text":"Leave the dressing in place even when it is loose and soiled"},{"id":"D","text":"Access the line with bare hands to save time"},{"id":"E","text":"Keep the catheter in longer than needed"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Central line care', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_321021', 'TF', 'During cardiopulmonary resuscitation of an adult in cardiac arrest, chest compressions should be delivered at a rate of 100 to 120 per minute.', 'Current guidelines recommend a compression rate of 100-120 per minute for adult CPR.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Emergency care procedures', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_321022', 'MATRIX', 'For each electrolyte value, click to specify whether it represents a HIGH or LOW result relative to the normal range.', 'Normal ranges: sodium 135-145 mEq/L, potassium 3.5-5.0 mEq/L, calcium 9-10.5 mg/dL.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Sodium 128 mEq/L"},{"id":"r2","text":"Potassium 5.8 mEq/L"},{"id":"r3","text":"Calcium 7.5 mg/dL"},{"id":"r4","text":"Sodium 150 mEq/L"}],"columns":[{"id":"c1","text":"Low"},{"id":"c2","text":"High"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Fluid and electrolyte imbalance', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_321023', 'MATRIX_MR', 'For each condition, select all associated clinical findings.', 'Shock and sepsis cause tachycardia and hypotension; fluid overload causes edema.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Hypovolemic shock"},{"id":"r2","text":"Fluid volume overload"},{"id":"r3","text":"Early sepsis"}],"columns":[{"id":"c1","text":"Tachycardia"},{"id":"c2","text":"Hypotension"},{"id":"c3","text":"Edema"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Complication recognition', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_321024', 'CLOZE', 'A client''s oxygen saturation drops to 86%. The nurse''s first action is to {1}, and the expected result is an {2} in oxygen saturation.', 'Applying supplemental oxygen for hypoxemia is the priority and should raise the oxygen saturation.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"apply supplemental oxygen"},{"id":"c2","text":"lower the head of the bed"},{"id":"c3","text":"restrict fluids"}]},{"id":"b2","choices":[{"id":"c1","text":"increase"},{"id":"c2","text":"decrease"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Impaired oxygenation', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_321025', 'HIGHLIGHT', 'Highlight the assessment findings that indicate the postoperative client may be developing shock. Vital signs: Temperature [[37.1°C]], BP [[82/54 mmHg]], HR [[126 bpm]]. Skin is [[cool and clammy]]. Client is [[alert and oriented]]. Urine output [[18 mL/hr]].', 'Hypotension, tachycardia, cool clammy skin, and oliguria together indicate developing shock.', '{"chunks":[{"id":"h1","text":"37.1°C"},{"id":"h2","text":"82/54 mmHg"},{"id":"h3","text":"126 bpm"},{"id":"h4","text":"cool and clammy"},{"id":"h5","text":"alert and oriented"},{"id":"h6","text":"18 mL/hr"}]}'::jsonb, '{"correct_ids":["h2","h3","h4","h6"],"feedback":{"h1":"Normal temperature.","h2":"Hypotension — sign of shock.","h3":"Tachycardia — compensatory sign of shock.","h4":"Poor perfusion — sign of shock.","h5":"Normal neuro status.","h6":"Oliguria — reduced perfusion."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Complication recognition', NULL, 'Easy', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_321026', 'BOWTIE', 'A conscious client with diabetes has a blood glucose of 54 mg/dL. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Hypoglycemia is treated with fast-acting carbohydrate and rechecking glucose, monitoring glucose and mental status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Give 15 g of fast-acting oral carbohydrate"},{"id":"lt2","text":"Recheck blood glucose in 15 minutes"},{"id":"lt3","text":"Withhold all food until the next meal"},{"id":"lt4","text":"Administer rapid-acting insulin"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Hypoglycemia"},{"id":"ct2","text":"Diabetic ketoacidosis"},{"id":"ct3","text":"Hyperosmolar state"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood glucose level"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupil size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Hypoglycemia', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_321027', 'DRAG_CLOZE', 'A body temperature of 35.0°C is classified as [1], while a temperature of 39.0°C is classified as [2].', 'A temperature below 36°C is hypothermia; a temperature above 38°C reflects fever.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"hypothermia"},{"id":"t2","text":"fever"},{"id":"t3","text":"normothermia"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Fundamentals of Nursing', 'Multisystem', 'Temperature regulation', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_321028', 'DRAG_ORDER', 'A client''s chest tube accidentally disconnects from the drainage system. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Submerge the tube end in sterile water"},{"id":"t2","text":"Notify the provider"},{"id":"t3","text":"Assess respiratory status"},{"id":"t4","text":"Obtain a new drainage system"},{"id":"t5","text":"Document the event"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t3","s3":"t4","s4":"t2","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322001', 'MCQ', 'A nurse is monitoring a client with a closed chest drainage system. Which observation in the water-seal chamber is an expected normal finding?', 'Tidaling in the water-seal chamber is an expected finding reflecting normal intrapleural pressure changes.', '{"options":[{"id":"A","text":"Tidaling that rises and falls with respiration"},{"id":"B","text":"Continuous vigorous bubbling"},{"id":"C","text":"No fluid movement at all"},{"id":"D","text":"Bright red fluid filling the chamber"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Gentle tidaling reflects normal pressure changes in the pleural space.","B":"Incorrect. Continuous bubbling suggests an air leak.","C":"Incorrect. Absent tidaling may mean an obstruction or re-expanded lung.","D":"Incorrect. This indicates fresh bleeding, not a normal finding."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube', 'Water-seal drainage', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322002', 'MCQ', 'A nurse assesses a newly formed colostomy on the first postoperative day. Which stoma appearance is normal?', 'A healthy stoma is pink to red and moist; dusky or black color signals ischemia.', '{"options":[{"id":"A","text":"Pink to red and moist"},{"id":"B","text":"Pale and dry"},{"id":"C","text":"Dark purple to black"},{"id":"D","text":"Gray and sunken"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A healthy stoma is pink to red and moist.","B":"Incorrect. Pallor may indicate poor perfusion.","C":"Incorrect. A dusky stoma suggests ischemia and must be reported.","D":"Incorrect. This suggests necrosis."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322003', 'MCQ', 'A nurse cares for a client with an arteriovenous (AV) fistula in the left arm. Which action is appropriate?', 'Blood pressure, venipuncture, and constriction are avoided in the fistula arm to preserve the access.', '{"options":[{"id":"A","text":"Avoid taking blood pressure in the left arm"},{"id":"B","text":"Draw all blood samples from the fistula arm"},{"id":"C","text":"Apply a tight dressing over the fistula"},{"id":"D","text":"Start a peripheral IV in the fistula arm"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. BP and venipuncture in the fistula arm can damage the access.","B":"Incorrect. Venipuncture in the fistula arm is avoided.","C":"Incorrect. Pressure can occlude the fistula.","D":"Incorrect. IVs are not placed in the access arm."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'AV fistula', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322004', 'MCQ', 'Before suctioning a client''s endotracheal tube, which action should the nurse take to reduce hypoxia?', 'Hyperoxygenation before suctioning prevents the hypoxia that suctioning can cause.', '{"options":[{"id":"A","text":"Hyperoxygenate the client with 100% oxygen"},{"id":"B","text":"Suction for a full 30 seconds"},{"id":"C","text":"Instill 10 mL of saline routinely"},{"id":"D","text":"Apply suction while inserting the catheter"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Preoxygenation reduces suction-induced hypoxia.","B":"Incorrect. Suction passes should be limited to 10-15 seconds.","C":"Incorrect. Routine saline instillation is not recommended.","D":"Incorrect. Suction is applied only on withdrawal."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322005', 'MCQ', 'A nurse reviews labs for a client with a serum potassium of 6.8 mEq/L. Which finding is most consistent with hyperkalemia?', 'Peaked T waves are a hallmark ECG change of hyperkalemia.', '{"options":[{"id":"A","text":"Peaked T waves on the ECG"},{"id":"B","text":"U waves on the ECG"},{"id":"C","text":"Constipation and ileus"},{"id":"D","text":"Muscle cramps with hypertension"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Peaked T waves are a classic ECG sign of hyperkalemia.","B":"Incorrect. U waves are associated with hypokalemia.","C":"Incorrect. Hyperkalemia causes hyperactive bowel/diarrhea.","D":"Incorrect. Hyperkalemia typically causes weakness."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Fluid and electrolyte imbalance', 'Hyperkalemia', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322006', 'MCQ', 'A newborn is receiving phototherapy for hyperbilirubinemia. Which nursing action is appropriate?', 'Eye shielding protects the retina; skin exposure and feeding support treatment.', '{"options":[{"id":"A","text":"Cover the newborn''s eyes with protective shields"},{"id":"B","text":"Dress the newborn in a long-sleeved gown"},{"id":"C","text":"Apply lotion to the skin before treatment"},{"id":"D","text":"Withhold all feedings during therapy"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Eye shields protect the retina from the phototherapy lights.","B":"Incorrect. Maximal skin exposure is needed.","C":"Incorrect. Lotions can cause burns under the lights.","D":"Incorrect. Feedings promote bilirubin excretion."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322007', 'MCQ', 'A nurse assesses a client with suspected sepsis. Which early finding would the nurse expect?', 'Early sepsis produces fever, warm flushed skin, tachycardia, and vasodilation.', '{"options":[{"id":"A","text":"Fever with warm, flushed skin"},{"id":"B","text":"Cold, mottled extremities with bradycardia"},{"id":"C","text":"Hypertension with bradycardia"},{"id":"D","text":"Decreased respiratory rate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Early (warm) sepsis presents with fever and vasodilation.","B":"Incorrect. This reflects late septic shock.","C":"Incorrect. Sepsis causes hypotension and tachycardia.","D":"Incorrect. Tachypnea is expected."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322008', 'MCQ', 'A nurse performs a sterile dressing change on a surgical wound. Which technique maintains asepsis?', 'Cleaning from the center outward moves from least to most contaminated, maintaining asepsis.', '{"options":[{"id":"A","text":"Clean the wound from the center outward"},{"id":"B","text":"Clean from the outer edges toward the center"},{"id":"C","text":"Reuse the same gauze for several strokes"},{"id":"D","text":"Touch the wound bed with an ungloved hand"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cleaning from least to most contaminated (center outward) prevents contamination.","B":"Incorrect. This drags contaminants into the wound.","C":"Incorrect. A new gauze is used for each stroke.","D":"Incorrect. Sterile technique is required."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322009', 'MCQ', 'A nurse observes a client''s cardiac monitor showing a regular rhythm with a rate of 40 bpm and normal P-QRS-T complexes. Which rhythm does this represent?', 'A regular rhythm below 60 bpm with normal complexes defines sinus bradycardia.', '{"options":[{"id":"A","text":"Sinus bradycardia"},{"id":"B","text":"Sinus tachycardia"},{"id":"C","text":"Atrial fibrillation"},{"id":"D","text":"Ventricular fibrillation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A regular rhythm under 60 bpm with normal complexes is sinus bradycardia.","B":"Incorrect. Tachycardia is above 100 bpm.","C":"Incorrect. A-fib is irregular with no clear P waves.","D":"Incorrect. V-fib has no organized complexes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Telemetry', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322010', 'MCQ', 'A high-pressure alarm sounds on a mechanically ventilated client''s ventilator. Which cause should the nurse assess first?', 'High-pressure alarms indicate increased resistance, commonly from secretions, kinking, or biting.', '{"options":[{"id":"A","text":"Secretions obstructing the airway"},{"id":"B","text":"A disconnected ventilator circuit"},{"id":"C","text":"A cuff leak in the tube"},{"id":"D","text":"An extubated tube"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A high-pressure alarm often signals increased airway resistance such as secretions.","B":"Incorrect. Disconnection triggers a low-pressure alarm.","C":"Incorrect. A leak causes a low-pressure alarm.","D":"Incorrect. This causes a low-pressure/apnea alarm."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'Alarms', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322011', 'MCQ', 'A nurse cares for a client with a temperature of 40.1°C (104.2°F). Which intervention is appropriate to reduce the fever?', 'Antipyretics plus cooling measures and fluids reduce hyperthermia.', '{"options":[{"id":"A","text":"Apply cool compresses and administer an antipyretic"},{"id":"B","text":"Cover the client with several warm blankets"},{"id":"C","text":"Withhold all oral fluids"},{"id":"D","text":"Place the client in a warm bath"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cooling measures and antipyretics lower the temperature.","B":"Incorrect. This raises the temperature further.","C":"Incorrect. Fluids are encouraged to prevent dehydration.","D":"Incorrect. A tepid bath is used, not warm."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Fundamentals of Nursing', 'Multisystem', 'Temperature regulation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322012', 'MCQ', 'A client has a nasogastric tube set to low intermittent suction after abdominal surgery. What is the primary purpose of the tube?', 'Postoperative NG suction decompresses the stomach, preventing distension, nausea, and vomiting.', '{"options":[{"id":"A","text":"To decompress the stomach and prevent distension"},{"id":"B","text":"To deliver continuous tube feedings"},{"id":"C","text":"To measure intracranial pressure"},{"id":"D","text":"To administer IV fluids"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Postoperative NG suction removes gastric contents and gas to prevent distension.","B":"Incorrect. A tube on suction is not used for feeding.","C":"Incorrect. NG tubes do not measure ICP.","D":"Incorrect. IV fluids go through a vein, not the NG tube."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative care', 'NG tube', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_322013', 'MCQ', 'A client in hypovolemic shock has a blood pressure of 80/40 mmHg. Which position should the nurse place the client in?', 'Elevating the legs promotes venous return and improves perfusion in hypovolemic shock.', '{"options":[{"id":"A","text":"Supine with legs slightly elevated"},{"id":"B","text":"High Fowler''s position"},{"id":"C","text":"Prone position"},{"id":"D","text":"Left lateral Sims'' position"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Modified Trendelenburg (legs elevated) promotes venous return in shock.","B":"Incorrect. Sitting upright reduces cerebral perfusion.","C":"Incorrect. This is not indicated for shock.","D":"Incorrect. This does not improve perfusion in shock."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Shock', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_322014', 'SATA', 'A nurse assesses a client with fluid volume deficit (dehydration). Which findings are expected? Select all that apply.', 'Fluid deficit causes poor turgor, dry membranes, tachycardia, and concentrated urine; edema and JVD indicate overload.', '{"options":[{"id":"A","text":"Poor skin turgor"},{"id":"B","text":"Dry mucous membranes"},{"id":"C","text":"Tachycardia"},{"id":"D","text":"Concentrated dark urine"},{"id":"E","text":"Bounding pulses and edema"},{"id":"F","text":"Jugular vein distension"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', 'Dehydration', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_322015', 'SATA', 'A nurse cares for a client with a chest tube drainage system. Which actions are appropriate? Select all that apply.', 'The system stays below chest level with patent tubing; routine stripping and prolonged clamping are avoided.', '{"options":[{"id":"A","text":"Keep the drainage system below the level of the chest"},{"id":"B","text":"Assess the insertion site for subcutaneous emphysema"},{"id":"C","text":"Ensure connections are secure and tubing is free of kinks"},{"id":"D","text":"Strip and milk the tubing routinely"},{"id":"E","text":"Clamp the tube during transport for long periods"},{"id":"F","text":"Empty the collection chamber by disconnecting it hourly"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_322016', 'SATA', 'A nurse monitors a client in the immediate postoperative period. Which findings should be reported to the provider? Select all that apply.', 'Hypoxia, oliguria, active bleeding, and hypotension with tachycardia are complications requiring notification.', '{"options":[{"id":"A","text":"Oxygen saturation of 86% on room air"},{"id":"B","text":"Urine output of 15 mL/hr"},{"id":"C","text":"Bright red blood saturating the dressing"},{"id":"D","text":"Blood pressure trending downward with tachycardia"},{"id":"E","text":"Drowsiness that resolves when spoken to"},{"id":"F","text":"Pain rated 3 of 10 after analgesia"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Postoperative care', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_322017', 'SATA', 'A nurse teaches a client about caring for a new colostomy. Which statements indicate correct understanding? Select all that apply.', 'The pouch is emptied when one-third full, the appliance is sized to the stoma, and color changes are reported.', '{"options":[{"id":"A","text":"\"I will empty the pouch when it is about one-third full.\""},{"id":"B","text":"\"I will measure the stoma to fit the appliance opening.\""},{"id":"C","text":"\"I will report a stoma that turns dark or dusky.\""},{"id":"D","text":"\"I will change the appliance only once a month.\""},{"id":"E","text":"\"I should expect the stoma to be pale and dry.\""}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_322018', 'SATA', 'A nurse plans pulmonary hygiene measures for a client with retained secretions. Which interventions are appropriate? Select all that apply.', 'Deep breathing, hydration, spirometry, and repositioning mobilize secretions and improve ventilation.', '{"options":[{"id":"A","text":"Encourage deep breathing and coughing"},{"id":"B","text":"Promote adequate hydration"},{"id":"C","text":"Assist with incentive spirometry"},{"id":"D","text":"Encourage frequent repositioning"},{"id":"E","text":"Keep the client supine and immobile"},{"id":"F","text":"Withhold fluids to reduce secretions"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Pulmonary hygiene', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_322019', 'SATA', 'A nurse reviews findings for a client with a serum potassium of 2.8 mEq/L. Which manifestations are consistent with hypokalemia? Select all that apply.', 'Hypokalemia causes muscle weakness, dysrhythmias, and decreased GI motility; peaked T waves indicate hyperkalemia.', '{"options":[{"id":"A","text":"Muscle weakness"},{"id":"B","text":"Cardiac dysrhythmias"},{"id":"C","text":"Decreased bowel sounds"},{"id":"D","text":"Peaked T waves"},{"id":"E","text":"Hyperactive deep tendon reflexes"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Fluid and electrolyte imbalance', 'Hypokalemia', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_322020', 'SELECT_N', 'A nurse finds an unresponsive client without a pulse. Which 3 actions are part of the immediate emergency response?', 'Activating help, starting compressions, and applying the AED are the immediate steps for cardiac arrest.', '{"options":[{"id":"A","text":"Call for help and activate the emergency response system"},{"id":"B","text":"Begin high-quality chest compressions"},{"id":"C","text":"Attach an automated external defibrillator (AED)"},{"id":"D","text":"Document the event in the chart first"},{"id":"E","text":"Offer the client oral fluids"},{"id":"F","text":"Wait for the provider before starting CPR"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Emergency care procedures', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_322021', 'TF', 'During peritoneal dialysis, dialysate that returns cloudy may indicate peritonitis and should be reported.', 'Cloudy effluent is a sign of peritonitis, a serious complication of peritoneal dialysis.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_322022', 'MATRIX', 'For each finding, click to specify whether it is associated with fluid volume deficit or fluid volume overload.', 'Deficit produces poor turgor and dryness; overload produces bounding pulse, crackles, and weight gain.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Poor skin turgor"},{"id":"r2","text":"Bounding pulse"},{"id":"r3","text":"Crackles in the lungs"},{"id":"r4","text":"Dry mucous membranes"},{"id":"r5","text":"Weight gain of 2 kg overnight"}],"columns":[{"id":"c1","text":"Fluid volume deficit"},{"id":"c2","text":"Fluid volume overload"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_322023', 'MATRIX_MR', 'For each condition, select all findings the nurse would expect (findings may apply to more than one condition).', 'Tachycardia is common to all; sepsis adds fever, and shock states produce hypotension.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Early sepsis"},{"id":"r2","text":"Hypovolemic shock"},{"id":"r3","text":"Septic shock (late)"}],"columns":[{"id":"c1","text":"Tachycardia"},{"id":"c2","text":"Hypotension"},{"id":"c3","text":"Fever"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c1","c2"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Complication recognition', NULL, 'Easy', 'Understand', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_322024', 'CLOZE', 'A client with an oxygen saturation of 88% is experiencing {1}, and the nurse''s first action is to {2}.', 'A saturation of 88% indicates hypoxemia; applying oxygen is the priority intervention.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hypoxemia"},{"id":"c2","text":"hyperoxia"},{"id":"c3","text":"polycythemia"}]},{"id":"b2","choices":[{"id":"c1","text":"apply supplemental oxygen"},{"id":"c2","text":"restrict fluids"},{"id":"c3","text":"lower the head of the bed"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Impaired oxygenation', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_322025', 'HIGHLIGHT', 'Highlight the findings that indicate impaired oxygenation requiring follow-up. The client is alert. SpO2 [[85% on room air]]. Respiratory rate [[32/min]]. Temperature [[37.0°C]]. Skin shows [[circumoral cyanosis]]. Reports [[increasing shortness of breath]]. Bowel sounds are present in all quadrants.', 'Low saturation, tachypnea, cyanosis, and worsening dyspnea all indicate impaired oxygenation.', '{"chunks":[{"id":"h1","text":"85% on room air"},{"id":"h2","text":"32/min"},{"id":"h3","text":"37.0°C"},{"id":"h4","text":"circumoral cyanosis"},{"id":"h5","text":"increasing shortness of breath"}]}'::jsonb, '{"correct_ids":["h1","h2","h4","h5"],"feedback":{"h1":"Hypoxemia — needs follow-up.","h2":"Tachypnea — a sign of respiratory distress.","h3":"Normal temperature — no follow-up needed.","h4":"Cyanosis indicates poor oxygenation.","h5":"Worsening dyspnea requires follow-up."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Impaired ventilation', NULL, 'Easy', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_322026', 'BOWTIE', 'Complete the diagram for a client with early sepsis by selecting the actions, the condition, and the parameters to monitor.', 'Early sepsis is managed with cultures and fluids while monitoring temperature and blood pressure.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Obtain blood cultures"},{"id":"lt2","text":"Administer prescribed IV fluids"},{"id":"lt3","text":"Restrict all fluids"},{"id":"lt4","text":"Withhold antibiotics until fever resolves"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Sepsis"},{"id":"ct2","text":"Hypothyroidism"},{"id":"ct3","text":"Migraine"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Temperature"},{"id":"rt2","text":"Blood pressure"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupil size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_322027', 'DRAG_CLOZE', 'A serum sodium of 128 mEq/L indicates [1], and a serum sodium of 150 mEq/L indicates [2].', 'Sodium below 135 mEq/L is hyponatremia; above 145 mEq/L is hypernatremia.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"hyponatremia"},{"id":"t2","text":"hypernatremia"},{"id":"t3","text":"hyperkalemia"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', NULL, 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_322028', 'DRAG_ORDER', 'Place the steps for open tracheostomy suctioning in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and don sterile gloves"},{"id":"t2","text":"Hyperoxygenate the client"},{"id":"t3","text":"Insert the catheter without applying suction"},{"id":"t4","text":"Apply intermittent suction while withdrawing the catheter"},{"id":"t5","text":"Reoxygenate and assess the client"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309001', 'MCQ', 'A client newly diagnosed with cancer says, "I don''t know how I''ll get through this." Which response by the nurse is most therapeutic?', 'Open-ended statements encourage the client to explore and express emotions.', '{"options":[{"id":"A","text":"\"Tell me more about what you''re feeling right now.\""},{"id":"B","text":"\"Don''t worry, everything will be fine.\""},{"id":"C","text":"\"You should focus on staying positive.\""},{"id":"D","text":"\"Many people do very well with treatment.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An open-ended, empathetic response invites the client to express feelings.","B":"Incorrect. False reassurance dismisses the client''s concern.","C":"Incorrect. Giving advice blocks communication.","D":"Incorrect. This minimizes and offers false reassurance."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Open-ended technique', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309002', 'MCQ', 'A client whose spouse recently died states, "There must be a mistake; the test results can''t be right." Which stage of grief is the client displaying?', 'Disbelief and refusal to accept reality characterize the denial stage of grief.', '{"options":[{"id":"A","text":"Denial"},{"id":"B","text":"Bargaining"},{"id":"C","text":"Acceptance"},{"id":"D","text":"Anger"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Refusing to accept the loss reflects the denial stage.","B":"Incorrect. Bargaining involves making deals to postpone loss.","C":"Incorrect. Acceptance involves coming to terms with the loss.","D":"Incorrect. Anger involves resentment and blame."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', 'Kübler-Ross stages', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309003', 'MCQ', 'A client experiencing a panic attack is breathing rapidly and states they feel like they are dying. Which action should the nurse take first?', 'During panic-level anxiety, staying present and using a calm voice provides safety and reduces distress.', '{"options":[{"id":"A","text":"Stay with the client and speak in a calm, reassuring voice"},{"id":"B","text":"Leave the client alone to rest quietly"},{"id":"C","text":"Explain the physiology of panic in detail"},{"id":"D","text":"Encourage the client to make a decision about treatment"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Presence and a calm voice help reduce the client''s anxiety.","B":"Incorrect. Leaving a panicked client alone increases fear.","C":"Incorrect. A highly anxious client cannot process detailed teaching.","D":"Incorrect. Decision-making is impaired during panic."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', 'Nursing intervention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309004', 'MCQ', 'A client with major depression says, "Everyone would be better off without me." What is the nurse''s priority action?', 'Asking directly about suicidal ideation is safe and necessary to assess risk and ensure safety.', '{"options":[{"id":"A","text":"Directly ask the client if they are thinking of suicide"},{"id":"B","text":"Change the subject to something more positive"},{"id":"C","text":"Reassure the client that their family loves them"},{"id":"D","text":"Document the statement and continue care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Asking directly about suicidal thoughts is the priority for safety.","B":"Incorrect. Avoiding the topic ignores a safety cue.","C":"Incorrect. False reassurance does not assess risk.","D":"Incorrect. Documentation alone delays urgent safety assessment."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', 'Suicide risk', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309005', 'MCQ', 'A client with schizophrenia reports hearing voices telling them they are worthless. Which is the most appropriate nurse response?', 'Presenting reality while validating the client''s feelings is the therapeutic approach to hallucinations.', '{"options":[{"id":"A","text":"\"I don''t hear the voices, but I understand they feel real and frightening to you.\""},{"id":"B","text":"\"There are no voices; you are imagining them.\""},{"id":"C","text":"\"What exactly are the voices telling you to do?\" asked repeatedly"},{"id":"D","text":"\"You should just ignore the voices.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This presents reality while acknowledging the client''s experience.","B":"Incorrect. Arguing about the hallucination is nontherapeutic.","C":"Incorrect. Dwelling on content can reinforce the hallucination.","D":"Incorrect. Telling the client to ignore them is dismissive and ineffective."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Hallucinations', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309006', 'MCQ', 'A nurse is caring for a client with moderate dementia who becomes agitated during care. Which approach is most appropriate?', 'Short simple sentences and a calm approach reduce confusion and agitation in dementia.', '{"options":[{"id":"A","text":"Use short, simple sentences and a calm tone"},{"id":"B","text":"Provide detailed explanations of each task"},{"id":"C","text":"Ask the client to explain why they are upset"},{"id":"D","text":"Speak louder and faster to get attention"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Simple communication and calm reduce agitation in dementia.","B":"Incorrect. Complex information overwhelms clients with dementia.","C":"Incorrect. Abstract reasoning is impaired in dementia.","D":"Incorrect. This increases agitation."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Dementia', 'Communication', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309007', 'MCQ', 'A client admitted 8 hours ago with a history of heavy daily alcohol use develops tremors, sweating, and elevated blood pressure. The nurse recognizes these as signs of what?', 'Early alcohol withdrawal presents with autonomic hyperactivity: tremor, diaphoresis, tachycardia, and hypertension.', '{"options":[{"id":"A","text":"Alcohol withdrawal"},{"id":"B","text":"Alcohol intoxication"},{"id":"C","text":"An allergic reaction"},{"id":"D","text":"Normal adjustment to hospitalization"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Tremors, diaphoresis, and hypertension are early withdrawal signs.","B":"Incorrect. Intoxication causes sedation, not tremors and hypertension.","C":"Incorrect. These are not allergic findings.","D":"Incorrect. These are pathological withdrawal signs."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Alcohol withdrawal', 'Assessment', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309008', 'MCQ', 'A client declines a meal because it conflicts with their religious dietary practices. Which is the best nurse action?', 'Respecting and accommodating cultural and religious dietary practices is culturally competent care.', '{"options":[{"id":"A","text":"Arrange for a meal that meets the client''s dietary requirements"},{"id":"B","text":"Encourage the client to eat this one meal anyway"},{"id":"C","text":"Explain that hospital meals cannot be changed"},{"id":"D","text":"Document that the client refused to eat"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Accommodating cultural and religious practices provides respectful care.","B":"Incorrect. This disregards the client''s beliefs.","C":"Incorrect. Meals can and should be adapted.","D":"Incorrect. This ignores the underlying cultural need."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Cultural care', 'Cultural sensitivity', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309009', 'MCQ', 'A client on the unit is becoming increasingly loud and clenching their fists. Which nurse action best supports de-escalation?', 'Remaining calm and respecting personal space are core de-escalation techniques.', '{"options":[{"id":"A","text":"Maintain a calm demeanor and offer the client personal space"},{"id":"B","text":"Move closer and place a hand on the client''s shoulder"},{"id":"C","text":"Tell the client firmly to calm down immediately"},{"id":"D","text":"Gather several staff to surround the client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A calm approach and adequate personal space reduce escalation.","B":"Incorrect. Invading space and touching may trigger aggression.","C":"Incorrect. Commanding tone can escalate the situation.","D":"Incorrect. Surrounding the client can feel threatening and escalate behavior."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', 'Aggression', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309010', 'MCQ', 'The family of a dying client asks the nurse to "do something" as their loved one becomes less responsive. Which response is most therapeutic?', 'Acknowledging the family''s distress and encouraging presence provides emotional support at end of life.', '{"options":[{"id":"A","text":"\"This is a difficult time. Would you like to sit with them and hold their hand?\""},{"id":"B","text":"\"There is really nothing more that can be done now.\""},{"id":"C","text":"\"You should go home and rest for a while.\""},{"id":"D","text":"\"Try not to be upset in front of the client.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This acknowledges feelings and encourages meaningful presence.","B":"Incorrect. This is dismissive and offers no support.","C":"Incorrect. This does not address the family''s needs.","D":"Incorrect. This blocks expression of emotion."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'End-of-life care', 'Emotional support', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309011', 'MCQ', 'A nurse suspects that an older adult client is being physically abused by a caregiver. What is the nurse''s legal obligation?', 'Nurses are legally mandated reporters and must report reasonable suspicion of abuse.', '{"options":[{"id":"A","text":"Report the suspicion to the appropriate authorities"},{"id":"B","text":"Wait until there is definite proof before acting"},{"id":"C","text":"Confront the caregiver directly and demand an explanation"},{"id":"D","text":"Keep the information confidential to protect the family"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandatory reporters of suspected abuse.","B":"Incorrect. Reporting is based on reasonable suspicion, not proof.","C":"Incorrect. Confrontation is not the nurse''s role and may endanger the client.","D":"Incorrect. Reporting overrides confidentiality in suspected abuse."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Mandatory reporting', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_309012', 'MCQ', 'A client in a manic episode is unable to sit still for meals and has lost weight. Which nursing intervention is most appropriate?', 'High-calorie finger foods meet nutritional needs of a hyperactive manic client who cannot sit still.', '{"options":[{"id":"A","text":"Offer high-calorie finger foods the client can eat while moving"},{"id":"B","text":"Insist the client remain seated for a full meal"},{"id":"C","text":"Withhold food until the client calms down"},{"id":"D","text":"Serve only liquids to save time"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Portable finger foods support nutrition when the client cannot sit still.","B":"Incorrect. A manic client cannot tolerate prolonged sitting.","C":"Incorrect. Withholding food worsens nutritional deficit.","D":"Incorrect. Liquids alone do not meet caloric needs."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Bipolar disorder', 'Mania', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_309013', 'SATA', 'Which of the following are therapeutic communication techniques? Select all that apply.', 'Silence, reflection, and offering presence are therapeutic; advice, ''why'' questions, and changing the subject are blocks.', '{"options":[{"id":"A","text":"Using silence to allow the client time to think"},{"id":"B","text":"Reflecting the client''s feelings back to them"},{"id":"C","text":"Offering to stay with the client"},{"id":"D","text":"Giving the client advice on what to do"},{"id":"E","text":"Asking ''why'' questions repeatedly"},{"id":"F","text":"Changing the subject when topics are uncomfortable"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Techniques', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_309014', 'SATA', 'A nurse assesses a client with major depressive disorder. Which findings would the nurse expect? Select all that apply.', 'Hopelessness, anhedonia, sleep/appetite change, and poor concentration are hallmark depressive findings; grandiosity and increased energy suggest mania.', '{"options":[{"id":"A","text":"Feelings of hopelessness"},{"id":"B","text":"Loss of interest in usual activities"},{"id":"C","text":"Changes in sleep and appetite"},{"id":"D","text":"Difficulty concentrating"},{"id":"E","text":"Grandiose sense of self-importance"},{"id":"F","text":"Excessive energy and rapid speech"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', 'Assessment findings', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_309015', 'SATA', 'A nurse teaches a client with generalized anxiety disorder about coping strategies. Which strategies are appropriate? Select all that apply.', 'Relaxation techniques and exercise reduce anxiety; caffeine and social isolation worsen it.', '{"options":[{"id":"A","text":"Deep breathing exercises"},{"id":"B","text":"Progressive muscle relaxation"},{"id":"C","text":"Regular physical activity"},{"id":"D","text":"Increasing caffeine intake for energy"},{"id":"E","text":"Avoiding all social contact"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety disorders', 'Coping strategies', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_309016', 'SATA', 'Which client behaviors indicate an increased risk for violence? Select all that apply.', 'Motor agitation, muscle tension, and threatening speech are early warning signs of escalating violence.', '{"options":[{"id":"A","text":"Pacing and restlessness"},{"id":"B","text":"Clenched fists and jaw"},{"id":"C","text":"Loud, threatening speech"},{"id":"D","text":"Calmly reading a book"},{"id":"E","text":"Sleeping soundly"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Violence potential', 'Warning signs', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_309017', 'SATA', 'Which findings would a nurse expect in a client with anorexia nervosa? Select all that apply.', 'Anorexia nervosa features low weight, fear of weight gain, distorted body image, and amenorrhea.', '{"options":[{"id":"A","text":"Significantly low body weight"},{"id":"B","text":"Intense fear of gaining weight"},{"id":"C","text":"Distorted body image"},{"id":"D","text":"Amenorrhea"},{"id":"E","text":"Satisfaction with current body weight"},{"id":"F","text":"Frequent overeating without restriction"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Eating disorders', 'Anorexia nervosa', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_309018', 'TF', 'Actively listening and using silence can be therapeutic communication techniques that encourage a client to express feelings.', 'Silence and active listening give the client time and space to process and share emotions.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_309019', 'TF', 'All individuals experience the stages of grief in the same fixed order and over the same length of time.', 'Grief is individual; stages may occur in any order, be repeated, or be skipped, and vary in duration.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_309020', 'SELECT_N', 'Which 3 features characterize a therapeutic milieu on a psychiatric unit?', 'A therapeutic milieu is safe, structured, consistent, and promotes social and coping-skill development.', '{"options":[{"id":"A","text":"A safe, structured daily routine"},{"id":"B","text":"Clear and consistent behavioral expectations"},{"id":"C","text":"Opportunities for social interaction and skill-building"},{"id":"D","text":"Unrestricted access to sharp personal items"},{"id":"E","text":"Frequent unannounced changes to the schedule"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Milieu therapy', 'Therapeutic environment', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_309021', 'MATRIX', 'For each nurse statement, click to classify it as a therapeutic or nontherapeutic response.', 'Exploring and reflecting feelings are therapeutic; minimizing and clichés block communication.', '{"row_label":"Statement","rows":[{"id":"r1","text":"\"Tell me more about how you are feeling.\""},{"id":"r2","text":"\"You shouldn''t feel that way.\""},{"id":"r3","text":"\"It sounds like this has been very hard for you.\""},{"id":"r4","text":"\"Everything happens for a reason.\""}],"columns":[{"id":"c1","text":"Therapeutic"},{"id":"c2","text":"Nontherapeutic"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Therapeutic vs nontherapeutic', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_309022', 'MATRIX_MR', 'For each disorder, select all features the nurse would expect (a feature may apply to more than one).', 'Depression features depressed mood, schizophrenia features hallucinations, and mania features elevated mood.', '{"row_label":"Disorder","rows":[{"id":"r1","text":"Major depressive disorder"},{"id":"r2","text":"Schizophrenia"},{"id":"r3","text":"Bipolar disorder, manic episode"}],"columns":[{"id":"c1","text":"Depressed mood"},{"id":"c2","text":"Hallucinations"},{"id":"c3","text":"Elevated/expansive mood"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"]},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Mental illness features', 'Symptom recognition', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_309023', 'CLOZE', 'A client whose perceptual field is greatly narrowed and who cannot focus without direction is experiencing {1} anxiety. The priority nursing action is to {2}.', 'Severe anxiety greatly narrows perception; the nurse should stay present and give simple, calm direction.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"severe"},{"id":"c2","text":"mild"},{"id":"c3","text":"no"}]},{"id":"b2","choices":[{"id":"c1","text":"remain with the client and provide calm direction"},{"id":"c2","text":"leave the client alone to relax"},{"id":"c3","text":"begin detailed health teaching"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', 'Levels of anxiety', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_309024', 'HIGHLIGHT', 'Highlight the statements in the nursing note that indicate increased suicide risk. Client [[gave away a prized guitar to a friend]] yesterday. States [["I won''t be a burden much longer"]]. Reports [[sleeping well and eating three meals]]. Client [[has a specific plan and access to pills]]. Enjoys visits from family.', 'Giving away possessions, verbal cues, and a specific plan with means all indicate elevated suicide risk.', '{"chunks":[{"id":"h1","text":"gave away a prized guitar to a friend"},{"id":"h2","text":"\"I won''t be a burden much longer\""},{"id":"h3","text":"sleeping well and eating three meals"},{"id":"h4","text":"has a specific plan and access to pills"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"Giving away possessions is a warning sign.","h2":"This suggests suicidal ideation.","h3":"Normal self-care is not a risk cue.","h4":"A plan with available means is high risk."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', 'Warning cues', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_309025', 'BOWTIE', 'A client 10 hours after their last drink has tremors and rising vital signs. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Alcohol withdrawal risks seizures; manage with seizure precautions and calm environment, monitoring vital signs and consciousness.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Institute seizure precautions"},{"id":"lt2","text":"Provide a calm, low-stimulation environment"},{"id":"lt3","text":"Encourage caffeinated beverages"},{"id":"lt4","text":"Restrain the client preventively"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Alcohol withdrawal"},{"id":"ct2","text":"Manic episode"},{"id":"ct3","text":"Panic disorder"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Vital signs"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Deep tendon reflexes only"},{"id":"rt4","text":"Daily weight only"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Alcohol withdrawal', 'Recognition and response', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_309026', 'DRAG_CLOZE', 'A woman grieving before her terminally ill husband has died is experiencing [1] grief, whereas prolonged grief that impairs daily functioning is called [2] grief.', 'Anticipatory grief occurs before a loss; complicated grief is prolonged and impairs functioning.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"anticipatory"},{"id":"t2","text":"complicated"},{"id":"t3","text":"delayed"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', 'Types of grief', 'Easy', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_309027', 'DRAG_ORDER', 'A client is becoming verbally agitated in the day room. Place the nurse''s de-escalation actions in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"}],"tokens":[{"id":"t1","text":"Ensure personal safety and adequate space"},{"id":"t2","text":"Speak calmly and acknowledge the client''s feelings"},{"id":"t3","text":"Offer choices to help the client regain control"},{"id":"t4","text":"Document the interaction and client response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', 'Priority actions', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310001', 'MCQ', 'A client newly diagnosed with cancer becomes quiet during an admission interview. Which response by the nurse is most therapeutic?', 'Open-ended statements invite the client to share feelings and build rapport.', '{"options":[{"id":"A","text":"\"Tell me more about how you are feeling right now.\""},{"id":"B","text":"\"Everything will be fine, don''t worry.\""},{"id":"C","text":"\"Why are you so upset about this?\""},{"id":"D","text":"\"Let''s talk about your discharge plan instead.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An open-ended invitation encourages the client to express feelings.","B":"Incorrect. False reassurance blocks communication.","C":"Incorrect. ''Why'' questions can feel accusatory.","D":"Incorrect. Changing the subject dismisses the client''s feelings."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Open-ended questions', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310002', 'MCQ', 'A client whose spouse died yesterday says, "There must be a mistake, my husband can''t be gone." Which stage of grief is the client demonstrating?', 'Refusing to believe a loss has occurred is characteristic of the denial stage.', '{"options":[{"id":"A","text":"Denial"},{"id":"B","text":"Acceptance"},{"id":"C","text":"Bargaining"},{"id":"D","text":"Anger"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Disbelief and refusal to accept the loss reflect denial.","B":"Incorrect. Acceptance involves coming to terms with the loss.","C":"Incorrect. Bargaining involves making deals to postpone the loss.","D":"Incorrect. Anger involves resentment and blame."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', 'Denial stage', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310003', 'MCQ', 'An agitated client is pacing and raising his voice in the day room. Which initial nursing action is most appropriate?', 'A calm voice and non-threatening body language are the first steps in de-escalation.', '{"options":[{"id":"A","text":"Speak calmly and maintain a non-threatening posture"},{"id":"B","text":"Place the client in seclusion immediately"},{"id":"C","text":"Approach and touch the client''s shoulder to reassure him"},{"id":"D","text":"Tell the client he will lose privileges if he continues"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A calm approach and open posture help de-escalate agitation.","B":"Incorrect. Seclusion is a last resort, not the first action.","C":"Incorrect. Touch may be perceived as threatening and escalate agitation.","D":"Incorrect. Threats increase agitation."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310004', 'MCQ', 'A nurse suspects that an older adult client is being physically abused by a caregiver. What is the nurse''s legal responsibility?', 'Nurses are mandatory reporters and must report reasonable suspicion of abuse.', '{"options":[{"id":"A","text":"Report the suspicion to the appropriate authorities"},{"id":"B","text":"Confront the caregiver about the abuse"},{"id":"C","text":"Wait until abuse is proven before acting"},{"id":"D","text":"Advise the client to move out of the home"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandatory reporters of suspected abuse.","B":"Incorrect. Confrontation may place the client at greater risk.","C":"Incorrect. Reporting is based on reasonable suspicion, not proof.","D":"Incorrect. This is not the nurse''s decision or legal duty."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Mandatory reporting', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310005', 'MCQ', 'A client experiencing a panic attack is hyperventilating and unable to focus. Which nursing intervention is appropriate?', 'During panic-level anxiety, the nurse stays with the client and uses calm reassurance.', '{"options":[{"id":"A","text":"Stay with the client and use a calm, reassuring voice"},{"id":"B","text":"Provide detailed teaching about anxiety triggers"},{"id":"C","text":"Leave the client alone to calm down"},{"id":"D","text":"Encourage the client to make a list of stressors"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Remaining present and calm reduces panic-level anxiety.","B":"Incorrect. Learning is impaired during panic; teaching is not appropriate now.","C":"Incorrect. The client should not be left alone during panic.","D":"Incorrect. Complex tasks are not possible at panic level."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', 'Panic level', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310006', 'MCQ', 'A client with schizophrenia states, "The voices are telling me to hurt myself." Which is the nurse''s priority response?', 'Command hallucinations to self-harm require immediate safety assessment.', '{"options":[{"id":"A","text":"\"Are the voices telling you to harm yourself right now?\""},{"id":"B","text":"\"The voices are not real, try to ignore them.\""},{"id":"C","text":"\"Let''s talk about something more pleasant.\""},{"id":"D","text":"\"You should not listen to those voices.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Assessing for command hallucinations addresses immediate safety.","B":"Incorrect. This dismisses the client and does not assess safety.","C":"Incorrect. Changing the subject ignores the safety risk.","D":"Incorrect. This does not assess the immediate danger."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Hallucinations', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310007', 'MCQ', 'A client declines a meal that contains pork, stating it is against her religious beliefs. Which nursing action is most appropriate?', 'Respecting religious and cultural dietary practices is part of culturally competent care.', '{"options":[{"id":"A","text":"Arrange for a meal that respects the client''s beliefs"},{"id":"B","text":"Explain that the hospital diet must be followed"},{"id":"C","text":"Encourage the client to eat around the pork"},{"id":"D","text":"Document that the client is non-compliant"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Culturally competent care accommodates religious dietary practices.","B":"Incorrect. This disregards the client''s beliefs.","C":"Incorrect. This does not respect the religious restriction.","D":"Incorrect. Honoring beliefs is not non-compliance."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Cultural care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310008', 'MCQ', 'A client admitted for alcohol withdrawal develops tremors, sweating, and anxiety 8 hours after the last drink. These are expected signs of which condition?', 'Tremors, diaphoresis, and anxiety within hours of the last drink indicate early alcohol withdrawal.', '{"options":[{"id":"A","text":"Early alcohol withdrawal"},{"id":"B","text":"Alcohol intoxication"},{"id":"C","text":"Wernicke encephalopathy"},{"id":"D","text":"Opioid withdrawal"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Tremors, diaphoresis, and anxiety are early withdrawal signs.","B":"Incorrect. Intoxication presents with sedation and slurred speech.","C":"Incorrect. This involves confusion, ataxia, and eye changes.","D":"Incorrect. This scenario is alcohol, not opioid, withdrawal."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Substance withdrawal', 'Alcohol', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310009', 'MCQ', 'A nurse is caring for a client with moderate dementia who becomes confused during care. Which communication strategy is best?', 'Short, simple sentences delivered calmly help clients with dementia understand.', '{"options":[{"id":"A","text":"Use short, simple sentences and a calm tone"},{"id":"B","text":"Give several instructions at once to save time"},{"id":"C","text":"Speak rapidly to keep the client''s attention"},{"id":"D","text":"Use complex explanations to reorient the client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Simple, clear communication reduces confusion in dementia.","B":"Incorrect. Multiple instructions overwhelm the client.","C":"Incorrect. Rapid speech increases confusion.","D":"Incorrect. Complex explanations are difficult to process."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Dementia', 'Communication', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310010', 'MCQ', 'A client caring for a spouse with a terminal illness reports feeling overwhelmed. Which nursing action best supports the client''s coping?', 'Linking a stressed caregiver to respite and support resources promotes healthy coping.', '{"options":[{"id":"A","text":"Provide information about respite care and support groups"},{"id":"B","text":"Tell the client to stop worrying so much"},{"id":"C","text":"Advise the client to place the spouse in a facility"},{"id":"D","text":"Suggest the client avoid thinking about the illness"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Connecting the client to support resources strengthens coping.","B":"Incorrect. This dismisses the client''s feelings.","C":"Incorrect. This is not the nurse''s decision to make.","D":"Incorrect. Avoidance is not an effective coping strategy."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Coping', 'Support systems', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310011', 'MCQ', 'A dying client asks the nurse, "Am I going to die soon?" Which response is most therapeutic?', 'Encouraging the client to explore feelings supports therapeutic end-of-life communication.', '{"options":[{"id":"A","text":"\"This sounds like something on your mind. Can you tell me more?\""},{"id":"B","text":"\"You shouldn''t think like that.\""},{"id":"C","text":"\"That''s a question for your doctor.\""},{"id":"D","text":"\"Everyone dies eventually.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Exploring the client''s feelings opens therapeutic dialogue.","B":"Incorrect. This blocks communication.","C":"Incorrect. This deflects the client''s emotional need.","D":"Incorrect. This is dismissive."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'End-of-life care', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_310012', 'MCQ', 'A client with depression states, "Everyone would be better off without me." What should the nurse do first?', 'Any hint of suicidal ideation requires the nurse to ask directly about suicidal thoughts.', '{"options":[{"id":"A","text":"Directly ask whether the client is thinking of suicide"},{"id":"B","text":"Reassure the client that things will get better"},{"id":"C","text":"Document the statement and continue care"},{"id":"D","text":"Notify the family of the client''s mood"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Asking directly about suicidal thoughts is the priority safety assessment.","B":"Incorrect. False reassurance does not assess safety.","C":"Incorrect. The statement requires immediate assessment.","D":"Incorrect. Assessing the client comes first."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', 'Suicide risk', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_310013', 'SATA', 'Which nurse statements are examples of therapeutic communication techniques? Select all that apply.', 'Active listening, exploring, and clarifying are therapeutic; false reassurance, ''why'' questions, and advice-giving are barriers.', '{"options":[{"id":"A","text":"\"Go on, I''m listening.\""},{"id":"B","text":"\"You mentioned feeling alone. Tell me more.\""},{"id":"C","text":"\"Let me make sure I understand what you''re saying.\""},{"id":"D","text":"\"Don''t worry, everything will be fine.\""},{"id":"E","text":"\"Why did you do that?\""},{"id":"F","text":"\"You should just focus on the positive.\""}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_310014', 'SATA', 'Which findings would the nurse expect to assess in a client with major depression? Select all that apply.', 'Anhedonia, worthlessness, sleep/appetite changes, and fatigue are classic depression findings; grandiosity and hyperactivity suggest mania.', '{"options":[{"id":"A","text":"Loss of interest in usual activities"},{"id":"B","text":"Feelings of worthlessness"},{"id":"C","text":"Changes in sleep and appetite"},{"id":"D","text":"Fatigue and low energy"},{"id":"E","text":"Grandiose thinking"},{"id":"F","text":"Increased goal-directed activity"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', 'Assessment', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_310015', 'SATA', 'Which nursing actions promote a therapeutic milieu on a psychiatric unit? Select all that apply.', 'A therapeutic milieu relies on structure, consistent rules, safety, and social engagement.', '{"options":[{"id":"A","text":"Establish clear and consistent unit rules"},{"id":"B","text":"Encourage client participation in group activities"},{"id":"C","text":"Maintain a safe, structured environment"},{"id":"D","text":"Allow clients to keep sharp personal items"},{"id":"E","text":"Ignore conflicts between clients"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic milieu', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_310016', 'SATA', 'Which findings should raise the nurse''s suspicion of possible elder abuse? Select all that apply.', 'Unexplained injuries, neglect, controlling caregivers, and fearfulness are warning signs of abuse.', '{"options":[{"id":"A","text":"Unexplained bruising in various stages of healing"},{"id":"B","text":"Poor hygiene and signs of neglect"},{"id":"C","text":"Caregiver answers all questions for the client"},{"id":"D","text":"Fear or anxiety when the caregiver is present"},{"id":"E","text":"Client independently manages own finances"},{"id":"F","text":"Client has a well-nourished appearance"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Warning signs', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_310017', 'SATA', 'Which interventions are appropriate for a client experiencing moderate anxiety? Select all that apply.', 'Deep breathing, simple communication, and a calm presence help reduce moderate anxiety.', '{"options":[{"id":"A","text":"Encourage slow, deep breathing"},{"id":"B","text":"Speak in short, simple sentences"},{"id":"C","text":"Remain calm and stay with the client"},{"id":"D","text":"Present multiple complex options to consider"},{"id":"E","text":"Leave the client alone to reduce stimulation"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', 'Interventions', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_310018', 'SELECT_N', 'Which 3 actions should the nurse take to reduce the risk of violence when caring for a potentially aggressive client?', 'Maintaining escape routes, staying calm, and removing potential weapons reduce violence risk.', '{"options":[{"id":"A","text":"Maintain a safe distance and clear exit path"},{"id":"B","text":"Speak in a calm, non-threatening manner"},{"id":"C","text":"Remove objects that could be used as weapons"},{"id":"D","text":"Corner the client to limit movement"},{"id":"E","text":"Argue with the client to correct misperceptions"},{"id":"F","text":"Approach quickly to establish control"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Violence potential', 'Safety precautions', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_310019', 'TF', 'Asking a client directly about suicidal thoughts does not increase the risk that the client will attempt suicide.', 'Direct questioning about suicide does not plant the idea; it opens the door to help and assessment.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_310020', 'TF', 'Offering false reassurance, such as "Everything will be fine," is an effective therapeutic communication technique.', 'False reassurance is a communication barrier that dismisses the client''s concerns.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_310021', 'MATRIX', 'For each nurse statement, indicate whether it is a therapeutic or non-therapeutic communication technique.', 'Exploring and reflecting feelings are therapeutic; judging and ''why'' questions are barriers.', '{"row_label":"Statement","rows":[{"id":"r1","text":"\"Tell me more about that.\""},{"id":"r2","text":"\"You shouldn''t feel that way.\""},{"id":"r3","text":"\"It sounds like you''re feeling scared.\""},{"id":"r4","text":"\"Why didn''t you take your medication?\""}],"columns":[{"id":"c1","text":"Therapeutic"},{"id":"c2","text":"Non-therapeutic"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Easy', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_310022', 'MATRIX_MR', 'For each disorder, select all the associated features (a disorder may have more than one).', 'Mania features elevated mood, depression features low mood, and schizophrenia features hallucinations.', '{"row_label":"Disorder","rows":[{"id":"r1","text":"Bipolar disorder, manic episode"},{"id":"r2","text":"Major depression"},{"id":"r3","text":"Schizophrenia"}],"columns":[{"id":"c1","text":"Elevated/expansive mood"},{"id":"c2","text":"Depressed mood"},{"id":"c3","text":"Hallucinations"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"]},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Mental illness symptoms', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_310023', 'CLOZE', 'A client crying over a recent loss is best supported when the nurse {1} and offers {2}.', 'Silent presence and non-judgmental support are therapeutic responses to grief.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"sits quietly and stays present"},{"id":"c2","text":"changes the subject"},{"id":"c3","text":"leaves the room"}]},{"id":"b2","choices":[{"id":"c1","text":"a caring, non-judgmental presence"},{"id":"c2","text":"advice to move on quickly"},{"id":"c3","text":"false reassurance"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_310024', 'HIGHLIGHT', 'Highlight the statements that indicate increased suicide risk. The client says, [[I have been giving away my belongings]]. He reports [[I feel like a burden to everyone]]. He states [[I am looking forward to my grandchild''s birthday]]. He mentions [[I have written a note to my family]]. He notes [[I slept well last night]].', 'Giving away belongings, feeling like a burden, and leaving a note are suicide warning signs.', '{"chunks":[{"id":"h1","text":"I have been giving away my belongings"},{"id":"h2","text":"I feel like a burden to everyone"},{"id":"h3","text":"I am looking forward to my grandchild''s birthday"},{"id":"h4","text":"I have written a note to my family"},{"id":"h5","text":"I slept well last night"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"Giving away possessions is a warning sign.","h2":"Feeling like a burden is a warning sign.","h3":"Future-oriented plans suggest lower risk.","h4":"Writing a note can indicate suicidal planning.","h5":"This is not a warning sign."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', 'Warning signs', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_310025', 'BOWTIE', 'A client with depression expresses suicidal ideation with a plan. Complete the diagram by selecting the priority concern, actions to take, and parameters to monitor.', 'Active suicidal ideation with a plan requires close observation, a safe environment, and monitoring of mood and self-harm cues.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Initiate one-to-one continuous observation"},{"id":"lt2","text":"Remove potentially harmful objects"},{"id":"lt3","text":"Allow the client unsupervised time alone"},{"id":"lt4","text":"Discharge the client home"}]},"centre":{"label":"Priority concern","tokens":[{"id":"ct1","text":"Risk for suicide"},{"id":"ct2","text":"Risk for infection"},{"id":"ct3","text":"Risk for constipation"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Mood and affect"},{"id":"rt2","text":"Statements about self-harm"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Wound drainage"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', NULL, 'Easy', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_310026', 'DRAG_CLOZE', 'When a client is at the [1] level of anxiety, the nurse should stay with the client and use [2] communication.', 'At panic-level anxiety, the nurse remains present and communicates in a simple, calm manner.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"panic"},{"id":"t2","text":"simple and calm"},{"id":"t3","text":"complex and detailed"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_310027', 'DRAG_ORDER', 'An agitated client begins to escalate. Place the nurse''s de-escalation actions in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Ensure personal and client safety with a clear exit"},{"id":"t2","text":"Approach calmly and use a quiet, non-threatening voice"},{"id":"t3","text":"Acknowledge the client''s feelings and listen"},{"id":"t4","text":"Set clear, simple limits on unsafe behavior"},{"id":"t5","text":"Offer options to help the client regain control"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317001', 'MCQ', 'A nurse reviews the pulse oximetry reading of a stable adult client and obtains an SpO2 of 88% on room air. Which action should the nurse take FIRST?', 'An SpO2 below 90% indicates hypoxemia and the priority is to correct oxygenation with supplemental oxygen.', '{"options":[{"id":"A","text":"Apply supplemental oxygen as prescribed"},{"id":"B","text":"Document the reading and continue monitoring"},{"id":"C","text":"Encourage the client to increase oral fluids"},{"id":"D","text":"Reposition the client to the left side"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An SpO2 of 88% is below the target range and needs oxygen.","B":"Incorrect. A reading of 88% requires intervention, not just documentation.","C":"Incorrect. Fluids do not correct hypoxemia.","D":"Incorrect. Positioning alone will not raise a low SpO2."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Vital-sign monitoring', 'Pulse oximetry', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317002', 'MCQ', 'A nurse reviews morning labs. Which serum potassium value is within the normal reference range for an adult?', 'The normal serum potassium range for adults is 3.5-5.0 mEq/L.', '{"options":[{"id":"A","text":"4.0 mEq/L"},{"id":"B","text":"2.8 mEq/L"},{"id":"C","text":"6.2 mEq/L"},{"id":"D","text":"1.9 mEq/L"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Normal potassium is 3.5-5.0 mEq/L.","B":"Incorrect. This value is low (hypokalemia).","C":"Incorrect. This value is high (hyperkalemia).","D":"Incorrect. This is critically low."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Potassium', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317003', 'MCQ', 'A nurse cares for a client with an indwelling urinary catheter. Which action best reduces the risk of a catheter-associated urinary tract infection?', 'Keeping the drainage bag below bladder level maintains gravity flow and prevents reflux, reducing CAUTI risk.', '{"options":[{"id":"A","text":"Keep the drainage bag below the level of the bladder"},{"id":"B","text":"Disconnect the tubing to obtain samples"},{"id":"C","text":"Place the drainage bag on the bed beside the client"},{"id":"D","text":"Irrigate the catheter every shift routinely"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This promotes gravity drainage and prevents urine backflow.","B":"Incorrect. Breaking a closed system increases infection risk.","C":"Incorrect. This allows backflow of urine.","D":"Incorrect. Routine irrigation is not recommended and raises infection risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter care', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317004', 'MCQ', 'A nurse verifies correct placement of a newly inserted nasogastric tube before use. Which method is the most reliable confirmation of placement?', 'Radiographic confirmation is the most reliable method to verify NG tube placement before initial use.', '{"options":[{"id":"A","text":"Obtain a radiographic (X-ray) confirmation"},{"id":"B","text":"Auscultate air injected into the stomach"},{"id":"C","text":"Ask the client if the tube feels comfortable"},{"id":"D","text":"Observe for condensation in the tube"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. X-ray is the gold standard for confirming NG tube placement.","B":"Incorrect. The air-bolus method is unreliable.","C":"Incorrect. Comfort does not confirm placement.","D":"Incorrect. This does not confirm gastric placement."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube management', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317005', 'MCQ', 'A nurse applies sequential compression devices (SCDs) to a postoperative client. What is the primary purpose of this intervention?', 'SCDs enhance venous return from the legs, reducing the risk of deep vein thrombosis and VTE.', '{"options":[{"id":"A","text":"Prevent venous thromboembolism"},{"id":"B","text":"Reduce surgical wound pain"},{"id":"C","text":"Improve arterial circulation to the feet"},{"id":"D","text":"Prevent pressure injuries on the heels"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. SCDs promote venous return and reduce clot formation.","B":"Incorrect. SCDs do not manage pain.","C":"Incorrect. SCDs address venous, not arterial, flow.","D":"Incorrect. That is not their purpose."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Venous-return devices', 'SCDs', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317006', 'MCQ', 'A nurse assesses a peripheral IV site and finds it cool, swollen, and pale with a slowed infusion. Which complication is most likely?', 'A cool, swollen, pale IV site with slowed flow indicates fluid leaking into tissue — infiltration.', '{"options":[{"id":"A","text":"Infiltration"},{"id":"B","text":"Phlebitis"},{"id":"C","text":"Systemic infection"},{"id":"D","text":"Air embolism"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Coolness, swelling, and pallor indicate infiltration.","B":"Incorrect. Phlebitis presents with warmth, redness, and a palpable cord.","C":"Incorrect. These are localized signs.","D":"Incorrect. Air embolism causes respiratory distress, not local swelling."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Cardiovascular', 'Peripheral IV monitoring', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317007', 'MCQ', 'A nurse prepares a client for surgery scheduled in the morning. Which preoperative instruction is most important to reduce the risk of aspiration?', 'Maintaining NPO status before surgery keeps the stomach empty and reduces the risk of aspiration during anesthesia.', '{"options":[{"id":"A","text":"Remain NPO after midnight as prescribed"},{"id":"B","text":"Take all home medications with a full glass of water"},{"id":"C","text":"Eat a light breakfast the morning of surgery"},{"id":"D","text":"Drink clear juice up until surgery"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. NPO status reduces the risk of aspiration under anesthesia.","B":"Incorrect. This should be verified against NPO orders.","C":"Incorrect. Eating violates NPO and raises aspiration risk.","D":"Incorrect. Oral intake should stop per NPO orders."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Preoperative care', 'NPO status', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317008', 'MCQ', 'Following a femoral cardiac catheterization, which nursing assessment is the priority to detect a complication?', 'After femoral catheterization, monitoring the site for bleeding and checking distal pulses detects hemorrhage and arterial occlusion.', '{"options":[{"id":"A","text":"Check the insertion site and distal pulses"},{"id":"B","text":"Assess the client''s appetite"},{"id":"C","text":"Measure the client''s height"},{"id":"D","text":"Ask about family medical history"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Bleeding and impaired circulation are key post-procedure risks.","B":"Incorrect. This is not a priority post-procedure.","C":"Incorrect. Not relevant to complication detection.","D":"Incorrect. Not a priority assessment now."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Cardiac catheterization', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317009', 'MCQ', 'A nurse teaches a client scheduled for a colonoscopy. Which statement by the client indicates correct understanding of the bowel preparation?', 'Completing the full bowel preparation clears stool so the colon can be adequately visualized during colonoscopy.', '{"options":[{"id":"A","text":"I will drink the entire prep solution to clear my bowel"},{"id":"B","text":"I can eat a steak dinner the night before"},{"id":"C","text":"I should stop drinking fluids 24 hours before"},{"id":"D","text":"I only need to take half the prep if I feel full"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Completing the prep ensures adequate visualization.","B":"Incorrect. A clear liquid diet is required before the procedure.","C":"Incorrect. Clear fluids are encouraged during prep.","D":"Incorrect. The full prep is needed for adequate cleansing."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Diagnostic-test education', 'Colonoscopy prep', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317010', 'MCQ', 'A nurse monitors a client during moderate (conscious) sedation. Which parameter is most important to monitor continuously?', 'Respiratory depression is the primary risk of moderate sedation, so airway, breathing, and SpO2 are monitored continuously.', '{"options":[{"id":"A","text":"Respiratory status and oxygen saturation"},{"id":"B","text":"24-hour urine output"},{"id":"C","text":"Bowel sounds"},{"id":"D","text":"Skin turgor"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Respiratory depression is the main risk of sedation.","B":"Incorrect. Not the priority during the procedure.","C":"Incorrect. Not a sedation priority.","D":"Incorrect. Not the priority during sedation."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Moderate sedation', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_317011', 'MCQ', 'A nurse obtains a capillary blood glucose sample. Which action promotes an accurate point-of-care result?', 'Wiping the first drop and testing the second gives a more accurate point-of-care glucose reading.', '{"options":[{"id":"A","text":"Wipe away the first drop of blood and use the second"},{"id":"B","text":"Squeeze the fingertip firmly to force out blood"},{"id":"C","text":"Use an expired test strip if available"},{"id":"D","text":"Puncture the center pad of the fingertip"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The first drop may be diluted and gives a less accurate reading.","B":"Incorrect. Excessive squeezing dilutes the sample with tissue fluid.","C":"Incorrect. Expired strips give inaccurate results.","D":"Incorrect. The side of the fingertip is preferred and less painful."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Blood/specimen collection', 'Blood glucose', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_317012', 'TF', 'Using an incentive spirometer as taught helps a postoperative client reduce the risk of atelectasis and pneumonia.', 'Incentive spirometry promotes deep lung expansion, preventing alveolar collapse (atelectasis) and postoperative pneumonia.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Postoperative complication prevention', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_317013', 'SATA', 'A nurse reviews a client''s vital signs. Which findings should the nurse recognize as abnormal and requiring follow-up? Select all that apply.', 'Severe hypertension, tachycardia, and bradypnea are abnormal and require follow-up; the other values are within normal limits.', '{"options":[{"id":"A","text":"Blood pressure 190/104 mmHg"},{"id":"B","text":"Heart rate 128 beats/min"},{"id":"C","text":"Respiratory rate 8 breaths/min"},{"id":"D","text":"Temperature 37.0°C (98.6°F)"},{"id":"E","text":"SpO2 98% on room air"},{"id":"F","text":"Heart rate 76 beats/min"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Vital-sign trend recognition', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_317014', 'SATA', 'A nurse assesses a peripheral IV site for signs of phlebitis. Which findings support this complication? Select all that apply.', 'Phlebitis produces redness, warmth, tenderness, and a palpable venous cord; coolness and pallor instead suggest infiltration.', '{"options":[{"id":"A","text":"Redness along the vein"},{"id":"B","text":"Warmth at the site"},{"id":"C","text":"A palpable cord along the vein"},{"id":"D","text":"Coolness and pallor at the site"},{"id":"E","text":"Brisk capillary refill in the hand"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Cardiovascular', 'Peripheral IV complications', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_317015', 'SATA', 'A nurse plans care to prevent postoperative complications. Which interventions are appropriate? Select all that apply.', 'Early ambulation, deep breathing, and antiembolism stockings reduce the risk of VTE and respiratory complications.', '{"options":[{"id":"A","text":"Encourage early ambulation"},{"id":"B","text":"Promote deep breathing and coughing"},{"id":"C","text":"Apply antiembolism stockings as prescribed"},{"id":"D","text":"Keep the client on strict bed rest for one week"},{"id":"E","text":"Withhold all pain medication"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Postoperative complication prevention', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_317016', 'SATA', 'A nurse reviews laboratory results. Which values are within normal adult reference ranges? Select all that apply.', 'Sodium 140, hemoglobin 14, and WBC 7,500 are normal; the potassium is high and platelets are critically low.', '{"options":[{"id":"A","text":"Sodium 140 mEq/L"},{"id":"B","text":"Hemoglobin 14 g/dL"},{"id":"C","text":"White blood cells 7,500/mm3"},{"id":"D","text":"Serum potassium 6.5 mEq/L"},{"id":"E","text":"Platelets 40,000/mm3"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_317017', 'SATA', 'A nurse cares for a client with a nasogastric tube to suction. Which actions promote safe management? Select all that apply.', 'Verifying placement, elevating the head of the bed, and oral care reduce aspiration and skin breakdown risks.', '{"options":[{"id":"A","text":"Verify placement before administering anything"},{"id":"B","text":"Keep the head of the bed elevated"},{"id":"C","text":"Provide frequent oral and nasal care"},{"id":"D","text":"Lay the client flat during feedings"},{"id":"E","text":"Irrigate with the tube disconnected from suction indefinitely"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube safety', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_317018', 'SELECT_N', 'A nurse performs a focused neurovascular assessment on an extremity after a cast application. Which 3 findings should the nurse assess?', 'Neurovascular checks after casting assess circulation (pulse, capillary refill) and nerve function (sensation, movement) to detect compartment syndrome.', '{"options":[{"id":"A","text":"Distal pulse"},{"id":"B","text":"Capillary refill"},{"id":"C","text":"Sensation and movement of toes"},{"id":"D","text":"Bowel sounds"},{"id":"E","text":"Deep tendon reflexes of the opposite arm"},{"id":"F","text":"Pupillary response"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Focused assessment', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_317019', 'MATRIX', 'For each adult vital sign, click to specify whether it is within normal limits or abnormal.', 'Normal adult values: HR 60-100, RR 12-20, temp ~37°C, BP <120/80, SpO2 >=95%.', '{"row_label":"Vital sign","rows":[{"id":"r1","text":"Heart rate 80 beats/min"},{"id":"r2","text":"Respiratory rate 30 breaths/min"},{"id":"r3","text":"Temperature 39.5°C (103.1°F)"},{"id":"r4","text":"Blood pressure 118/76 mmHg"},{"id":"r5","text":"SpO2 85% on room air"}],"columns":[{"id":"c1","text":"Normal"},{"id":"c2","text":"Abnormal"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Multisystem', 'Vital-sign interpretation', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_317020', 'MATRIX_MR', 'For each peripheral IV complication, select all assessment findings that apply.', 'Phlebitis is warm and red; infiltration is cool and swollen; a site infection shows redness, warmth, and swelling.', '{"row_label":"Complication","rows":[{"id":"r1","text":"Phlebitis"},{"id":"r2","text":"Infiltration"},{"id":"r3","text":"Local site infection"}],"columns":[{"id":"c1","text":"Redness/Warmth"},{"id":"c2","text":"Swelling"},{"id":"c3","text":"Coolness"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2","c3"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Cardiovascular', 'IV site complications', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_317021', 'CLOZE', 'A postoperative client has an SpO2 of 87% and shallow breathing. The nurse recognizes this as {1} and should first {2}.', 'A low SpO2 with shallow breathing indicates hypoxemia; oxygen and deep breathing improve oxygenation.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hypoxemia"},{"id":"c2","text":"hyperventilation"},{"id":"c3","text":"hypertension"}]},{"id":"b2","choices":[{"id":"c1","text":"apply oxygen and encourage deep breathing"},{"id":"c2","text":"restrict the client''s fluids"},{"id":"c3","text":"place the client flat"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Postoperative monitoring', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_317022', 'HIGHLIGHT', 'Highlight the assessment findings that require immediate follow-up. The client is resting. Temperature [[37.1°C]]. Blood pressure [[88/54]]. Heart rate [[124]]. Respiratory rate [[16]]. SpO2 [[84% on room air]].', 'Hypotension, tachycardia, and low SpO2 are abnormal and require follow-up; the temperature and respiratory rate are normal.', '{"chunks":[{"id":"h1","text":"37.1°C"},{"id":"h2","text":"88/54"},{"id":"h3","text":"124"},{"id":"h4","text":"16"},{"id":"h5","text":"84% on room air"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Normal temperature — no follow-up needed.","h2":"Hypotension — needs follow-up.","h3":"Tachycardia — needs follow-up.","h4":"Normal respiratory rate.","h5":"Significant hypoxemia — urgent."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Trend recognition', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_317023', 'BOWTIE', 'A peripheral IV site is cool, swollen, and pale. Complete the diagram by selecting the complication, actions to take, and parameters to monitor.', 'Infiltration is managed by stopping the infusion and removing the catheter, while monitoring the limb for swelling and skin changes.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the infusion"},{"id":"lt2","text":"Remove the IV catheter"},{"id":"lt3","text":"Increase the infusion rate"},{"id":"lt4","text":"Apply firm continuous pressure to speed flow"}]},"centre":{"label":"Complication","tokens":[{"id":"ct1","text":"Infiltration"},{"id":"ct2","text":"Phlebitis"},{"id":"ct3","text":"Air embolism"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Swelling of the affected limb"},{"id":"rt2","text":"Skin color and temperature at the site"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Pupil size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Cardiovascular', 'IV infiltration', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_317024', 'DRAG_ORDER', 'A nurse prepares to collect a venous blood specimen. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"},{"id":"s6","target_text":"6th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and apply gloves"},{"id":"t2","text":"Verify the client''s identity using two identifiers"},{"id":"t3","text":"Apply the tourniquet and select the vein"},{"id":"t4","text":"Insert the needle and collect the sample"},{"id":"t5","text":"Remove the tourniquet and apply pressure to the site"},{"id":"t6","text":"Label the tube at the bedside"}]}'::jsonb, '{"slots":{"s1":"t2","s2":"t1","s3":"t3","s4":"t4","s5":"t5","s6":"t6"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Hematologic', 'Blood/specimen collection', NULL, 'Easy', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318001', 'MCQ', 'A nurse is monitoring a client for orthostatic hypotension. Which instruction should the nurse give the client before standing?', 'Changing position slowly allows the cardiovascular system to compensate and prevents falls.', '{"options":[{"id":"A","text":"Rise slowly and sit at the edge of the bed first"},{"id":"B","text":"Hold your breath while standing up"},{"id":"C","text":"Stand up quickly to get it over with"},{"id":"D","text":"Cross your legs before standing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Gradual position change reduces the risk of a sudden blood-pressure drop.","B":"Incorrect. Breath-holding can worsen dizziness.","C":"Incorrect. Rapid change triggers the pressure drop.","D":"Incorrect. This does not prevent orthostatic changes."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Vital-sign trends', 'Orthostatic hypotension', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318002', 'MCQ', 'A nurse applies sequential compression devices (SCDs) to a postoperative client. What is the primary purpose of these devices?', 'SCDs enhance venous return in the legs to prevent venous thromboembolism after surgery.', '{"options":[{"id":"A","text":"Prevent deep vein thrombosis"},{"id":"B","text":"Reduce surgical wound pain"},{"id":"C","text":"Lower blood pressure"},{"id":"D","text":"Prevent pressure injuries on the heels"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. SCDs promote venous return and reduce clot risk.","B":"Incorrect. SCDs do not manage pain.","C":"Incorrect. That is not their purpose.","D":"Incorrect. SCDs target venous stasis, not skin."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Venous-return devices', 'Sequential compression devices', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318003', 'MCQ', 'To reduce the risk of a catheter-associated urinary tract infection, where should the nurse keep the drainage bag?', 'Keeping the bag below the bladder prevents reflux of urine and reduces infection risk.', '{"options":[{"id":"A","text":"Below the level of the bladder"},{"id":"B","text":"At the same level as the bladder"},{"id":"C","text":"Hooked to the upper side rail"},{"id":"D","text":"Resting on the floor"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This promotes drainage and prevents backflow.","B":"Incorrect. This can impede drainage.","C":"Incorrect. This allows urine to flow back toward the bladder.","D":"Incorrect. Contact with the floor is a contamination risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Urinary catheter', 'Infection prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318004', 'MCQ', 'A client on warfarin has an INR of 5.8. How should the nurse interpret this value?', 'A therapeutic INR is typically 2–3; 5.8 reflects over-anticoagulation and bleeding risk.', '{"options":[{"id":"A","text":"The client is at increased risk for bleeding"},{"id":"B","text":"The client needs a higher warfarin dose"},{"id":"C","text":"The value is within the normal therapeutic range"},{"id":"D","text":"The client is at risk for clotting"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An INR this high indicates excessive anticoagulation.","B":"Incorrect. The dose is already too high.","C":"Incorrect. Therapeutic range is usually 2–3.","D":"Incorrect. High INR means thin blood, not clotting."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'INR', 'Easy', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318005', 'MCQ', 'Before administering a feeding through a nasogastric tube, which is the most reliable bedside method to verify tube placement?', 'Aspirate pH testing (and X-ray) are reliable; the auscultation method is no longer recommended.', '{"options":[{"id":"A","text":"Check the pH of aspirated gastric contents"},{"id":"B","text":"Auscultate air injected into the tube"},{"id":"C","text":"Ask the client if they feel the tube"},{"id":"D","text":"Place the tube tip in water and watch for bubbles"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A low (acidic) pH supports gastric placement.","B":"Incorrect. The air-bolus method is unreliable.","C":"Incorrect. Sensation does not confirm placement.","D":"Incorrect. This is unsafe and inaccurate."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG/GI tube', 'Placement verification', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318006', 'MCQ', 'A nurse notes cool, pale, swollen tissue around a peripheral IV site with a sluggish infusion. Which complication is most likely?', 'Coolness, pallor, and edema at the site are classic signs of IV infiltration.', '{"options":[{"id":"A","text":"Infiltration"},{"id":"B","text":"Phlebitis"},{"id":"C","text":"Air embolism"},{"id":"D","text":"Speed shock"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cool, swollen, pale tissue indicates fluid leaking into tissue.","B":"Incorrect. Phlebitis presents with warmth, redness, and a palpable cord.","C":"Incorrect. That causes respiratory distress, not local swelling.","D":"Incorrect. That is a systemic reaction to rapid infusion."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Infiltration', 'Easy', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318007', 'MCQ', 'Which device should the nurse teach a postoperative client to use to prevent atelectasis?', 'Incentive spirometry promotes deep inhalation and alveolar expansion, preventing atelectasis.', '{"options":[{"id":"A","text":"Incentive spirometer"},{"id":"B","text":"Peak flow meter"},{"id":"C","text":"Pulse oximeter"},{"id":"D","text":"Nebulizer"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. It encourages deep breathing and lung expansion.","B":"Incorrect. That measures asthma airflow, not prevents atelectasis.","C":"Incorrect. It monitors saturation but does not expand lungs.","D":"Incorrect. It delivers medication, not lung expansion exercises."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre/post-operative care', 'Atelectasis prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318008', 'MCQ', 'A client''s point-of-care blood glucose reads 54 mg/dL and the client is alert. What should the nurse do first?', 'An alert hypoglycemic client is treated with 15 g of fast-acting carbohydrate, then rechecked.', '{"options":[{"id":"A","text":"Give 15 g of a fast-acting carbohydrate"},{"id":"B","text":"Administer IV dextrose 50%"},{"id":"C","text":"Hold all further monitoring"},{"id":"D","text":"Give the client a high-protein snack"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The rule of 15 treats mild hypoglycemia in an alert client.","B":"Incorrect. IV dextrose is for clients who cannot swallow.","C":"Incorrect. Recheck is required.","D":"Incorrect. Protein does not raise glucose quickly."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Point-of-care testing', 'Blood glucose', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318009', 'MCQ', 'Before applying ECG electrodes, what should the nurse do to obtain the clearest tracing?', 'Clean, dry skin ensures good electrode contact and reduces artifact on the ECG tracing.', '{"options":[{"id":"A","text":"Clean and dry the skin at the electrode sites"},{"id":"B","text":"Apply lotion to the electrode sites"},{"id":"C","text":"Place electrodes directly over bony prominences"},{"id":"D","text":"Have the client hold their breath during the tracing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Clean, dry skin improves electrode contact and signal quality.","B":"Incorrect. Lotion interferes with adhesion and conduction.","C":"Incorrect. Bone causes artifact; use flat, fleshy areas.","D":"Incorrect. This is unnecessary for a routine ECG."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'ECG monitoring', 'Electrode placement', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318010', 'MCQ', 'During moderate (conscious) sedation for a procedure, which parameter is most important for the nurse to monitor continuously?', 'Respiratory depression is the chief hazard of moderate sedation, so oxygenation is monitored continuously.', '{"options":[{"id":"A","text":"Oxygen saturation and respiratory status"},{"id":"B","text":"Bowel sounds"},{"id":"C","text":"Deep tendon reflexes"},{"id":"D","text":"Skin turgor"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Respiratory depression is the primary risk of sedation.","B":"Incorrect. Not a sedation priority.","C":"Incorrect. Not a sedation monitoring priority.","D":"Incorrect. Not relevant to sedation safety."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Moderate sedation', 'Monitoring', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_318011', 'MCQ', 'To reduce the risk of aspiration during a PEG tube feeding, how should the nurse position the client?', 'Keeping the head of bed elevated during and after feeding reduces reflux and aspiration.', '{"options":[{"id":"A","text":"Head of bed elevated at least 30 degrees"},{"id":"B","text":"Flat and supine"},{"id":"C","text":"In the left lateral position"},{"id":"D","text":"In the Trendelenburg position"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevation reduces reflux and aspiration risk.","B":"Incorrect. Lying flat increases aspiration risk.","C":"Incorrect. Semi-Fowler''s is preferred for feeding.","D":"Incorrect. This increases reflux."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Percutaneous feeding tube', 'Aspiration prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_318012', 'SATA', 'Which findings in a postoperative client should the nurse recognize as warning signs that require follow-up? Select all that apply.', 'Fever, oliguria, and distension signal possible complications; normal BP, mild pain, and good perfusion do not.', '{"options":[{"id":"A","text":"Temperature of 38.9°C"},{"id":"B","text":"Urine output of 10 mL/hr"},{"id":"C","text":"Increasing abdominal distension"},{"id":"D","text":"Blood pressure of 118/74 mmHg"},{"id":"E","text":"Pain rated 2 out of 10"},{"id":"F","text":"Warm, dry skin with capillary refill under 2 seconds"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Focused assessment', 'Post-op complications', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_318013', 'SATA', 'Which signs at a peripheral IV site indicate phlebitis? Select all that apply.', 'Phlebitis produces redness, warmth, tenderness, and a palpable venous cord; coolness suggests infiltration instead.', '{"options":[{"id":"A","text":"Redness along the vein"},{"id":"B","text":"Warmth at the site"},{"id":"C","text":"A palpable cord along the vein"},{"id":"D","text":"Cool, pale skin at the site"},{"id":"E","text":"Absence of any tenderness"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Phlebitis', 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_318014', 'SATA', 'Which actions reduce the risk of error when collecting a blood specimen? Select all that apply.', 'Two-identifier verification, bedside labeling, and correct tube selection prevent specimen and patient errors.', '{"options":[{"id":"A","text":"Verify the client''s identity using two identifiers"},{"id":"B","text":"Label the tubes at the bedside"},{"id":"C","text":"Use the correct tubes for the ordered tests"},{"id":"D","text":"Label the tubes later at the nurses'' station"},{"id":"E","text":"Use one identifier to save time"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Multisystem', 'Blood/specimen collection', 'Venipuncture safety', 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_318015', 'SATA', 'Which topics should the nurse include in preoperative teaching to reduce postoperative complications? Select all that apply.', 'Spirometry, splinted coughing, early ambulation, and leg exercises prevent respiratory and thromboembolic complications.', '{"options":[{"id":"A","text":"How to use the incentive spirometer"},{"id":"B","text":"How to splint the incision when coughing"},{"id":"C","text":"The importance of early ambulation"},{"id":"D","text":"How to perform leg exercises in bed"},{"id":"E","text":"To remain flat and immobile for 48 hours"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre-operative care', 'Client teaching', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_318016', 'SATA', 'Which laboratory results should the nurse recognize as increasing a client''s risk for bleeding? Select all that apply.', 'Low platelets and a high INR both increase bleeding risk; the normal values do not.', '{"options":[{"id":"A","text":"Platelet count of 40,000/mm3"},{"id":"B","text":"INR of 6.0"},{"id":"C","text":"Hemoglobin of 14 g/dL"},{"id":"D","text":"Platelet count of 250,000/mm3"},{"id":"E","text":"INR of 1.0"}]}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Bleeding risk', 'Easy', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_318017', 'SELECT_N', 'A client''s serum potassium is 6.5 mEq/L. Which 2 findings should the nurse most closely monitor for?', 'Hyperkalemia causes cardiac dysrhythmias and muscle weakness, which require close monitoring.', '{"options":[{"id":"A","text":"Cardiac dysrhythmias"},{"id":"B","text":"Muscle weakness"},{"id":"C","text":"Constipation"},{"id":"D","text":"Increased urine output"},{"id":"E","text":"Hypertension"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Potassium', 'Easy', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_318018', 'TF', 'After a femoral cardiac catheterization, the nurse should assess the pulses distal to the insertion site to detect impaired circulation.', 'Checking distal pulses monitors for arterial occlusion or bleeding at the catheter site.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Post-cardiac catheterization', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_318019', 'MATRIX', 'For each laboratory value, click to specify whether it is within the normal range or abnormal.', 'Normal sodium and WBC contrast with dangerously high potassium and low hemoglobin.', '{"row_label":"Value","rows":[{"id":"r1","text":"Sodium 140 mEq/L"},{"id":"r2","text":"Potassium 6.8 mEq/L"},{"id":"r3","text":"Hemoglobin 6.5 g/dL"},{"id":"r4","text":"White blood cells 8,000/mm3"}],"columns":[{"id":"c1","text":"Normal"},{"id":"c2","text":"Abnormal"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c2","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Lab-value interpretation', 'Normal vs abnormal', 'Easy', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_318020', 'MATRIX_MR', 'For each device, select all complications it helps prevent (may apply to more than one).', 'Each preventive measure targets a specific complication of immobility or feeding.', '{"row_label":"Device","rows":[{"id":"r1","text":"Sequential compression devices"},{"id":"r2","text":"Head-of-bed elevation during feeding"},{"id":"r3","text":"Repositioning every 2 hours"},{"id":"r4","text":"Antiembolism stockings"}],"columns":[{"id":"c1","text":"Deep vein thrombosis"},{"id":"c2","text":"Aspiration"},{"id":"c3","text":"Pressure injury"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Multisystem', 'Complication prevention', 'Device purpose', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_318021', 'CLOZE', 'A client''s oxygen saturation drops to 88 percent. The nurse recognizes this as {1} and should first {2}.', 'An SpO2 of 88 percent indicates hypoxemia, requiring repositioning and supplemental oxygen.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hypoxemia"},{"id":"c2","text":"a normal value"},{"id":"c3","text":"hypercapnia"}]},{"id":"b2","choices":[{"id":"c1","text":"reposition and apply oxygen"},{"id":"c2","text":"document and continue"},{"id":"c3","text":"lower the head of the bed"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Vital-sign trends', 'Oxygenation', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_318022', 'HIGHLIGHT', 'Highlight the vital signs that require follow-up. Temperature [[37.0°C]]. Heart rate [[126 bpm]]. Blood pressure [[118/76]]. Respiratory rate [[8 breaths/min]]. SpO2 [[89% on room air]].', 'Tachycardia, bradypnea, and low oxygen saturation are abnormal; temperature and BP are normal.', '{"chunks":[{"id":"h1","text":"37.0°C"},{"id":"h2","text":"126 bpm"},{"id":"h3","text":"118/76"},{"id":"h4","text":"8 breaths/min"},{"id":"h5","text":"89% on room air"}]}'::jsonb, '{"correct_ids":["h2","h4","h5"],"feedback":{"h1":"Normal temperature — no follow-up needed.","h2":"Tachycardia — needs follow-up.","h3":"Normal blood pressure — no follow-up needed.","h4":"Bradypnea — needs follow-up.","h5":"Hypoxemia — needs follow-up."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Trend recognition', 'Abnormal vital signs', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_318023', 'BOWTIE', 'Complete the diagram by selecting the complication, actions to take, and parameters to monitor.', 'Infiltration is managed by stopping the infusion and removing the catheter while monitoring the site.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the infusion"},{"id":"lt2","text":"Remove the IV catheter"},{"id":"lt3","text":"Increase the infusion rate"},{"id":"lt4","text":"Apply heat and continue infusing"}]},"centre":{"label":"Complication","tokens":[{"id":"ct1","text":"IV infiltration"},{"id":"ct2","text":"Air embolism"},{"id":"ct3","text":"Systemic infection"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Site swelling"},{"id":"rt2","text":"Skin temperature at the site"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupil size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Complication prevention', 'IV infiltration', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_318024', 'DRAG_ORDER', 'Place the steps for obtaining a clean-catch midstream urine specimen in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene"},{"id":"t2","text":"Cleanse the perineal area"},{"id":"t3","text":"Begin voiding into the toilet"},{"id":"t4","text":"Collect the midstream urine in the sterile container"},{"id":"t5","text":"Label and send the specimen to the lab"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Blood/specimen collection', 'Midstream urine', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319001', 'MCQ', 'A nurse is checking orthostatic vital signs. After the client stands, which change in blood pressure indicates orthostatic hypotension?', 'Orthostatic hypotension is a systolic drop of 20 mmHg or a diastolic drop of 10 mmHg within 3 minutes of standing.', '{"options":[{"id":"A","text":"A drop in systolic pressure of at least 20 mmHg"},{"id":"B","text":"A rise in systolic pressure of 20 mmHg"},{"id":"C","text":"No change in blood pressure"},{"id":"D","text":"A drop in systolic pressure of 5 mmHg"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A systolic fall of 20 mmHg or more on standing defines orthostatic hypotension.","B":"Incorrect. A rise is not orthostatic hypotension.","C":"Incorrect. A normal response shows little change.","D":"Incorrect. A 5 mmHg drop is within normal limits."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Vital-sign trends', 'Orthostatic hypotension', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319002', 'MCQ', 'A nurse needs to verify placement of a newly inserted nasogastric tube before use. Which method is the most reliable confirmation?', 'An X-ray is the most reliable method to confirm initial NG tube placement.', '{"options":[{"id":"A","text":"X-ray of the chest and abdomen"},{"id":"B","text":"Auscultating air injected into the tube"},{"id":"C","text":"Placing the tube end in water to check for bubbles"},{"id":"D","text":"Asking the client if they feel the tube"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Radiographic confirmation is the gold standard for initial placement.","B":"Incorrect. The air-bolus method is unreliable.","C":"Incorrect. This is unsafe and unreliable.","D":"Incorrect. Client sensation does not confirm placement."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube', 'Placement verification', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319003', 'MCQ', 'To prevent a catheter-associated urinary tract infection, where should the nurse keep the urinary drainage bag?', 'The drainage bag stays below bladder level to keep urine flowing away and prevent reflux.', '{"options":[{"id":"A","text":"Below the level of the bladder"},{"id":"B","text":"Above the level of the bladder"},{"id":"C","text":"On the client''s abdomen"},{"id":"D","text":"Attached to the side rail"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Keeping the bag below the bladder prevents backflow of urine.","B":"Incorrect. This causes reflux and infection risk.","C":"Incorrect. This is above bladder level.","D":"Incorrect. Side rails raise and lower, risking backflow."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter', 'CAUTI prevention', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319004', 'MCQ', 'A nurse reviews a client''s laboratory results. Which serum potassium value is within the normal reference range?', 'Normal serum potassium is 3.5 to 5.0 mEq/L; 4.0 mEq/L is normal.', '{"options":[{"id":"A","text":"4.0 mEq/L"},{"id":"B","text":"2.8 mEq/L"},{"id":"C","text":"6.2 mEq/L"},{"id":"D","text":"1.5 mEq/L"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Normal potassium is 3.5 to 5.0 mEq/L.","B":"Incorrect. This is hypokalemia.","C":"Incorrect. This is hyperkalemia.","D":"Incorrect. This is critically low."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Potassium', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319005', 'MCQ', 'A nurse is applying antiembolism stockings to a postoperative client. When is the best time to apply them?', 'Stockings are applied before rising when the legs are least edematous, maximizing venous return.', '{"options":[{"id":"A","text":"In the morning before the client gets out of bed"},{"id":"B","text":"After the client has been walking for an hour"},{"id":"C","text":"After a warm bath in the evening"},{"id":"D","text":"Only at bedtime"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Applying before rising, while veins are not engorged, is most effective.","B":"Incorrect. Legs are already engorged after activity.","C":"Incorrect. Warmth and dependent position engorge the legs.","D":"Incorrect. They should be worn continuously and applied before rising."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Venous-return devices', 'Antiembolism stockings', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319006', 'MCQ', 'A nurse notes cool, pale, swollen skin around a peripheral IV site with no blood return. Which complication is most likely?', 'Infiltration presents with a cool, pale, edematous site and absent blood return.', '{"options":[{"id":"A","text":"Infiltration"},{"id":"B","text":"Phlebitis"},{"id":"C","text":"Air embolism"},{"id":"D","text":"Speed shock"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Coolness, swelling, and pallor indicate fluid leaking into tissue.","B":"Incorrect. Phlebitis causes warmth, redness, and a palpable cord.","C":"Incorrect. Air embolism causes respiratory distress, not local swelling.","D":"Incorrect. Speed shock is a systemic reaction to rapid infusion."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Infiltration', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319007', 'MCQ', 'A nurse teaches a preoperative client about the incentive spirometer. What is the main purpose of this device after surgery?', 'The incentive spirometer encourages deep sustained inhalation to prevent atelectasis and pneumonia.', '{"options":[{"id":"A","text":"To promote deep breathing and prevent atelectasis"},{"id":"B","text":"To measure blood oxygen saturation"},{"id":"C","text":"To deliver aerosolized medication"},{"id":"D","text":"To suction airway secretions"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. It expands the alveoli and prevents postoperative lung collapse.","B":"Incorrect. That is a pulse oximeter.","C":"Incorrect. That is a nebulizer.","D":"Incorrect. Suctioning is a separate procedure."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre-operative care', 'Incentive spirometry', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319008', 'MCQ', 'After a cardiac catheterization via the femoral artery, which assessment is the priority for the affected leg?', 'Monitoring distal pulses, color, and temperature detects bleeding or arterial compromise early.', '{"options":[{"id":"A","text":"Check pedal pulses, color, and temperature distal to the site"},{"id":"B","text":"Encourage the client to bend the leg frequently"},{"id":"C","text":"Apply heat to the insertion site"},{"id":"D","text":"Ambulate the client immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Distal circulation must be monitored for arterial occlusion or bleeding.","B":"Incorrect. The leg is kept straight to prevent bleeding.","C":"Incorrect. Heat increases bleeding risk.","D":"Incorrect. Bed rest is required after the procedure."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Cardiac catheterization', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319009', 'MCQ', 'A client is receiving moderate (conscious) sedation for a procedure. Which parameter is most important for the nurse to monitor continuously?', 'Respiratory depression is the primary hazard of moderate sedation, so airway and oxygenation are monitored closely.', '{"options":[{"id":"A","text":"Oxygen saturation and respiratory status"},{"id":"B","text":"Bowel sounds"},{"id":"C","text":"Deep tendon reflexes"},{"id":"D","text":"Pupil size only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Respiratory depression is the greatest risk during moderate sedation.","B":"Incorrect. Bowel sounds are not the priority during sedation.","C":"Incorrect. Reflexes are not the sedation priority.","D":"Incorrect. Airway and breathing take precedence."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Moderate sedation', 'Monitoring', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319010', 'MCQ', 'A nurse is preparing to obtain a capillary blood glucose sample by fingerstick. Which action is correct?', 'The side of the fingertip is punctured for less pain and adequate flow; the first drop is discarded.', '{"options":[{"id":"A","text":"Puncture the side of the fingertip"},{"id":"B","text":"Puncture the center pad of the fingertip"},{"id":"C","text":"Squeeze the finger tightly to force blood out"},{"id":"D","text":"Use the first drop of blood for the reading"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The side of the fingertip has fewer nerve endings and good blood flow.","B":"Incorrect. The center is more painful and highly innervated.","C":"Incorrect. Excessive squeezing dilutes the sample with tissue fluid.","D":"Incorrect. The first drop is wiped away as it may be contaminated."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Blood/specimen collection', 'Blood glucose', 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_319011', 'MCQ', 'A nurse is preparing to obtain a 12-lead ECG. What should the nurse do to ensure a clear tracing?', 'A clean, dry skin surface and a still client minimize artifact and produce a clear ECG tracing.', '{"options":[{"id":"A","text":"Ensure the client lies still and the skin is clean and dry"},{"id":"B","text":"Have the client walk during the recording"},{"id":"C","text":"Apply electrodes over thick chest hair without prepping"},{"id":"D","text":"Ask the client to breathe deeply and rapidly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Movement and poor electrode contact cause artifact.","B":"Incorrect. Movement produces artifact.","C":"Incorrect. Poor contact causes a poor tracing.","D":"Incorrect. This causes baseline wander."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'ECG monitoring', 'Lead placement', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_319012', 'SATA', 'A nurse plans care to prevent postoperative complications for a client after abdominal surgery. Which interventions are appropriate? Select all that apply.', 'Early ambulation, breathing exercises, SCDs, and incision splinting reduce respiratory and venous complications.', '{"options":[{"id":"A","text":"Encourage early ambulation as tolerated"},{"id":"B","text":"Teach coughing and deep breathing"},{"id":"C","text":"Apply sequential compression devices"},{"id":"D","text":"Keep the client on strict bed rest for one week"},{"id":"E","text":"Withhold all fluids until discharge"},{"id":"F","text":"Splint the incision when coughing"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Post-operative care', 'Complication prevention', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_319013', 'SATA', 'A nurse assesses a peripheral IV site for phlebitis. Which findings suggest phlebitis? Select all that apply.', 'Phlebitis presents with redness, warmth, tenderness, and a palpable venous cord.', '{"options":[{"id":"A","text":"Redness along the vein"},{"id":"B","text":"Warmth at the site"},{"id":"C","text":"A palpable cord along the vein"},{"id":"D","text":"Cool, pale skin at the site"},{"id":"E","text":"Tenderness at the site"},{"id":"F","text":"Absent blood return with brisk capillary refill"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Phlebitis', 'Easy', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_319014', 'SATA', 'A nurse cares for a client receiving continuous feeding through a percutaneous gastrostomy tube. Which actions reduce the risk of aspiration? Select all that apply.', 'Elevating the head of the bed, checking residuals, verifying placement, and flushing reduce aspiration risk.', '{"options":[{"id":"A","text":"Keep the head of the bed elevated at least 30 degrees"},{"id":"B","text":"Check gastric residual volume per protocol"},{"id":"C","text":"Lay the client flat during the feeding"},{"id":"D","text":"Verify tube placement before feeding"},{"id":"E","text":"Flush the tube with the ordered water"},{"id":"F","text":"Increase the feeding rate to finish quickly"}]}'::jsonb, '{"answers":["A","B","D","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Percutaneous feeding tube', 'Aspiration prevention', 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_319015', 'SATA', 'A nurse reviews morning labs. Which values are outside the normal reference range? Select all that apply.', 'Elevated glucose, hypernatremia, and elevated creatinine are abnormal; the hemoglobin and potassium are normal.', '{"options":[{"id":"A","text":"Fasting blood glucose 210 mg/dL"},{"id":"B","text":"Sodium 158 mEq/L"},{"id":"C","text":"Hemoglobin 14 g/dL"},{"id":"D","text":"Serum creatinine 3.2 mg/dL"},{"id":"E","text":"Potassium 4.1 mEq/L"}]}'::jsonb, '{"answers":["A","B","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Lab-value interpretation', 'Hyperglycemia', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_319016', 'SATA', 'A nurse performs a neurovascular assessment on a client with a newly casted arm. Which components should the nurse assess? Select all that apply.', 'Neurovascular checks assess the five Ps: color, capillary refill, movement, sensation, and pulse/temperature distal to the cast.', '{"options":[{"id":"A","text":"Capillary refill of the fingers"},{"id":"B","text":"Color of the distal fingers"},{"id":"C","text":"Movement of the fingers"},{"id":"D","text":"Sensation in the fingers"},{"id":"E","text":"The client''s dietary preferences"},{"id":"F","text":"Distal pulse and temperature"}]}'::jsonb, '{"answers":["A","B","C","D","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological', 'Focused assessment', 'Neurovascular checks', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_319017', 'SELECT_N', 'A nurse reviews a set of adult vital signs. Which 2 values are outside the normal range and require follow-up?', 'A respiratory rate of 30 and an SpO2 of 88% are abnormal; the remaining values are within normal limits.', '{"options":[{"id":"A","text":"Respiratory rate 30 breaths/min"},{"id":"B","text":"Oxygen saturation 88% on room air"},{"id":"C","text":"Heart rate 78 bpm"},{"id":"D","text":"Temperature 37.0°C"},{"id":"E","text":"Blood pressure 118/76 mmHg"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Vital-sign trends', 'Abnormal values', 'Easy', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_319018', 'TF', 'After a bronchoscopy, the nurse should keep the client NPO until the gag reflex returns.', 'Local anesthetic suppresses the gag reflex, so the client remains NPO to prevent aspiration until it returns.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Diagnostic-test monitoring', 'Bronchoscopy', 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_319019', 'MATRIX', 'For each adult laboratory value, click to indicate whether it is within the normal range or abnormal.', 'Sodium and platelets are normal; leukocytosis, a high INR, and a low hemoglobin are abnormal.', '{"row_label":"Laboratory value","rows":[{"id":"r1","text":"Sodium 140 mEq/L"},{"id":"r2","text":"White blood cells 18,000/mm3"},{"id":"r3","text":"Platelets 250,000/mm3"},{"id":"r4","text":"INR 5.5"},{"id":"r5","text":"Hemoglobin 7 g/dL"}],"columns":[{"id":"c1","text":"Normal"},{"id":"c2","text":"Abnormal"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Normal vs abnormal', 'Easy', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_319020', 'MATRIX_MR', 'For each device, select all complications it is intended to help prevent (may support more than one).', 'SCDs and stockings prevent DVT, head elevation prevents aspiration, and a pressure-redistributing mattress prevents pressure injury.', '{"row_label":"Device","rows":[{"id":"r1","text":"Sequential compression device"},{"id":"r2","text":"Elevated head of bed during feeding"},{"id":"r3","text":"Alternating-pressure mattress"},{"id":"r4","text":"Antiembolism stockings"}],"columns":[{"id":"c1","text":"Aspiration"},{"id":"c2","text":"Deep vein thrombosis"},{"id":"c3","text":"Pressure injury"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1"],"r3":["c3"],"r4":["c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Multisystem', 'Injury/complication prevention', 'Device purpose', 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_319021', 'CLOZE', 'A client has a nasogastric tube set to low intermittent suction. To keep the airway clear and prevent aspiration, the nurse positions the client with the head of the bed {1}, and confirms tube patency by {2} the tube per protocol.', 'An elevated head of bed reduces aspiration risk, and flushing maintains NG tube patency.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"elevated"},{"id":"c2","text":"flat"},{"id":"c3","text":"in Trendelenburg"}]},{"id":"b2","choices":[{"id":"c1","text":"flushing"},{"id":"c2","text":"clamping"},{"id":"c3","text":"removing"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube', 'Suction', 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_319022', 'HIGHLIGHT', 'The nurse reviews postoperative findings four hours after surgery. Highlight the findings that require immediate follow-up. Temperature [[37.1°C]]. Heart rate [[126 bpm]]. Blood pressure [[88/54 mmHg]]. Pain rated [[3 of 10]]. Wound dressing shows [[increasing bright red drainage]].', 'Tachycardia, hypotension, and increasing bright red drainage together suggest postoperative hemorrhage.', '{"chunks":[{"id":"h1","text":"37.1°C"},{"id":"h2","text":"126 bpm"},{"id":"h3","text":"88/54 mmHg"},{"id":"h4","text":"3 of 10"},{"id":"h5","text":"increasing bright red drainage"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Normal temperature — no follow-up needed.","h2":"Tachycardia can signal bleeding or hypovolemia.","h3":"Hypotension is concerning postoperatively.","h4":"Mild pain is expected and controlled.","h5":"Active bleeding requires urgent follow-up."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Post-operative care', 'Trend recognition', 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_319023', 'BOWTIE', 'A client''s peripheral IV site is swollen, cool, and pale with no blood return. Complete the diagram by selecting the actions to take, the complication, and the parameters to monitor.', 'Infiltration is managed by stopping the infusion and removing the catheter, then monitoring swelling and distal circulation.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the infusion"},{"id":"lt2","text":"Remove the IV catheter"},{"id":"lt3","text":"Increase the infusion rate"},{"id":"lt4","text":"Apply firm massage over the site"}]},"centre":{"label":"Complication","tokens":[{"id":"ct1","text":"Infiltration"},{"id":"ct2","text":"Air embolism"},{"id":"ct3","text":"Systemic infection"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Site swelling"},{"id":"rt2","text":"Distal circulation"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Pupil size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Infiltration', 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_319024', 'DRAG_ORDER', 'A nurse is collecting a venous blood specimen by venipuncture. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"},{"id":"s6","target_text":"6th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and apply gloves"},{"id":"t2","text":"Apply the tourniquet and select a vein"},{"id":"t3","text":"Cleanse the site with antiseptic"},{"id":"t4","text":"Insert the needle and collect the sample"},{"id":"t5","text":"Release the tourniquet and remove the needle"},{"id":"t6","text":"Apply pressure and label the tubes"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5","s6":"t6"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Cardiovascular', 'Blood/specimen collection', 'Venipuncture', 'Easy', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304001', 'MCQ', 'A nurse''s hands are visibly soiled with blood after removing gloves. Which action is most appropriate for hand hygiene?', 'When hands are visibly soiled, soap and water is required; alcohol rub is only for non-soiled hands.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Use an alcohol-based hand rub"},{"id":"C","text":"Wipe hands on a clean towel"},{"id":"D","text":"Apply a second pair of gloves"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Visibly soiled hands require soap and water, not alcohol rub.","B":"Incorrect. Alcohol rub is not adequate when hands are visibly soiled.","C":"Incorrect. Wiping does not remove pathogens.","D":"Incorrect. Gloving over soiled hands does not clean them."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304002', 'MCQ', 'A client is admitted with active pulmonary tuberculosis. Which type of precaution should the nurse implement?', 'Pulmonary TB requires airborne precautions with a negative-pressure room and N95 respirator.', '{"options":[{"id":"A","text":"Airborne precautions"},{"id":"B","text":"Contact precautions"},{"id":"C","text":"Droplet precautions"},{"id":"D","text":"Standard precautions only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TB spreads via airborne droplet nuclei.","B":"Incorrect. Contact precautions apply to direct-contact organisms.","C":"Incorrect. TB requires airborne, not droplet, precautions.","D":"Incorrect. TB requires additional airborne precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304003', 'MCQ', 'When donning personal protective equipment before entering an isolation room, which item should the nurse put on first?', 'The correct donning sequence is gown, mask, goggles, then gloves.', '{"options":[{"id":"A","text":"Gown"},{"id":"B","text":"Gloves"},{"id":"C","text":"Goggles"},{"id":"D","text":"Mask"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The gown is donned first, then mask, goggles, and gloves.","B":"Incorrect. Gloves are donned last.","C":"Incorrect. Goggles come after the gown and mask.","D":"Incorrect. The mask comes after the gown."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304004', 'MCQ', 'Before administering a medication, which method should the nurse use to verify client identity?', 'Two unique identifiers (name plus date of birth) must be verified before medication administration.', '{"options":[{"id":"A","text":"Check two identifiers such as name and date of birth"},{"id":"B","text":"Confirm the room number"},{"id":"C","text":"Ask the client if they are ready for medication"},{"id":"D","text":"Verify the bed tag"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers are the standard for safe identification.","B":"Incorrect. Room number is not a reliable identifier.","C":"Incorrect. This does not verify identity.","D":"Incorrect. Bed tags can be outdated."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304005', 'MCQ', 'When preparing to lift a heavy object from the floor, which body mechanic should the nurse use?', 'Bending the knees and using leg muscles while keeping the back straight prevents musculoskeletal injury.', '{"options":[{"id":"A","text":"Bend at the knees and keep the back straight"},{"id":"B","text":"Bend at the waist and keep the legs straight"},{"id":"C","text":"Twist the torso while lifting"},{"id":"D","text":"Hold the object away from the body"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Using the legs protects the back from injury.","B":"Incorrect. This strains the lower back.","C":"Incorrect. Twisting increases injury risk.","D":"Incorrect. Objects should be held close to the body."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Safe handling and ergonomics', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304006', 'MCQ', 'A nurse realizes a medication was given to the wrong client but the client shows no harm. What should the nurse do first?', 'The nurse assesses the client for effects and completes an incident report to promote system safety.', '{"options":[{"id":"A","text":"Assess the client and complete an incident report"},{"id":"B","text":"Say nothing since no harm occurred"},{"id":"C","text":"Ask a coworker to document it later"},{"id":"D","text":"Discard the medication record"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Assess safety first, then report the near-miss.","B":"Incorrect. All errors must be reported.","C":"Incorrect. The nurse involved is responsible for reporting.","D":"Incorrect. Records must never be altered or destroyed."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Error and near-miss reporting', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304007', 'MCQ', 'While setting up a sterile field, the nurse reaches across the field with an ungloved hand. What should the nurse do?', 'Reaching over a sterile field contaminates it; the setup must be discarded and restarted.', '{"options":[{"id":"A","text":"Consider the field contaminated and set up a new one"},{"id":"B","text":"Continue since the hand did not touch anything"},{"id":"C","text":"Cover the field with a sterile towel"},{"id":"D","text":"Spray the field with antiseptic"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reaching across a sterile field contaminates it.","B":"Incorrect. The field is contaminated regardless of touch.","C":"Incorrect. Covering does not restore sterility.","D":"Incorrect. A contaminated field must be replaced."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Sterile technique', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304008', 'MCQ', 'A person in scrubs without a hospital badge asks to take a newborn from the nursery for tests. What should the nurse do?', 'Infant abduction prevention requires verifying identification and authorization of anyone transporting a newborn.', '{"options":[{"id":"A","text":"Verify the person''s identity and authorization before releasing the infant"},{"id":"B","text":"Release the infant since the person wears scrubs"},{"id":"C","text":"Ask the mother to hand over the infant"},{"id":"D","text":"Allow it if the person knows the infant''s name"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Newborn security requires verifying identity and authorization.","B":"Incorrect. Scrubs do not confirm authorization.","C":"Incorrect. This bypasses security verification.","D":"Incorrect. Knowing a name is not sufficient."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive', 'Newborn security', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304009', 'MCQ', 'After administering an intramuscular injection, where should the nurse dispose of the used needle?', 'Used needles are disposed of uncapped in a puncture-resistant sharps container.', '{"options":[{"id":"A","text":"In a puncture-resistant sharps container"},{"id":"B","text":"In the regular trash bin"},{"id":"C","text":"In the red biohazard bag"},{"id":"D","text":"Recapped and placed in a drawer"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sharps go in a designated puncture-proof container.","B":"Incorrect. This risks needlestick injury.","C":"Incorrect. Bags are for soft waste, not sharps.","D":"Incorrect. Recapping increases injury risk."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Biohazard handling', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304010', 'MCQ', 'Which intervention best reduces fall risk for a hospitalized older adult?', 'Keeping the call light reachable and the bed low are core fall-prevention measures.', '{"options":[{"id":"A","text":"Keep the call light within reach and bed in the lowest position"},{"id":"B","text":"Keep all four side rails raised at all times"},{"id":"C","text":"Dim the room lighting fully at all times"},{"id":"D","text":"Place the bed in the highest position"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Accessibility and a low bed reduce falls.","B":"Incorrect. Four raised rails are a restraint and a climb hazard.","C":"Incorrect. Poor lighting increases fall risk.","D":"Incorrect. A high bed increases fall injury risk."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Fall prevention', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304011', 'MCQ', 'Before administering a new antibiotic, which action is most important for the nurse to take?', 'Assessing for allergies before administering a new medication prevents anaphylaxis and adverse reactions.', '{"options":[{"id":"A","text":"Ask the client about medication allergies"},{"id":"B","text":"Check the client''s favorite foods"},{"id":"C","text":"Confirm the client''s insurance"},{"id":"D","text":"Ask when the client last ate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Allergy assessment prevents dangerous reactions.","B":"Incorrect. This is unrelated to drug safety.","C":"Incorrect. Insurance is not a safety priority here.","D":"Incorrect. Not the priority for antibiotic safety."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_304012', 'MCQ', 'During a home visit for an older adult at risk for falls, which finding should the nurse address first?', 'Loose throw rugs are a common tripping hazard and should be removed or secured to prevent falls.', '{"options":[{"id":"A","text":"Loose throw rugs on the floor"},{"id":"B","text":"A calendar on the wall"},{"id":"C","text":"A television in the living room"},{"id":"D","text":"Family photographs on a shelf"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Loose rugs are a leading trip hazard.","B":"Incorrect. Not a safety hazard.","C":"Incorrect. Not a fall hazard.","D":"Incorrect. Not a safety concern."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home safety assessment', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_304013', 'TF', 'Standard precautions should be used with every client regardless of their diagnosis or presumed infection status.', 'Standard precautions apply to all clients because any client may harbor a transmissible pathogen.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_304014', 'TF', 'A physical restraint may be applied to a confused client at the nurse''s discretion without a provider order.', 'Restraints require a provider order and are used only as a last resort after less restrictive measures fail.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Restraints', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_304015', 'SATA', 'A client is on contact precautions for Clostridioides difficile. Which actions should the nurse take? Select all that apply.', 'C. difficile requires soap-and-water hand hygiene, gloves, gown, and dedicated equipment; spores resist alcohol rub.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Wear gloves when entering the room"},{"id":"C","text":"Wear a gown for client contact"},{"id":"D","text":"Use dedicated equipment for the client"},{"id":"E","text":"Place the client in a negative-pressure room"},{"id":"F","text":"Clean hands with alcohol-based rub only"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Contact precautions', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_304016', 'SATA', 'Which interventions help prevent falls for a hospitalized client? Select all that apply.', 'Low bed, reachable call light, nonslip footwear, and clear pathways reduce falls; four rails and darkness increase risk.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position"},{"id":"B","text":"Ensure the call light is within reach"},{"id":"C","text":"Provide nonslip footwear"},{"id":"D","text":"Keep the pathway to the bathroom clear"},{"id":"E","text":"Raise all four side rails at all times"},{"id":"F","text":"Keep the room dark to promote rest"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Fall prevention', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_304017', 'SATA', 'At which moments should the nurse perform hand hygiene? Select all that apply.', 'Hand hygiene is performed before client contact, before aseptic tasks, after body-fluid exposure, and after glove removal.', '{"options":[{"id":"A","text":"Before touching a client"},{"id":"B","text":"After removing gloves"},{"id":"C","text":"After contact with body fluids"},{"id":"D","text":"Before an aseptic procedure"},{"id":"E","text":"Only at the start of the shift"},{"id":"F","text":"Only when hands look dirty"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_304018', 'SATA', 'A small fire starts in a client''s trash can. Which immediate actions are appropriate? Select all that apply.', 'RACE guides fire response: Rescue, Alarm, Contain, Extinguish; elevators and open windows are avoided.', '{"options":[{"id":"A","text":"Rescue clients in immediate danger"},{"id":"B","text":"Activate the fire alarm"},{"id":"C","text":"Contain the fire by closing doors"},{"id":"D","text":"Use the elevator to evacuate"},{"id":"E","text":"Open windows to release smoke"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Fire safety (RACE)', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_304019', 'SATA', 'Which statements about safely removing PPE are correct? Select all that apply.', 'Gloves come off first, the mask is removed last by its ties without touching the front, and hands are washed afterward.', '{"options":[{"id":"A","text":"Gloves are removed first"},{"id":"B","text":"Perform hand hygiene after removal"},{"id":"C","text":"Remove the mask last, by the ties"},{"id":"D","text":"Touch the outer front of the mask to remove it"},{"id":"E","text":"Reuse the gown for the next client"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE removal', NULL, 'Easy', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_304020', 'SELECT_N', 'A client has influenza requiring droplet precautions. Select the 2 actions the nurse should take.', 'Droplet precautions require a surgical mask within close range and masking the client during transport.', '{"options":[{"id":"A","text":"Wear a surgical mask when within 6 feet of the client"},{"id":"B","text":"Place a surgical mask on the client during transport"},{"id":"C","text":"Use a negative-pressure isolation room"},{"id":"D","text":"Wear an N95 respirator for all care"},{"id":"E","text":"No mask is needed for routine care"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Respiratory', 'Droplet precautions', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_304021', 'MATRIX', 'For each client condition, click to specify the correct type of transmission-based precaution.', 'TB and measles are airborne, influenza is droplet, and MRSA requires contact precautions.', '{"row_label":"Client","rows":[{"id":"r1","text":"Active pulmonary tuberculosis"},{"id":"r2","text":"Influenza"},{"id":"r3","text":"MRSA wound infection"},{"id":"r4","text":"Measles (rubeola)"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_304022', 'MATRIX_MR', 'For each precaution type, select all PPE items the nurse should routinely wear on entering the room.', 'Contact precautions require gloves and gown; airborne requires an N95; anticipated blood contact requires gloves and gown.', '{"row_label":"Precaution","rows":[{"id":"r1","text":"Contact precautions"},{"id":"r2","text":"Airborne precautions"},{"id":"r3","text":"Standard precautions when contact with blood is likely"}],"columns":[{"id":"c1","text":"Gloves"},{"id":"c2","text":"Gown"},{"id":"c3","text":"N95 respirator"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE by precaution type', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_304023', 'CLOZE', 'A client with active tuberculosis requires {1} precautions and should be placed in a {2} room.', 'TB requires airborne precautions with a negative-pressure isolation room to contain droplet nuclei.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"airborne"},{"id":"c2","text":"droplet"},{"id":"c3","text":"contact"}]},{"id":"b2","choices":[{"id":"c1","text":"negative-pressure"},{"id":"c2","text":"positive-pressure"},{"id":"c3","text":"standard"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Isolation precautions', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_304024', 'HIGHLIGHT', 'During a home visit, highlight the findings that are safety hazards for an older adult at risk for falls. The home has [[loose throw rugs]] in the hallway, [[poor lighting on the stairs]], [[grab bars in the bathroom]], [[clutter on the floor]], and a [[working smoke detector]].', 'Loose rugs, poor stair lighting, and floor clutter are fall hazards; grab bars and a smoke detector are protective.', '{"chunks":[{"id":"h1","text":"loose throw rugs"},{"id":"h2","text":"poor lighting on the stairs"},{"id":"h3","text":"clutter on the floor"},{"id":"h4","text":"grab bars in the bathroom"},{"id":"h5","text":"working smoke detector"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"Trip hazard.","h2":"Increases fall risk.","h3":"Obstacle and trip hazard.","h4":"Protective, not a hazard.","h5":"Protective, not a hazard."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Home safety assessment', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_304025', 'BOWTIE', 'A client is admitted with suspected active tuberculosis. Complete the diagram by selecting the condition, actions to take, and equipment needed.', 'Suspected TB requires airborne precautions with an N95 respirator and a negative-pressure isolation room.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Place client in a negative-pressure room"},{"id":"lt2","text":"Don an N95 respirator before entry"},{"id":"lt3","text":"Keep the door open for airflow"},{"id":"lt4","text":"Use a surgical mask for all care"}]},"centre":{"label":"Required precaution","tokens":[{"id":"ct1","text":"Airborne precautions"},{"id":"ct2","text":"Contact precautions"},{"id":"ct3","text":"Standard precautions only"}]},"right":{"label":"Equipment needed","tokens":[{"id":"rt1","text":"N95 respirator"},{"id":"rt2","text":"Negative-pressure isolation room"},{"id":"rt3","text":"Sterile gloves"},{"id":"rt4","text":"Positive-pressure room"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Airborne isolation', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_304026', 'DRAG_ORDER', 'Place the steps for donning personal protective equipment before entering an isolation room in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene"},{"id":"t2","text":"Put on the gown"},{"id":"t3","text":"Put on the mask"},{"id":"t4","text":"Put on goggles"},{"id":"t5","text":"Put on gloves"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Donning PPE', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305001', 'MCQ', 'A nurse''s hands are visibly soiled after removing a soiled dressing. Which method of hand hygiene should the nurse use?', 'Soap and water are required when hands are visibly soiled; alcohol rub is only for hands that are not soiled.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Use an alcohol-based hand rub"},{"id":"C","text":"Wipe hands on a clean towel"},{"id":"D","text":"Apply new gloves without cleaning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Visibly soiled hands must be washed with soap and water.","B":"Incorrect. Alcohol rub is not effective on visibly soiled hands.","C":"Incorrect. This does not remove pathogens.","D":"Incorrect. Hands must be cleaned first."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305002', 'MCQ', 'A client is admitted with active pulmonary tuberculosis. Which type of isolation precaution should the nurse implement?', 'Tuberculosis is transmitted by airborne nuclei, requiring a negative-pressure room and an N95 respirator.', '{"options":[{"id":"A","text":"Airborne precautions"},{"id":"B","text":"Contact precautions"},{"id":"C","text":"Droplet precautions"},{"id":"D","text":"Standard precautions only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TB is spread by airborne droplet nuclei.","B":"Incorrect. Contact precautions are for direct-contact organisms.","C":"Incorrect. TB requires airborne, not droplet, precautions.","D":"Incorrect. TB requires additional airborne precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305003', 'MCQ', 'When donning personal protective equipment before entering an isolation room, which item does the nurse put on FIRST?', 'The correct donning sequence is gown, mask, goggles, then gloves.', '{"options":[{"id":"A","text":"Gown"},{"id":"B","text":"Gloves"},{"id":"C","text":"Goggles"},{"id":"D","text":"Mask"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The gown is donned first, followed by mask, goggles, then gloves.","B":"Incorrect. Gloves are donned last.","C":"Incorrect. Goggles come after the mask.","D":"Incorrect. The mask is donned after the gown."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305004', 'MCQ', 'Before administering a medication, which action best confirms the correct client identity?', 'Two independent identifiers, such as name and date of birth, are required before care.', '{"options":[{"id":"A","text":"Check two identifiers such as name and date of birth"},{"id":"B","text":"Ask the client to confirm their room number"},{"id":"C","text":"Call the client''s first name and wait for a response"},{"id":"D","text":"Verify with the client in the next bed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers are the standard for client identification.","B":"Incorrect. Room number is not an approved identifier.","C":"Incorrect. A single name is not sufficient.","D":"Incorrect. This is not a reliable identifier."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305005', 'MCQ', 'A client has diarrhea caused by Clostridioides difficile. Which precaution is most important to prevent transmission?', 'C. difficile requires contact precautions; alcohol rubs do not kill spores, so soap and water are used.', '{"options":[{"id":"A","text":"Contact precautions with soap-and-water hand washing"},{"id":"B","text":"Airborne precautions with an N95 respirator"},{"id":"C","text":"Alcohol-based hand rub after each contact"},{"id":"D","text":"Droplet precautions with a surgical mask"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. C. difficile spores require contact precautions and soap-and-water washing.","B":"Incorrect. C. difficile is not airborne.","C":"Incorrect. Alcohol does not kill C. difficile spores.","D":"Incorrect. Droplet precautions are not indicated."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'GI', 'Transmission-based precautions', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305006', 'MCQ', 'A nurse prepares to transfer a heavy, dependent client from bed to a chair. Which action promotes safe handling?', 'Mechanical lifts and proper body mechanics prevent musculoskeletal injury during transfers.', '{"options":[{"id":"A","text":"Use a mechanical lift with assistance"},{"id":"B","text":"Bend at the waist and lift the client alone"},{"id":"C","text":"Twist the trunk while pivoting the client"},{"id":"D","text":"Keep the feet together for balance"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A mechanical lift protects both the client and the nurse.","B":"Incorrect. Bending at the waist risks back injury.","C":"Incorrect. Twisting increases injury risk.","D":"Incorrect. A wide base of support is safer."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Ergonomics and safe handling', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305007', 'MCQ', 'A nurse discovers that a medication was given at the wrong time but the client was not harmed. What should the nurse do first?', 'Nurses assess the client and report errors and near-misses to support system safety improvement.', '{"options":[{"id":"A","text":"Assess the client and complete an incident report"},{"id":"B","text":"Ignore the error because no harm occurred"},{"id":"C","text":"Document the error only in the client''s chart as a near-miss"},{"id":"D","text":"Wait to see if the client develops symptoms"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Assess the client, then document through the incident-reporting system.","B":"Incorrect. All errors must be reported.","C":"Incorrect. Incident reports are separate from the chart.","D":"Incorrect. Reporting should not be delayed."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Error and near-miss reporting', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305008', 'MCQ', 'After administering an intramuscular injection, where should the nurse dispose of the used needle?', 'Used sharps must be discarded immediately in a puncture-resistant sharps container without recapping.', '{"options":[{"id":"A","text":"In a puncture-resistant sharps container"},{"id":"B","text":"In the regular trash can"},{"id":"C","text":"In a red biohazard bag"},{"id":"D","text":"Recap it and place it in the medication drawer"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sharps must go in a rigid puncture-resistant container.","B":"Incorrect. Sharps are a biohazard.","C":"Incorrect. Bags are not puncture-resistant.","D":"Incorrect. Recapping risks needlestick injury."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Biohazard handling', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305009', 'MCQ', 'A nurse on the postpartum unit is preparing to hand a newborn to a staff member. Which action best ensures newborn security?', 'Verifying authorized hospital identification is a core newborn-abduction prevention measure.', '{"options":[{"id":"A","text":"Verify the staff member''s identification badge before transferring the infant"},{"id":"B","text":"Hand the newborn to anyone in scrubs"},{"id":"C","text":"Leave the newborn in the hallway bassinet briefly"},{"id":"D","text":"Ask the mother to identify the staff member"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Confirming authorized ID prevents infant abduction.","B":"Incorrect. Scrubs do not confirm authorization.","C":"Incorrect. Newborns are never left unattended.","D":"Incorrect. Staff must be verified by ID badge."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive', 'Newborn security', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305010', 'MCQ', 'During a fire in a client care area, the nurse recalls the RACE acronym. What does the R stand for?', 'In RACE, R = Rescue, A = Alarm, C = Confine, E = Extinguish/Evacuate.', '{"options":[{"id":"A","text":"Rescue clients in immediate danger"},{"id":"B","text":"Report the incident to administration"},{"id":"C","text":"Return to the nurses'' station"},{"id":"D","text":"Remove all electrical equipment"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. R stands for Rescue.","B":"Incorrect. Reporting is not the R step.","C":"Incorrect. This is not part of RACE.","D":"Incorrect. This is not the R step."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Fire safety', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305011', 'MCQ', 'Before administering a new antibiotic, the nurse should perform which action to reduce the risk of a reaction?', 'Assessing allergy history before administration is essential to prevent hypersensitivity reactions.', '{"options":[{"id":"A","text":"Ask the client about medication allergies"},{"id":"B","text":"Administer the full dose slowly"},{"id":"C","text":"Give an antihistamine with every dose"},{"id":"D","text":"Document the dose after administration"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Allergy assessment must precede administration.","B":"Incorrect. Allergy status must be checked first.","C":"Incorrect. This is not routine and does not replace allergy assessment.","D":"Incorrect. This does not prevent a reaction."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_305012', 'MCQ', 'A home-health nurse assesses fall risk for an older adult. Which finding most requires intervention?', 'Loose throw rugs are a common home tripping hazard that should be removed or secured.', '{"options":[{"id":"A","text":"Loose throw rugs on the floor"},{"id":"B","text":"A night-light in the hallway"},{"id":"C","text":"Grab bars installed in the shower"},{"id":"D","text":"A cordless phone within reach"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Loose rugs are a major tripping hazard.","B":"Incorrect. A night-light reduces fall risk.","C":"Incorrect. Grab bars improve safety.","D":"Incorrect. This improves safety and access."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home safety assessment', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_305013', 'SATA', 'Which actions are components of standard precautions used with every client? Select all that apply.', 'Standard precautions include hand hygiene, gloves for body-fluid contact, safe sharps disposal, and respiratory hygiene for all clients.', '{"options":[{"id":"A","text":"Perform hand hygiene before and after client contact"},{"id":"B","text":"Wear gloves when contact with body fluids is anticipated"},{"id":"C","text":"Dispose of sharps in a puncture-resistant container"},{"id":"D","text":"Place all clients in a negative-pressure room"},{"id":"E","text":"Require an N95 respirator for every client"},{"id":"F","text":"Cover coughs with respiratory hygiene practices"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_305014', 'SATA', 'Which interventions help prevent falls for a hospitalized older adult? Select all that apply.', 'Low bed, accessible call light, nonslip footwear, and clear pathways reduce fall risk.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position"},{"id":"B","text":"Ensure the call light is within reach"},{"id":"C","text":"Provide nonslip footwear"},{"id":"D","text":"Keep the room dimly lit at all times"},{"id":"E","text":"Clear clutter from walking paths"},{"id":"F","text":"Leave the client to ambulate alone to build confidence"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Fall prevention', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_305015', 'SATA', 'A client has influenza requiring droplet precautions. Which measures are appropriate? Select all that apply.', 'Droplet precautions require a surgical mask, private room, masking during transport, and hand hygiene; negative pressure is for airborne organisms.', '{"options":[{"id":"A","text":"Wear a surgical mask when within 3 feet of the client"},{"id":"B","text":"Place the client in a private room when possible"},{"id":"C","text":"Have the client wear a mask when transported"},{"id":"D","text":"Use a negative-pressure isolation room"},{"id":"E","text":"Perform hand hygiene before and after contact"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Droplet precautions', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_305016', 'SATA', 'Which nursing responsibilities apply when a client is in physical restraints? Select all that apply.', 'Restraints require a provider order, regular circulation and skin checks, quick-release knots on the frame, and periodic release.', '{"options":[{"id":"A","text":"Obtain a provider order for the restraint"},{"id":"B","text":"Assess skin and circulation at regular intervals"},{"id":"C","text":"Use a quick-release knot that ties to the bed frame"},{"id":"D","text":"Tie the restraint to the movable side rail"},{"id":"E","text":"Release the restraint periodically to check the client"},{"id":"F","text":"Leave the restraint in place indefinitely without reassessment"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Restraints', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_305017', 'SATA', 'Which principles maintain the integrity of a sterile field? Select all that apply.', 'Sterile fields must stay in view, have unsterile borders, be kept above the waist, and remain dry; reaching over contaminates the field.', '{"options":[{"id":"A","text":"Keep the sterile field within your line of vision"},{"id":"B","text":"Consider a 1-inch border around the field unsterile"},{"id":"C","text":"Hold sterile items above waist level"},{"id":"D","text":"Reach across the sterile field to retrieve items"},{"id":"E","text":"Consider any moisture on the field as contamination"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Sterile technique', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_305018', 'SELECT_N', 'Which 3 items are required PPE for a nurse entering the room of a client on contact precautions?', 'Contact precautions require gown, gloves, and hand hygiene; an N95 is for airborne precautions.', '{"options":[{"id":"A","text":"Gown"},{"id":"B","text":"Gloves"},{"id":"C","text":"Hand hygiene before entering"},{"id":"D","text":"N95 respirator"},{"id":"E","text":"Goggles for all care"},{"id":"F","text":"Sterile drape"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_305019', 'TF', 'Hand hygiene is considered the single most effective way to prevent the spread of infection.', 'Hand hygiene is the most effective single measure to reduce transmission of health-care-associated infections.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_305020', 'TF', 'A nurse who believes a prescribed order is unsafe should carry it out first and then question the provider afterward.', 'A nurse must clarify and withhold a questionable order before implementing it, never carry out a potentially unsafe order first.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Order verification', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_305021', 'MATRIX', 'For each condition, click the type of transmission-based precaution required.', 'Measles and TB are airborne; influenza and pertussis are droplet; MRSA is contact.', '{"row_label":"Disease","rows":[{"id":"r1","text":"Measles"},{"id":"r2","text":"Influenza"},{"id":"r3","text":"MRSA wound infection"},{"id":"r4","text":"Pertussis"},{"id":"r5","text":"Tuberculosis"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', NULL, 'Easy', 'Understand', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_305022', 'MATRIX_MR', 'For each PPE item, select all precaution types that routinely require it.', 'Gown and gloves are core to contact precautions, a surgical mask to droplet, and an N95 to airborne.', '{"row_label":"Precaution level","rows":[{"id":"r1","text":"Gown"},{"id":"r2","text":"Surgical mask"},{"id":"r3","text":"N95 respirator"},{"id":"r4","text":"Gloves"}],"columns":[{"id":"c1","text":"Contact"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Airborne"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_305023', 'CLOZE', 'A client with active tuberculosis requires a {1} room, and the nurse must wear a {2} before entering.', 'Airborne precautions for TB require a negative-pressure room and a fitted N95 respirator.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"negative-pressure"},{"id":"c2","text":"positive-pressure"},{"id":"c3","text":"standard"}]},{"id":"b2","choices":[{"id":"c1","text":"fitted N95 respirator"},{"id":"c2","text":"surgical mask"},{"id":"c3","text":"face shield only"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Isolation precautions', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_305024', 'HIGHLIGHT', 'A home-health nurse assesses a client''s home. Highlight the findings that are safety hazards. There are [[loose electrical cords across the walkway]]. The bathroom has [[grab bars installed]]. There is a [[space heater near the curtains]]. The hallway has a [[working smoke detector]]. Medications are [[stored in unlabeled containers]].', 'Loose cords, a heater near curtains, and unlabeled medications are hazards; grab bars and a smoke detector are safety features.', '{"chunks":[{"id":"h1","text":"loose electrical cords across the walkway"},{"id":"h2","text":"grab bars installed"},{"id":"h3","text":"space heater near the curtains"},{"id":"h4","text":"working smoke detector"},{"id":"h5","text":"stored in unlabeled containers"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Tripping hazard.","h2":"Grab bars improve safety.","h3":"Fire hazard.","h4":"This is a safety feature.","h5":"Risk of medication error."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home safety assessment', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_305025', 'BOWTIE', 'A nurse sustains a needlestick from a used needle. Complete the diagram to identify the immediate concern, actions to take, and follow-up to monitor.', 'A needlestick risks bloodborne pathogen exposure; the nurse washes the site, reports immediately, and follows up with testing and prophylaxis assessment.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Wash the site with soap and water"},{"id":"lt2","text":"Report the exposure immediately"},{"id":"lt3","text":"Recap the needle for reuse"},{"id":"lt4","text":"Squeeze until bleeding stops and ignore it"}]},"centre":{"label":"Immediate concern","tokens":[{"id":"ct1","text":"Bloodborne pathogen exposure"},{"id":"ct2","text":"Airborne infection"},{"id":"ct3","text":"Latex allergy"}]},"right":{"label":"Follow-up to monitor","tokens":[{"id":"rt1","text":"Baseline bloodborne pathogen testing"},{"id":"rt2","text":"Post-exposure prophylaxis need"},{"id":"rt3","text":"Daily weight"},{"id":"rt4","text":"Blood glucose"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Needlestick injury', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_305026', 'DRAG_ORDER', 'Place the steps for removing (doffing) personal protective equipment in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Remove gloves"},{"id":"t2","text":"Remove goggles"},{"id":"t3","text":"Remove gown"},{"id":"t4","text":"Remove mask"},{"id":"t5","text":"Perform hand hygiene"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306001', 'MCQ', 'A nurse''s hands are visibly soiled after removing a soiled dressing. Which hand-hygiene method should the nurse use?', 'When hands are visibly soiled, soap and water is required; alcohol rub is only for hands that are not visibly soiled.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Apply alcohol-based hand rub"},{"id":"C","text":"Wipe hands with a dry paper towel"},{"id":"D","text":"Change gloves without washing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Visibly soiled hands must be washed with soap and water.","B":"Incorrect. Alcohol rub is not effective on visibly soiled hands.","C":"Incorrect. This does not remove pathogens.","D":"Incorrect. Hand hygiene is still required."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306002', 'MCQ', 'A client is admitted with active pulmonary tuberculosis. Which type of isolation room should the nurse ensure is used?', 'Active pulmonary TB requires airborne precautions with a negative-pressure room and N95 respirator.', '{"options":[{"id":"A","text":"Airborne isolation with negative-pressure room"},{"id":"B","text":"Droplet isolation with a standard private room"},{"id":"C","text":"Contact isolation only"},{"id":"D","text":"Protective (reverse) isolation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TB requires airborne precautions in a negative-pressure room.","B":"Incorrect. TB is airborne, not droplet.","C":"Incorrect. Contact precautions do not address airborne spread.","D":"Incorrect. Protective isolation is for immunocompromised clients."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306003', 'MCQ', 'When donning personal protective equipment before entering an isolation room, which item should the nurse put on FIRST?', 'The correct donning sequence is gown, mask/respirator, goggles/face shield, then gloves.', '{"options":[{"id":"A","text":"Gown"},{"id":"B","text":"Gloves"},{"id":"C","text":"Goggles"},{"id":"D","text":"Shoe covers"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The gown is donned first, followed by mask, goggles, then gloves.","B":"Incorrect. Gloves are donned last.","C":"Incorrect. Goggles come after the mask.","D":"Incorrect. This is not the correct first step."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE donning', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306004', 'MCQ', 'Before administering a medication, which action best verifies the nurse has the correct client?', 'Two independent client identifiers (e.g., name and date of birth) must be verified before administering medication.', '{"options":[{"id":"A","text":"Check two identifiers such as name and date of birth"},{"id":"B","text":"Ask the roommate to confirm the client''s name"},{"id":"C","text":"Confirm the room and bed number only"},{"id":"D","text":"Call the client''s first name and proceed if they respond"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers are the safety standard.","B":"Incorrect. A roommate is not a reliable identifier.","C":"Incorrect. Room number alone is unreliable.","D":"Incorrect. A confused client may respond to any name."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306005', 'MCQ', 'After giving a subcutaneous injection, how should the nurse dispose of the used needle?', 'Used needles are discarded uncapped, immediately, in a labeled puncture-resistant sharps container.', '{"options":[{"id":"A","text":"Place it uncapped in a puncture-resistant sharps container"},{"id":"B","text":"Recap the needle before discarding it"},{"id":"C","text":"Break the needle off and throw it in the trash"},{"id":"D","text":"Hand the needle to another nurse for disposal"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Uncapped disposal in a sharps container prevents needlestick injury.","B":"Incorrect. Recapping increases needlestick risk.","C":"Incorrect. This is unsafe.","D":"Incorrect. This increases exposure risk."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Sharps disposal', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306006', 'MCQ', 'A nurse discovers a small fire in a client''s trash can. Using the RACE protocol, what is the FIRST action?', 'RACE stands for Rescue, Alarm, Confine, Extinguish — rescue of endangered clients is first.', '{"options":[{"id":"A","text":"Rescue any clients in immediate danger"},{"id":"B","text":"Activate the fire alarm"},{"id":"C","text":"Confine the fire by closing doors"},{"id":"D","text":"Extinguish the fire with an extinguisher"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rescue is the first step of RACE.","B":"Incorrect. Alarm is the second step.","C":"Incorrect. Confine comes after rescue and alarm.","D":"Incorrect. Extinguish is the last step."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Fire safety', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306007', 'MCQ', 'Which action by the nurse best prevents infant abduction on the maternity unit?', 'Matching infant and parent identification bands and never releasing infants to unidentified staff prevent abduction.', '{"options":[{"id":"A","text":"Verify identification bands match before returning the infant to the mother"},{"id":"B","text":"Allow anyone in scrubs to transport the infant"},{"id":"C","text":"Leave the infant unattended in the hallway"},{"id":"D","text":"Post the infant''s full name on the door"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Matching ID bands prevent misidentification and abduction.","B":"Incorrect. Identity must be verified, not assumed from clothing.","C":"Incorrect. This is unsafe.","D":"Incorrect. This is a privacy and security risk."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive', 'Newborn security', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306008', 'MCQ', 'When preparing to transfer a heavy, immobile client from bed to chair, which action protects the nurse from injury?', 'Proper body mechanics, mechanical lifts, and adequate help prevent musculoskeletal injury during transfers.', '{"options":[{"id":"A","text":"Use a mechanical lift and request assistance"},{"id":"B","text":"Lift the client quickly using the back muscles"},{"id":"C","text":"Bend at the waist to reach the client"},{"id":"D","text":"Transfer the client alone to save time"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mechanical lifts and help reduce injury risk.","B":"Incorrect. Using the back causes injury.","C":"Incorrect. Bending at the waist strains the back.","D":"Incorrect. This risks injury to nurse and client."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Safe client handling', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306009', 'MCQ', 'Standard precautions require the nurse to treat which of the following as potentially infectious?', 'Standard precautions treat the blood and body fluids of all clients as potentially infectious, regardless of diagnosis.', '{"options":[{"id":"A","text":"All blood and body fluids from every client"},{"id":"B","text":"Only fluids from clients with a known infection"},{"id":"C","text":"Only fluids from clients in isolation"},{"id":"D","text":"Only visibly bloody fluids"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Standard precautions apply to all clients'' blood and body fluids.","B":"Incorrect. Standard precautions apply to everyone.","C":"Incorrect. This describes transmission-based precautions.","D":"Incorrect. All body fluids are treated as infectious."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306010', 'MCQ', 'A client has a prescribed wrist restraint applied. How often should the nurse assess circulation to the restrained extremity?', 'Restrained extremities require frequent assessment (commonly every 2 hours) for circulation, sensation, and skin integrity.', '{"options":[{"id":"A","text":"At least every 2 hours (per facility policy)"},{"id":"B","text":"Once per shift"},{"id":"C","text":"Only when the client complains"},{"id":"D","text":"Every 12 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Regular assessment protects circulation and skin integrity.","B":"Incorrect. This is too infrequent.","C":"Incorrect. Assessment must be proactive.","D":"Incorrect. This is unsafe."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Restraints', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306011', 'MCQ', 'While setting up a sterile field, the nurse notices the outer inch of the drape. Which statement is correct?', 'The outer 1-inch (2.5 cm) border of a sterile field is considered contaminated and must not hold sterile items.', '{"options":[{"id":"A","text":"The outer 1-inch border of the sterile field is considered contaminated"},{"id":"B","text":"The entire drape including the edges is sterile"},{"id":"C","text":"Only the center is contaminated"},{"id":"D","text":"Sterile fields do not have contaminated zones"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The 1-inch border is treated as non-sterile.","B":"Incorrect. The border is contaminated.","C":"Incorrect. The center is sterile.","D":"Incorrect. The border is always non-sterile."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Sterile technique', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_306012', 'MCQ', 'A client has a Clostridioides difficile infection. Which PPE should the nurse wear when providing direct care?', 'C. difficile requires contact precautions — gown and gloves — plus hand washing with soap and water (spores resist alcohol).', '{"options":[{"id":"A","text":"Gown and gloves"},{"id":"B","text":"N95 respirator only"},{"id":"C","text":"Surgical mask only"},{"id":"D","text":"No PPE is needed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. C. difficile requires contact precautions with gown and gloves.","B":"Incorrect. C. difficile is not airborne.","C":"Incorrect. Contact precautions require gown and gloves.","D":"Incorrect. Contact precautions are required."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Contact precautions', NULL, 'Easy', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_306013', 'TF', 'A nurse caring for a client on airborne precautions for measles should wear an N95 respirator when entering the room.', 'Airborne precautions (measles, TB, varicella) require a fitted N95 respirator or higher.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Respiratory', 'Airborne precautions', NULL, 'Easy', 'Remember', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_306014', 'TF', 'Wearing gloves during client care eliminates the need to perform hand hygiene after glove removal.', 'Hand hygiene is always required after glove removal because gloves can have unseen defects and hands can be contaminated during removal.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_306015', 'SATA', 'Which interventions should the nurse implement to reduce fall risk for a hospitalized older adult? Select all that apply.', 'Low bed, accessible call light, nonskid footwear, and clutter-free floors reduce falls; four raised rails act as a restraint and removing glasses increases risk.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position"},{"id":"B","text":"Ensure the call light is within reach"},{"id":"C","text":"Provide nonskid footwear"},{"id":"D","text":"Keep the floor clear of clutter"},{"id":"E","text":"Raise all four side rails at all times"},{"id":"F","text":"Dim the lights and remove the client''s glasses"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Fall prevention', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_306016', 'SATA', 'Which situations require the nurse to perform hand hygiene? Select all that apply.', 'Hand hygiene is performed before client contact, before aseptic tasks, after body-fluid exposure, and after glove removal — not only when hands appear soiled.', '{"options":[{"id":"A","text":"Before contact with a client"},{"id":"B","text":"After removing gloves"},{"id":"C","text":"After contact with body fluids"},{"id":"D","text":"Before an aseptic procedure"},{"id":"E","text":"Only at the start of the shift"},{"id":"F","text":"Only when hands look dirty"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', NULL, 'Easy', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_306017', 'SATA', 'During a home visit, which findings should the nurse identify as fall hazards for an older adult? Select all that apply.', 'Loose rugs, poor lighting, and cords across walkways are fall hazards; grab bars and nonslip mats are protective.', '{"options":[{"id":"A","text":"Loose throw rugs on the floor"},{"id":"B","text":"Poor lighting in the hallway"},{"id":"C","text":"Electrical cords across the walkway"},{"id":"D","text":"Grab bars installed in the bathroom"},{"id":"E","text":"Nonslip mats in the shower"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Home safety', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_306018', 'SATA', 'Before administering a new antibiotic, which actions related to allergy safety should the nurse take? Select all that apply.', 'Allergy history, the allergy band, and the nature of prior reactions must be verified before administering a new medication.', '{"options":[{"id":"A","text":"Ask the client about known drug allergies"},{"id":"B","text":"Check the allergy band and chart"},{"id":"C","text":"Ask what reaction previous allergies caused"},{"id":"D","text":"Administer the drug first, then ask about allergies"},{"id":"E","text":"Assume no allergies if the chart is blank"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_306019', 'SATA', 'A nurse discovers a medication error. Which actions are appropriate? Select all that apply.', 'The nurse assesses the client, notifies the provider, and files an incident report; errors are never concealed, and the incident report is not referenced in the chart.', '{"options":[{"id":"A","text":"Assess the client for adverse effects"},{"id":"B","text":"Notify the provider"},{"id":"C","text":"Complete an incident report"},{"id":"D","text":"Hide the error to avoid discipline"},{"id":"E","text":"Document the incident report in the client''s chart"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error reporting', NULL, 'Easy', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_306020', 'SELECT_N', 'Which 2 actions are required when caring for a client on droplet precautions for influenza?', 'Droplet precautions require a surgical mask within close range and a private/cohort room; a negative-pressure room and N95 are for airborne precautions.', '{"options":[{"id":"A","text":"Wear a surgical mask when within 6 feet of the client"},{"id":"B","text":"Place the client in a private room or cohort"},{"id":"C","text":"Use a negative-pressure room"},{"id":"D","text":"Wear an N95 respirator for all care"},{"id":"E","text":"No mask is needed for routine care"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Droplet precautions', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_306021', 'MATRIX', 'For each disease, click to indicate the correct type of transmission-based precaution.', 'TB and measles are airborne, influenza is droplet, and MRSA wound infection requires contact precautions.', '{"row_label":"Disease","rows":[{"id":"r1","text":"Tuberculosis"},{"id":"r2","text":"Influenza"},{"id":"r3","text":"MRSA wound infection"},{"id":"r4","text":"Measles"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Transmission-based precautions', NULL, 'Easy', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_306022', 'MATRIX_MR', 'For each precaution type, select all PPE items required for routine direct care.', 'Contact precautions need gloves and gown; airborne precautions need an N95; standard precautions with anticipated splash need gloves and gown.', '{"row_label":"PPE item","rows":[{"id":"r1","text":"Contact precautions"},{"id":"r2","text":"Airborne precautions"},{"id":"r3","text":"Standard precautions (blood exposure expected)"}],"columns":[{"id":"c1","text":"Gloves"},{"id":"c2","text":"Gown"},{"id":"c3","text":"N95 respirator"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c1","c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE selection', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_306023', 'CLOZE', 'When hands are not visibly soiled, the nurse may use {1}, but hands that are visibly soiled must be cleaned with {2}.', 'Alcohol-based rub is appropriate for hands that are not visibly soiled; visibly soiled hands require soap and water.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"alcohol-based hand rub"},{"id":"c2","text":"sterile water"},{"id":"c3","text":"a dry towel"}]},{"id":"b2","choices":[{"id":"c1","text":"soap and water"},{"id":"c2","text":"hand rub only"},{"id":"c3","text":"saline"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Easy', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_306024', 'HIGHLIGHT', 'The nurse enters a client''s room and notes several conditions. Highlight the findings that are safety hazards. The [[bed is in the highest position]]. The [[call light is within reach]]. There is a [[wet spill on the floor]]. The [[side rails are up on both sides for mobility]]. An [[oxygen tank is stored lying on the floor unsecured]].', 'A high bed, wet floor, and unsecured oxygen tank are safety hazards; an accessible call light and two rails for mobility are safe.', '{"chunks":[{"id":"h1","text":"bed is in the highest position"},{"id":"h2","text":"call light is within reach"},{"id":"h3","text":"wet spill on the floor"},{"id":"h4","text":"side rails are up on both sides for mobility"},{"id":"h5","text":"oxygen tank is stored lying on the floor unsecured"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"A high bed increases fall risk.","h2":"This is a safe condition.","h3":"A wet floor is a slip hazard.","h4":"Two side rails for mobility is acceptable.","h5":"An unsecured oxygen tank is a hazard."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Environmental safety', NULL, 'Easy', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_306025', 'BOWTIE', 'A client is placed on contact precautions for a resistant wound infection. Complete the diagram by selecting the precaution type, the actions to take, and the equipment to keep at the door.', 'Contact precautions require donning gown and gloves before entry, hand hygiene on exit, and gowns and gloves stocked at the door.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Don gown and gloves before entering"},{"id":"lt2","text":"Perform hand hygiene on exit"},{"id":"lt3","text":"Enter the room without PPE"},{"id":"lt4","text":"Transport the client freely without cover"}]},"centre":{"label":"Precaution type","tokens":[{"id":"ct1","text":"Contact precautions"},{"id":"ct2","text":"Airborne precautions"},{"id":"ct3","text":"Droplet precautions"}]},"right":{"label":"Equipment at the door","tokens":[{"id":"rt1","text":"Gowns"},{"id":"rt2","text":"Gloves"},{"id":"rt3","text":"N95 respirators"},{"id":"rt4","text":"Negative-pressure monitor"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Isolation precautions', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_306026', 'DRAG_ORDER', 'Place the steps for removing personal protective equipment in the correct order to prevent self-contamination.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Remove gloves"},{"id":"t2","text":"Remove goggles or face shield"},{"id":"t3","text":"Remove gown"},{"id":"t4","text":"Remove mask or respirator"},{"id":"t5","text":"Perform hand hygiene"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE removal', NULL, 'Easy', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP')
ON CONFLICT (item_id) DO NOTHING;
